using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Json;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Security.Principal;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Windows.Forms;

namespace CapriDesktop
{
    internal static class Program
    {
        // Set when she closed while starting twice in a row, so this start moved settings.json aside and kept her keys.
        internal static bool StartedFresh;
        internal const string StartMarker = "starting.on";
        private static string lastCrash;
        private static int lastCrashAt;

        [STAThread]
        private static int Main(string[] args)
        {
            if (args.Length > 0 && args[0] == "--hook") return HuskHook.Run(args.Length > 1 ? args[1] : "");
            if (args.Length == 4 && args[0] == "--release-input") return InputRelease.Watch(args[1], args[2], args[3]);
            try { Native.SetProcessDpiAwarenessContext(new IntPtr(-4)); } catch (EntryPointNotFoundException) { Native.SetProcessDPIAware(); }
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            bool smoke = args.Length >= 2 && args[0] == "--smoke-test";
            if (smoke && !SmokeRun.Worker) return SmokeRun.Run(args);
            SmokeOptions smokeOptions = smoke ? SmokeOptions.Parse(args) : null;
            bool bench = args.Length == 2 && args[0] == "--bench";
            if (args.Length == 1 && args[0] == "--stream") Computer.Streaming = Computer.StreamingAlways = true;
            string identity = WindowsIdentity.GetCurrent().User.Value;
            bool first;
            using (Mutex mutex = new Mutex(true, "Local\\Capri.Desktop." + identity + (smoke ? ".Test.Worker" : bench ? ".Bench" : ""), out first))
            using (EventWaitHandle restore = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\Capri.Restore." + identity + (smoke ? ".Test.Worker" : bench ? ".Bench" : "")))
            using (EventWaitHandle shown = new EventWaitHandle(false, EventResetMode.ManualReset, "Local\\Capri.Shown." + identity + (smoke ? ".Test.Worker" : bench ? ".Bench" : "")))
            {
                if (!first)
                {
                    if (smoke)
                    {
                        Directory.CreateDirectory(args[1]);
                        File.WriteAllText(Path.Combine(args[1], "failure.txt"), "Another smoke test holds Capri's test lock. This run did not start.");
                        return 1;
                    }
                    Native.AllowSetForegroundWindow(-1); shown.Reset(); restore.Set();
                    // A stuck Capri ends herself when she's opened again, and this launch takes her place. One that's fine shows
                    // herself and sends this launch away, so quitting her straight after can't bring her back.
                    if (!Heartbeat.TakeOver(mutex, shown)) return 0;
                    restore.Reset();
                }
                try
                {
                    string data = smoke || bench ? Path.GetFullPath(args[1]) : Packaged.Home(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData));
                    Brain.LogPath = Path.Combine(data, "errors.txt");
                    // Whatever ends her, their own cursor comes back, and a crash goes in errors.txt.
                    AppDomain.CurrentDomain.ProcessExit += delegate { HerCursor.Off(); };
                    AppDomain.CurrentDomain.UnhandledException += delegate(object sender, UnhandledExceptionEventArgs crash) { HerCursor.Off(); Crashed(crash.ExceptionObject as Exception); };
                    RunMark running = smoke || bench ? null : new RunMark(data);
                    if (running != null) running.Recover(null);
                    if (!smoke)
                    {
                        // A crash in a timer or a click is written down and she carries on.
                        Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
                        Application.ThreadException += delegate(object sender, ThreadExceptionEventArgs crash) { Crashed(crash.Exception); };
                        if (!bench) StartedFresh = Starting(data);
                    }
                    else Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);
                    using (Companion app = new Companion(smoke ? Environment.GetEnvironmentVariable("CAPRI_SMOKE_DATA") ?? data : data, restore, shown, smoke, running))
                    {
                        if (smoke) app.StartSmokeTest(data, smokeOptions);
                        if (bench) app.StartBench(data);
                        Application.Run(app);
                        if (running != null) running.Clear();
                        HerCursor.Off();
                        if (smoke && !app.TestFinished)
                        {
                            app.TestFailed = true;
                            if (!File.Exists(Path.Combine(data, "failure.txt"))) File.WriteAllText(Path.Combine(data, "failure.txt"), "Smoke test closed before completion at " + app.TestStep + ".");
                        }
                        return app.TestFailed ? 1 : 0;
                    }
                }
                catch (Exception error)
                {
                    HerCursor.Off();
                    if (smoke) { Directory.CreateDirectory(args[1]); File.WriteAllText(Path.Combine(args[1], "failure.txt"), error.ToString()); return 1; }
                    Crashed(error);
                    Notice.Tell(null, "Capri could not start.\n\n" + error.Message, "Capri", true);
                    return 1;
                }
            }
        }

        // A start that never settled means she closed while starting: a crash, but also Task Manager, an antivirus, a stuck
        // shutdown or the power going off in her first 15 s. Two of those in a row move settings.json aside, the same fix as
        // deleting it, and she starts fresh with her keys kept (JustAxolotl lost theirs to one). True when that happened.
        internal static bool Starting(string data)
        {
            string marker = Path.Combine(data, StartMarker);
            string settings = Path.Combine(data, "settings.json");
            bool fresh = false;
            try
            {
                Directory.CreateDirectory(data);
                // The marker's second line counts the unfinished starts before the one that wrote it. One from before 0.7.6 has none.
                int unfinished = 0;
                if (File.Exists(marker))
                {
                    string[] lines = File.ReadAllLines(marker);
                    int earlier;
                    unfinished = 1 + (lines.Length > 1 && int.TryParse(lines[1], out earlier) && earlier > 0 ? earlier : 0);
                }
                if (unfinished >= 2 && File.Exists(settings))
                {
                    string kept = Path.Combine(data, "settings.crashed.json");
                    if (File.Exists(kept)) File.Delete(kept);
                    File.Move(settings, kept);
                    KeepKeys(kept, settings);
                    fresh = true;
                    unfinished = 0;
                    Brain.Log("startup", -1, "Capri closed while starting twice in a row, so she started with fresh settings and kept your keys. The old ones are in settings.crashed.json.");
                }
                else if (unfinished == 1) Brain.Log("startup", -1, "Capri closed while starting last time. If it happens again, she starts with fresh settings and keeps your keys.");
                File.WriteAllText(marker, DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + Environment.NewLine + unfinished);
            }
            catch (IOException) { }
            catch (UnauthorizedAccessException) { }
            return fresh;
        }

        // A fresh start keeps what can't crash her: her brain and voice keys with what each one is for (model, voice, agent,
        // server), and her own keys to talk, mute, type, hide and go quiet. The rest starts like a new install. Settings that
        // can't be read keep nothing.
        private static void KeepKeys(string crashed, string settings)
        {
            Preferences old;
            try { using (FileStream stream = File.OpenRead(crashed)) old = (Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(stream); }
            catch (Exception) { return; }
            Preferences fresh = new Preferences { Language = Brain.SystemLanguage(System.Globalization.CultureInfo.CurrentUICulture) };
            fresh.VoiceKey = old.VoiceKey; fresh.VoiceId = old.VoiceId; fresh.VoiceModel = old.VoiceModel;
            fresh.AgentId = old.AgentId; fresh.AgentVersion = old.AgentVersion; fresh.AgentPolyglot = old.AgentPolyglot; fresh.AgentPersonality = old.AgentPersonality;
            fresh.TextKey = old.TextKey; fresh.TextModel = old.TextModel;
            fresh.NvidiaKey = old.NvidiaKey; fresh.NvidiaModel = old.NvidiaModel;
            fresh.PaidKey = old.PaidKey; fresh.PaidModel = old.PaidModel;
            // Which tier is picked and that the keys are already split: without them, a MEDIUM Gemini or OpenRouter key would
            // be split again as a paid one, over the MAX key (a Codex review, 2 Nov).
            fresh.Tier = old.Tier; fresh.Tiered = old.Tiered; fresh.NvidiaGlm = old.NvidiaGlm;
            fresh.ServerUrl = old.ServerUrl; fresh.ServerApi = old.ServerApi; fresh.ServerModel = old.ServerModel; fresh.ServerSpeaker = old.ServerSpeaker; fresh.ServerKey = old.ServerKey;
            fresh.AsideUrl = old.AsideUrl; fresh.AsideApi = old.AsideApi; fresh.AsideModel = old.AsideModel; fresh.AsideSpeaker = old.AsideSpeaker; fresh.AsideKey = old.AsideKey;
            // Their provider too, so a fresh start never sends their chats to a brain they moved away from.
            fresh.BrainProvider = old.BrainProvider; fresh.ProviderModel = old.ProviderModel; fresh.ProviderOn = old.ProviderOn;
            fresh.CloudVoice = old.CloudVoice;
            fresh.TalkMods = old.TalkMods; fresh.TalkVk = old.TalkVk; fresh.MuteMods = old.MuteMods; fresh.MuteVk = old.MuteVk;
            fresh.TypeMods = old.TypeMods; fresh.TypeVk = old.TypeVk; fresh.HideMods = old.HideMods; fresh.HideVk = old.HideVk;
            fresh.QuietMods = old.QuietMods; fresh.QuietVk = old.QuietVk;
            fresh.PushMods = old.PushMods; fresh.PushVk = old.PushVk;
            fresh.GameMods = old.GameMods; fresh.GameVk = old.GameVk; fresh.GameSpots = old.GameSpots;
            try { using (FileStream stream = File.Create(settings)) new DataContractJsonSerializer(typeof(Preferences)).WriteObject(stream, fresh); }
            catch (Exception) { try { File.Delete(settings); } catch (Exception) { } }
        }

        // A crash goes in errors.txt: what it was and where in her code, so Copy error details shows it.
        internal static void Crashed(Exception error)
        {
            if (error == null) return;
            while (error.InnerException != null) error = error.InnerException;
            string what = error.GetType().Name + ": " + error.Message;
            lock (typeof(Program))
            {
                if (what == lastCrash && unchecked(Environment.TickCount - lastCrashAt) < 60000) return;
                lastCrash = what;
                lastCrashAt = Environment.TickCount;
            }
            Brain.Log("crash", -1, what);
            int shown = 0;
            foreach (string frame in (error.StackTrace ?? "").Split('\n'))
            {
                string at = frame.Trim();
                if (at.Length == 0) continue;
                Brain.Log("crash", -1, at);
                if (++shown == 4) break;
            }
            // Out of memory and drawing failures can mean she ran out of Windows' drawing objects rather than memory, so they
            // also say what she holds.
            if (error is OutOfMemoryException || error is System.Runtime.InteropServices.ExternalException) Brain.Log("crash", -1, "She holds " + WindowUse.Read() + ".");
        }
    }

    internal sealed class RunMark
    {
        internal const string Marker = "running.on";
        internal const string Notice = "Capri closed unexpectedly last time. If it keeps happening, right-click her > Help > Copy error details and send it to us.";
        internal static Func<DateTime, DateTime, Record[]> Events = ReadEvents;
        private readonly string file, log, version, exe;
        private readonly int pid;
        private readonly DateTime start;
        private bool ended;
        private int notice, recovering;

        internal sealed class Record
        {
            internal DateTime At;
            internal int Id;
            internal string Source, Text, Name, Pid, Module, Code, Error;
        }

        internal RunMark(string data)
        {
            file = Path.Combine(data, Marker);
            log = Path.Combine(data, "errors.txt");
            using (Process own = Process.GetCurrentProcess()) { pid = own.Id; start = own.StartTime.ToUniversalTime(); }
            version = Assembly.GetExecutingAssembly().GetName().Version.ToString(3);
            exe = Path.GetFileName(Application.ExecutablePath);
        }

        internal void Mark()
        {
            lock (this)
            {
                if (ended) return;
                try
                {
                    Directory.CreateDirectory(Path.GetDirectoryName(file));
                    File.WriteAllLines(file, new[] { pid.ToString(System.Globalization.CultureInfo.InvariantCulture), start.ToString("o"), version, exe });
                }
                catch (Exception error) { Note("Couldn't write her running marker: " + Short(error.Message, 180)); }
            }
        }

        internal void Clear()
        {
            lock (this)
            {
                ended = true;
                try { File.Delete(file); }
                catch (Exception error) { Note("Couldn't remove her running marker: " + Short(error.Message, 180)); }
            }
        }

        internal bool TakeNotice() { return Interlocked.Exchange(ref notice, 0) != 0; }

        internal void Recover(Action done)
        {
            try
            {
                if (Interlocked.Exchange(ref recovering, 1) != 0) { if (done != null) done(); return; }
                if (!File.Exists(file)) { if (done != null) done(); return; }
                string[] lines = File.ReadAllLines(file);
                int oldPid;
                DateTime oldStart;
                DateTime found = DateTime.UtcNow;
                if (lines.Length < 3 || !int.TryParse(lines[0], out oldPid) || oldPid <= 0
                    || !DateTime.TryParseExact(lines[1], "o", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.RoundtripKind, out oldStart)
                    || oldStart.ToUniversalTime() > found)
                {
                    Note("Couldn't read her last running marker.");
                    Forget(lines);
                    if (done != null) done();
                    return;
                }
                oldStart = oldStart.ToUniversalTime();
                string oldVersion = Short(lines[2], 40), oldExe = lines.Length > 3 ? Path.GetFileName(lines[3]) : exe;
                Func<DateTime, DateTime, Record[]> read = Events;
                ThreadPool.QueueUserWorkItem(delegate
                {
                    bool reported = false;
                    try
                    {
                        string earlier = "";
                        try { if (CrashLogged(oldStart, found, oldPid, oldVersion)) { reported = true; return; } }
                        catch (Exception error) { earlier = " Couldn't check her earlier crash log: " + Short(error.Message, 180) + "."; }
                        DateTime closed;
                        string why = Windows(read, oldStart, found, oldPid, oldExe, out closed);
                        string when = closed == DateTime.MinValue
                            ? "; started " + oldStart.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss") + ", found " + found.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss") + ", ran up to " + Seconds(found - oldStart) + " s"
                            : " around " + closed.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss") + " after about " + Seconds(closed - oldStart) + " s; started " + oldStart.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss");
                        reported = Note("Capri v" + oldVersion + " (PID " + oldPid + ") closed unexpectedly" + when + ". " + why + earlier);
                        Interlocked.Exchange(ref notice, 1);
                    }
                    catch (Exception error)
                    {
                        reported = Note("Capri v" + oldVersion + " (PID " + oldPid + ") closed unexpectedly; started " + oldStart.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss")
                            + ", found " + found.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss") + ", ran up to " + Seconds(found - oldStart) + " s. Couldn't check Windows' crash log: " + Short(error.Message, 180));
                        Interlocked.Exchange(ref notice, 1);
                    }
                    finally { if (reported) Forget(lines); try { if (done != null) done(); } catch (Exception) { } }
                });
            }
            catch (Exception error)
            {
                Note("Couldn't read her last running marker: " + Short(error.Message, 180));
                try { if (done != null) done(); } catch (Exception) { }
            }
        }

        private bool Note(string line)
        {
            try { return Brain.LogAt(log, "closed", -1, line); }
            catch (Exception) { }
            return false;
        }

        private void Forget(string[] old)
        {
            lock (this)
            {
                try { if (File.Exists(file) && string.Join("\n", File.ReadAllLines(file)) == string.Join("\n", old)) File.Delete(file); }
                catch (Exception error) { Note("Couldn't remove her last running marker: " + Short(error.Message, 180)); }
            }
        }

        private bool CrashLogged(DateTime from, DateTime to, int oldPid, string oldVersion)
        {
            string[] lines;
            lock (typeof(Brain))
            {
                if (!File.Exists(log)) return false;
                lines = File.ReadAllLines(log);
            }
            string report = "Capri v" + oldVersion + " (PID " + oldPid + ") closed unexpectedly", began = "started " + from.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss");
            from = from.AddTicks(-(from.Ticks % TimeSpan.TicksPerSecond));
            foreach (string line in lines)
            {
                DateTime at;
                if (line.Length >= 19
                    && DateTime.TryParseExact(line.Substring(0, 19), "yyyy-MM-dd HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AssumeLocal, out at)
                    && at.ToUniversalTime() >= from && at.ToUniversalTime() <= to
                    // Only this close's own report counts: a crash she caught and carried on from earlier in the run says
                    // nothing about what ended her.
                    && line.Contains(" | closed | ") && line.Contains(report) && line.Contains(began)) return true;
            }
            return false;
        }

        private static string Seconds(TimeSpan elapsed) { return Math.Max(0, (long)elapsed.TotalSeconds).ToString(System.Globalization.CultureInfo.InvariantCulture); }
        private static string Short(string text, int cap)
        {
            string line = Regex.Replace(text ?? "", @"\s+", " ").Trim();
            return line.Length > cap ? line.Substring(0, cap) : line;
        }

        private static string Windows(Func<DateTime, DateTime, Record[]> read, DateTime from, DateTime to, int pid, string exe, out DateTime closed)
        {
            closed = DateTime.MinValue;
            Record[] records = null;
            Exception failed = null;
            Thread reader = new Thread(delegate()
            {
                try { records = read(from, to); }
                catch (Exception error) { failed = error; }
            }) { IsBackground = true };
            reader.Start();
            if (!reader.Join(10000)) return "Windows' crash log did not answer within 10 s.";
            if (failed != null) return "Couldn't read Windows' Application log: " + failed.GetType().Name + ": " + Short(failed.Message, 180) + ".";
            Record app = null, runtime = null, report = null;
            if (records != null)
                for (int i = 0; i < records.Length && i < 64; i++)
                {
                    Record record = records[i];
                    if (record == null || record.At < from || record.At > to || !Matches(record, pid, exe)) continue;
                    if (record.Source == "Application Error" && record.Id == 1000 && (app == null || record.At > app.At)) app = record;
                    if (record.Source == ".NET Runtime" && record.Id == 1026 && (runtime == null || record.At > runtime.At)) runtime = record;
                    if (record.Source == "Windows Error Reporting" && record.Id == 1001 && (report == null || record.At > report.At)) report = record;
                }
            if (app == null && runtime == null && report == null) return "Windows has no crash record, so something ended her from outside, like an antivirus, Task Manager or the PC losing power.";
            System.Collections.Generic.List<string> parts = new System.Collections.Generic.List<string>();
            if (app != null)
            {
                closed = app.At;
                string module = app.Module, code = app.Code;
                if (string.IsNullOrEmpty(module)) module = Regex.Match(app.Text ?? "", @"Faulting module name:\s*([^,\r\n]+)", RegexOptions.IgnoreCase).Groups[1].Value;
                if (string.IsNullOrEmpty(code)) code = Regex.Match(app.Text ?? "", @"Exception code:\s*(0x[0-9a-f]+|[0-9a-f]+)", RegexOptions.IgnoreCase).Groups[1].Value;
                parts.Add("Application Error: module " + Short(string.IsNullOrEmpty(module) ? "unknown" : module, 100) + "; exception " + Short(string.IsNullOrEmpty(code) ? "unknown" : code, 40) + ".");
            }
            if (runtime != null)
            {
                if (closed == DateTime.MinValue) closed = runtime.At;
                parts.Add(".NET Runtime: " + Stack(runtime.Text));
            }
            if (report != null && parts.Count == 0) { closed = report.At; parts.Add("Windows Error Reporting recorded the close."); }
            foreach (Record record in new[] { app, runtime, report })
                if (record != null && !string.IsNullOrEmpty(record.Error)) parts.Add("Couldn't read the event's message: " + Short(record.Error, 180) + ".");
            return string.Join(" ", parts.ToArray());
        }

        private static bool Matches(Record record, int pid, string exe)
        {
            if (string.IsNullOrEmpty(exe)) return false;
            string text = record.Text ?? "";
            if (!string.IsNullOrEmpty(record.Name))
            {
                if (!string.Equals(Path.GetFileName(record.Name), exe, StringComparison.OrdinalIgnoreCase)) return false;
            }
            else if (!Regex.IsMatch(text, @"(?<![\w.-])" + Regex.Escape(exe) + @"(?![\w.-])", RegexOptions.IgnoreCase)) return false;
            string value = record.Pid;
            if (string.IsNullOrEmpty(value)) value = Regex.Match(text, @"\b(?:Faulting process id|Process\s*ID)\s*:\s*(0x[0-9a-f]+|\d+)", RegexOptions.IgnoreCase).Groups[1].Value;
            if (string.IsNullOrEmpty(value)) return true;
            long found;
            bool hex = value.StartsWith("0x", StringComparison.OrdinalIgnoreCase);
            return long.TryParse(hex ? value.Substring(2) : value, hex ? System.Globalization.NumberStyles.HexNumber : System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out found) && found == pid;
        }

        private static string Stack(string text)
        {
            System.Collections.Generic.List<string> frames = new System.Collections.Generic.List<string>();
            string exception = "";
            foreach (string raw in (text ?? "").Split('\n'))
            {
                string line = raw.Trim();
                if (line.StartsWith("Exception Info:", StringComparison.OrdinalIgnoreCase)) exception = Short(line, 180) + " | ";
                if (line.StartsWith("at ", StringComparison.OrdinalIgnoreCase) && frames.Count < 3) frames.Add(Short(line, 180));
            }
            if (frames.Count > 0) return exception + string.Join(" | ", frames.ToArray());
            foreach (string raw in (text ?? "").Split('\n'))
            {
                string line = raw.Trim();
                if (line.Length == 0 || line.StartsWith("Application:", StringComparison.OrdinalIgnoreCase) || line.StartsWith("Framework Version:", StringComparison.OrdinalIgnoreCase)) continue;
                frames.Add(Short(line, 180));
                if (frames.Count == 3) break;
            }
            return frames.Count == 0 ? "Windows recorded the close." : string.Join(" | ", frames.ToArray());
        }

        private static string Field(string xml, string name)
        {
            return WebUtility.HtmlDecode(Regex.Match(xml, @"<Data\s+Name=['""]" + Regex.Escape(name) + @"['""]>([\s\S]*?)</Data>").Groups[1].Value);
        }

        // One read of Windows' event log that waits through its timeouts. On a slow PC EvtNext gives up with ERROR_TIMEOUT and
        // EventLogReader throws a plain EventLogException in Windows' own language, so only its type tells; the query stays
        // good and the next read carries on. A tester's 0.8.3 log lost all three of its crash records that way. Any other
        // failure comes straight through, and a timeout that lasts the whole budget comes through as the last one.
        internal static T Read<T>(Func<TimeSpan, T> read, TimeSpan budget)
        {
            Stopwatch clock = Stopwatch.StartNew();
            System.Diagnostics.Eventing.Reader.EventLogException last = null;
            do
            {
                TimeSpan left = budget - clock.Elapsed;
                try { return read(TimeSpan.FromMilliseconds(Math.Max(1, Math.Min(1000, left.TotalMilliseconds)))); }
                catch (System.Diagnostics.Eventing.Reader.EventLogException error)
                {
                    if (error.GetType() != typeof(System.Diagnostics.Eventing.Reader.EventLogException)) throw;
                    last = error;
                }
            } while (clock.Elapsed < budget);
            throw last;
        }

        private static Record[] ReadEvents(DateTime from, DateTime to)
        {
            string query = "*[System[((Provider[@Name='Application Error'] and EventID=1000) or (Provider[@Name='.NET Runtime'] and EventID=1026) or (Provider[@Name='Windows Error Reporting'] and EventID=1001)) and TimeCreated[@SystemTime>='"
                + from.ToString("o", System.Globalization.CultureInfo.InvariantCulture) + "' and @SystemTime<='" + to.ToString("o", System.Globalization.CultureInfo.InvariantCulture) + "']]]";
            System.Diagnostics.Eventing.Reader.EventLogQuery search = new System.Diagnostics.Eventing.Reader.EventLogQuery("Application", System.Diagnostics.Eventing.Reader.PathType.LogName, query) { ReverseDirection = true };
            System.Collections.Generic.List<Record> records = new System.Collections.Generic.List<Record>();
            // The lookup runs off the UI thread after she starts, so it can wait 8 s in all, and Windows() gives it 10.
            TimeSpan budget = TimeSpan.FromSeconds(8);
            Stopwatch clock = Stopwatch.StartNew();
            using (System.Diagnostics.Eventing.Reader.EventLogReader reader = new System.Diagnostics.Eventing.Reader.EventLogReader(search))
                for (int i = 0; i < 64 && clock.Elapsed < budget; i++)
                    using (System.Diagnostics.Eventing.Reader.EventRecord record = Read<System.Diagnostics.Eventing.Reader.EventRecord>(reader.ReadEvent, budget - clock.Elapsed))
                    {
                        if (record == null) break;
                        if (!record.TimeCreated.HasValue) continue;
                        string xml = record.ToXml(), text, error = null;
                        try { text = record.FormatDescription(); }
                        catch (Exception failed) { text = WebUtility.HtmlDecode(Regex.Replace(xml, @"<[^>]+>", "\n")); error = failed.Message; }
                        records.Add(new Record { At = record.TimeCreated.Value.ToUniversalTime(), Id = record.Id, Source = record.ProviderName, Text = text,
                            Name = Field(xml, record.Id == 1001 ? "P1" : "AppName"), Pid = Field(xml, "ProcessId"), Module = Field(xml, "ModuleName"), Code = Field(xml, "ExceptionCode"), Error = error });
                    }
            return records.ToArray();
        }
    }

    // How many of Windows' drawing objects and how much memory she holds, for the lines a freeze leaves in errors.txt. A window
    // out of GDI or USER objects (10,000 of each) draws only part of itself and stops, so the numbers show if that's why.
    internal sealed class WindowUse
    {
        internal int Gdi = -1, User = -1, Handles = -1;
        internal long Private = -1, Working = -1;

        [DllImport("user32.dll")] private static extern int GetGuiResources(IntPtr process, int flags);

        internal static WindowUse Read()
        {
            WindowUse use = new WindowUse();
            try
            {
                using (Process own = Process.GetCurrentProcess())
                {
                    use.Gdi = GetGuiResources(own.Handle, 0);
                    use.User = GetGuiResources(own.Handle, 1);
                    use.Handles = own.HandleCount;
                    use.Private = own.PrivateMemorySize64;
                    use.Working = own.WorkingSet64;
                }
            }
            catch (Exception) { }
            return use;
        }

        public override string ToString()
        {
            return "GDI " + Gdi + ", USER " + User + ", handles " + Handles + ", private " + (Private < 0 ? -1 : Private >> 20) + " MB, working set " + (Working < 0 ? -1 : Working >> 20) + " MB";
        }
    }

    // Her window answers a ping four times a second. When it stops, something has her UI thread stuck, and she can't be clicked,
    // dragged or quit (Mika, 1 Nov: "SHES STUCK ON MMY SCREEN", "QUITTING DOESNT WORK"). Ten seconds stuck goes in errors.txt
    // with where in her code it's stuck. Stuck and opened again, stuck closing, or stuck for a minute, she ends herself, and her
    // input helper lets go of any key or button she held. A minute's freeze starts her again, at most once every ten minutes.
    // A shorter stall, from 2 s, goes in once it's over with what held her up, at most once a minute (Neco Arc, 3 Nov: "she
    // lags a lot", "her avatar freezes").
    internal sealed class Heartbeat
    {
        internal int StallAfter = 2000, StallSpacing = 60000, LogAfter = 10000, EndAfter = 60000, CloseFor = 15000, ReopenAfter = 2000, Grace = 2000, SettleAfter = 15000;
        // How long a second launch waits for a stuck Capri to end, before it leaves her be. Writing down where she's stuck
        // can take her about 10 s, and a stalled Quit 15 s.
        internal const int Handover = 20000;
        private const string Restarted = "CAPRI_RESTARTED";
        private readonly Control window;
        private readonly EventWaitHandle reopened;
        private readonly Thread ui;
        private readonly Stopwatch clock = Stopwatch.StartNew();
        private volatile bool stopped;
        private int sent, answered;
        private long sentAt, closingAt = -1;
        // What she was up to, for the line in errors.txt. Read on the heartbeat's thread, so it only reads fields.
        internal Func<string> Doing;
        // What she holds of Windows' drawing objects and memory. The smoke test makes up its own.
        internal Func<WindowUse> Use = WindowUse.Read;
        internal Action<string> Note = delegate(string line) { Brain.Log("frozen", -1, line); };
        // Ends her, starting her again when asked. The smoke test swaps it for one that only counts.
        internal Action<bool> End = Stop;
        internal Action Replaced;

        internal Heartbeat(Control window, EventWaitHandle reopened)
        {
            this.window = window;
            this.reopened = reopened;
            ui = Thread.CurrentThread;
        }

        internal void Start()
        {
            Thread beat = new Thread(Watch);
            beat.IsBackground = true;
            beat.Name = "Capri heartbeat";
            // It wakes for a moment four times a second, so it can sit above a busy game and still see her stuck.
            beat.Priority = ThreadPriority.Highest;
            beat.Start();
        }

        internal void Halt() { stopped = true; }

        // Quit was pressed or her window got closed. Whatever holds her up after this, she's gone in CloseFor.
        internal void Closing() { Interlocked.CompareExchange(ref closingAt, clock.ElapsedMilliseconds, -1); }

        private void Ping(long now)
        {
            int number = Volatile.Read(ref sent) + 1;
            try { window.BeginInvoke(new Action(delegate { Volatile.Write(ref answered, number); })); }
            catch (InvalidOperationException) { return; }
            Interlocked.Exchange(ref sentAt, now);
            Volatile.Write(ref sent, number);
        }

        // Nothing in here may take her down: a heartbeat that breaks just stops.
        private void Watch()
        {
            try { Beat(); }
            catch (Exception error) { stopped = true; Noted("Her heartbeat stopped: " + error.GetType().Name + ": " + error.Message); }
        }

        private void Beat()
        {
            long last = clock.ElapsedMilliseconds, frozeAt = -1, stalledAt = -1, stallNoted = -StallSpacing;
            string stall = null;
            while (true)
            {
                Thread.Sleep(250);
                if (stopped) return;
                long now = clock.ElapsedMilliseconds;
                // A PC waking from sleep jumps a long way at once, and the ping waiting counts from then.
                if (now - last > 5000) Interlocked.Exchange(ref sentAt, now);
                last = now;
                if (Debugger.IsAttached) continue;
                long closing = Interlocked.Read(ref closingAt);
                if (closing >= 0 && now - closing >= CloseFor)
                {
                    Noted("She was still closing " + (now - closing) / 1000 + " s after Quit, so she ended herself." + Where(ui));
                    Ended(false);
                    return;
                }
                if (Volatile.Read(ref answered) == Volatile.Read(ref sent))
                {
                    if (frozeAt >= 0) Noted("Her window answered again after " + (now - frozeAt) / 1000 + " s.");
                    else if (stall != null) Noted("Her window didn't answer for " + ((now - stalledAt) / 1000.0).ToString("0.0", System.Globalization.CultureInfo.InvariantCulture) + " s" + stall);
                    frozeAt = stalledAt = -1;
                    stall = null;
                    Ping(now);
                    continue;
                }
                long stuck = now - Interlocked.Read(ref sentAt);
                if (stuck >= LogAfter && frozeAt < 0)
                {
                    frozeAt = Interlocked.Read(ref sentAt);
                    Noted("Her window stopped answering for " + stuck / 1000 + " s" + Said() + Where(ui));
                }
                // Read while it's held up, so the line says what held it, and written with how long once it answers.
                if (stuck >= StallAfter && stalledAt < 0 && frozeAt < 0)
                {
                    stalledAt = Interlocked.Read(ref sentAt);
                    if (now - stallNoted >= StallSpacing) { stallNoted = now; stall = Said() + Where(ui); }
                }
                // A start is left be: a window that never answered, or is in its first 15 s, is still starting, and ending it
                // then would count as a start that never finished (two in a row move settings.json aside).
                if (stuck >= ReopenAfter && Volatile.Read(ref answered) > 0 && now >= SettleAfter && Reopened())
                {
                    // Opened again while stuck. A window that answers after all gets it back to show herself as usual.
                    Stopwatch grace = Stopwatch.StartNew();
                    while (grace.ElapsedMilliseconds < Grace && Volatile.Read(ref answered) != Volatile.Read(ref sent)) Thread.Sleep(50);
                    if (Volatile.Read(ref answered) == Volatile.Read(ref sent)) { try { reopened.Set(); } catch (ObjectDisposedException) { } continue; }
                    Replace(clock.ElapsedMilliseconds - Interlocked.Read(ref sentAt));
                    return;
                }
                // A window that never answered at all is still starting, and starting again would only get stuck again.
                if (stuck >= EndAfter && Volatile.Read(ref answered) > 0)
                {
                    bool again = MayRestart();
                    Noted("Her window was stuck for " + stuck / 1000 + " s, so she " + (again ? "started again." : "closed. She froze twice in ten minutes, so she didn't start again."));
                    Ended(again);
                    return;
                }
            }
        }

        // ", on a job. GDI 140, USER 360, ...": what she was doing and what she holds, read on this thread.
        private string Said()
        {
            Func<string> doing = Doing;
            string what = doing == null ? "" : doing();
            return (what.Length == 0 ? ". " : ", " + what + ". ") + Use() + ".";
        }

        // Her window can be closed and the signal gone by the time a quit's last ping goes unanswered.
        private bool Reopened()
        {
            try { return reopened != null && reopened.WaitOne(0); }
            catch (ObjectDisposedException) { return false; }
        }

        // errors.txt is written on a thread of its own, so a stuck file can't hold up the rest.
        private void Noted(string line)
        {
            Action<string> note = Note;
            Thread writer = new Thread(delegate() { note(line); });
            writer.IsBackground = true;
            // Level with the heartbeat, so a game on every core can't hold it up while she's lowered.
            writer.Priority = ThreadPriority.Highest;
            writer.Start();
            writer.Join(2000);
        }

        private void Ended(bool again)
        {
            stopped = true;
            Action<bool> end = End;
            end(again);
        }

        internal void Replace(long stuck)
        {
            Noted("a stuck Capri was ended when you opened her again. She was stuck for " + stuck / 1000 + " s.");
            try { if (Replaced != null) Replaced(); } catch (Exception) { }
            Ended(false);
        }

        // Where her UI thread is stuck, read by pausing it for a moment on a thread of its own. Empty if it can't be read.
        internal static string Where(Thread ui)
        {
            StackTrace trace = null;
            Thread reader = new Thread(delegate()
            {
                bool paused = false;
#pragma warning disable 618
                try
                {
                    ui.Suspend();
                    paused = true;
                    trace = new StackTrace(ui, false);
                }
                catch (Exception) { }
                finally { if (paused) { try { ui.Resume(); } catch (Exception) { } } }
#pragma warning restore 618
            });
            reader.IsBackground = true;
            reader.Priority = ThreadPriority.Highest;
            reader.Start();
            if (!reader.Join(3000) || trace == null) return "";
            // The two frames on top say what it waits on, and her own code under them says what asked.
            System.Collections.Generic.List<string> frames = new System.Collections.Generic.List<string>();
            int ours = 0;
            for (int i = 0; i < trace.FrameCount && ours < 4; i++)
            {
                MethodBase method = trace.GetFrame(i).GetMethod();
                if (method == null) continue;
                Type type = method.DeclaringType;
                bool mine = type != null && type.Namespace == typeof(Heartbeat).Namespace;
                if (!mine && i >= 2) continue;
                if (mine) ours++;
                frames.Add((type == null ? "" : type.Name + ".") + method.Name);
            }
            return frames.Count == 0 ? "" : " Stuck at: " + string.Join(" < ", frames.ToArray());
        }

        private static bool MayRestart()
        {
            string was = Environment.GetEnvironmentVariable(Restarted);
            long ticks;
            return was == null || !long.TryParse(was, out ticks) || DateTime.UtcNow.Ticks - ticks > TimeSpan.FromMinutes(10).Ticks;
        }

        private static void Stop(bool again)
        {
            HerCursor.Off();
            if (again)
            {
                // Over a game she runs below normal, and a copy started from her would start there too and stay there.
                try { using (Process own = Process.GetCurrentProcess()) own.PriorityClass = ProcessPriorityClass.Normal; }
                catch (Exception) { }
                try
                {
                    System.Collections.Generic.List<string> passed = new System.Collections.Generic.List<string>();
                    string[] given = Environment.GetCommandLineArgs();
                    for (int i = 1; i < given.Length; i++) passed.Add(given[i].IndexOf(' ') >= 0 ? "\"" + given[i] + "\"" : given[i]);
                    ProcessStartInfo start = new ProcessStartInfo(Packaged.Launcher(Application.ExecutablePath), string.Join(" ", passed.ToArray())) { UseShellExecute = false };
                    start.EnvironmentVariables[Restarted] = DateTime.UtcNow.Ticks.ToString(System.Globalization.CultureInfo.InvariantCulture);
                    Process.Start(start);
                }
                catch (Exception error) { Brain.Log("frozen", -1, "She couldn't start again: " + error.Message); }
            }
            Process.GetCurrentProcess().Kill();
        }

        // A second launch waits here for a stuck Capri to end herself, then takes her place. One that's fine shows herself and
        // says so, and this launch leaves her be. Shown comes first, so it wins over a Quit that lands at the same moment.
        internal static bool TakeOver(Mutex held, WaitHandle shown)
        {
            try { return WaitHandle.WaitAny(new WaitHandle[] { shown, held }, Handover) == 1; }
            catch (AbandonedMutexException) { return true; }
        }
    }

