        [DataMember] public string Vault;

        // A new install: she starts in the PC's own language when she speaks it, and with her tuned voice.
        internal static Preferences Fresh()
        {
            Preferences fresh = new Preferences { Language = Brain.SystemLanguage(System.Globalization.CultureInfo.CurrentUICulture) };
            fresh.Tune();
            return fresh;
        }

        // Her voice as Lachy retuned it (31 Oct): 80% volume, pitch +2, 1.2x, robot and glitch left Off, and her voice layers off
        // with their sliders at their defaults. Pitch, speed, volume and layers go for every voice.
        internal void Tune()
        {
            Volume = 80;
            VoicePitch = 2;
            VoiceSpeed = 120;
            VoiceLayers = false;
            LayerPitch1 = VoiceFx.Layering.HigherPitch;
            LayerDelay1 = VoiceFx.Layering.Behind;
            LayerPitch2 = VoiceFx.Layering.LowerPitch;
            LayerDelay2 = VoiceFx.Layering.Behind;
            VoiceTuned = true;
            VoiceRetuned = true;
        }

        // Settings from before her tuned voice get it once if every voice slider is still where it started (Layer 1 started at
        // +1.5); 0.7.7's unchanged tuned voice gets the retune once too. Anyone who moved one keeps theirs.
        internal void TuneOnce()
        {
            if (VoiceRetuned) return;
            bool untouched = !VoiceTuned && Volume == 100 && VoicePitch == 0 && VoiceSpeed == 100 && VoiceRobot == 0 && VoiceGlitch == 0 && HdRobot == 0 && HdVoiceGlitch == 0 && !VoiceLayers
                && (LayerPitch1 == 1.5 || LayerPitch1 == VoiceFx.Layering.HigherPitch) && LayerDelay1 == VoiceFx.Layering.Behind && LayerPitch2 == VoiceFx.Layering.LowerPitch && LayerDelay2 == VoiceFx.Layering.Behind;
            bool tuned = VoiceTuned && Volume == 80 && VoicePitch == 3 && VoiceSpeed == 120 && VoiceRobot == 0 && VoiceGlitch == 0 && HdRobot == 0 && HdVoiceGlitch == 0 && VoiceLayers
                && LayerPitch1 == VoiceFx.Layering.HigherPitch && LayerDelay1 == VoiceFx.Layering.Behind && LayerPitch2 == VoiceFx.Layering.LowerPitch && LayerDelay2 == VoiceFx.Layering.Behind;
            if (untouched || tuned) Tune();
            VoiceTuned = true;
            VoiceRetuned = true;
        }

        [OnDeserializing]
        private void Defaults(StreamingContext context)
        {
            VoiceSpeed = 100;
            MicLoudness = 100;
            HdRobot = VoiceFx.HdRobotDefault;
            LayerPitch1 = VoiceFx.Layering.HigherPitch;
            LayerDelay1 = VoiceFx.Layering.Behind;
            LayerPitch2 = VoiceFx.Layering.LowerPitch;
            LayerDelay2 = VoiceFx.Layering.Behind;
            Size = 240;
            Motion = true;
            OnTop = true;
            Recall = 8;
            Remembers = true;
            Volume = 100;
            Sounds = 60;
            SleepAfter = 120;
            BubbleTime = 1;
            TalkMods = 3;
            TalkVk = 0x56;
            MuteMods = 3;
            MuteVk = 0x4E;
            TypeMods = 3;
            TypeVk = 0x54;
            HideMods = 3;
            HideVk = 0x48;
            QuietMods = 3;
            QuietVk = 0x50;
            GameMods = 3;
            GameVk = 0x47;
            WanderPace = 1;
            PopPace = 1;
            PerchFps = 30;
            PowerSaver = 1;
            MainframeSize = 0;
            CheckIns = true;
            CareWater = CareStretch = CareLate = CareMeal = CareGame = CareBored = true;
            CareWaterMinutes = CareBoredMinutes = 60;
            CareStretchMinutes = 90;
            CareEyesMinutes = 25;
            CareLateHour = 1;
            CareMealMinutes = 360;
            CareGameMinutes = 120;
            CaughtUp = true;
            FollowUps = true;
            WatchMemory = WatchAlong.DefaultLines;
        }

        internal static int FrameSize(int size)
        {
            return size == 100 || size == 125 || size == 150 || size == 175 || size == 200 ? size : 0;
        }

        [OnDeserialized]
        private void Loaded(StreamingContext context) { MainframeSize = FrameSize(MainframeSize); MainframeColours = Neon.ClampLook(MainframeColours); MicLoudness = MicMix.Level(MicLoudness); }

        internal bool CareOn(CareKind kind)
        {
            switch (kind)
            {
                case CareKind.Water: return CareWater;
                case CareKind.Stretch: return CareStretch;
                case CareKind.Eyes: return CareEyes;
                case CareKind.Late: return CareLate;
                case CareKind.Meal: return CareMeal;
                case CareKind.Game: return CareGame;
                default: return CareBored;
            }
        }

        internal int CareTime(CareKind kind)
        {
            switch (kind)
            {
                case CareKind.Water: return CareWaterMinutes > 0 ? CareWaterMinutes : 60;
                case CareKind.Stretch: return CareStretchMinutes > 0 ? CareStretchMinutes : 90;
                case CareKind.Eyes: return CareEyesMinutes > 0 ? CareEyesMinutes : 25;
                case CareKind.Late: return CareLateHour >= 0 && CareLateHour < 24 ? CareLateHour : 1;
                case CareKind.Meal: return CareMealMinutes > 0 ? CareMealMinutes : 360;
                case CareKind.Game: return CareGameMinutes > 0 ? CareGameMinutes : 120;
                default: return CareBoredMinutes > 0 ? CareBoredMinutes : 60;
            }
        }

        internal void SetCare(CareKind kind, bool on, int time)
        {
            switch (kind)
            {
                case CareKind.Water: CareWater = on; CareWaterMinutes = time; break;
                case CareKind.Stretch: CareStretch = on; CareStretchMinutes = time; break;
                case CareKind.Eyes: CareEyes = on; CareEyesMinutes = time; break;
                case CareKind.Late: CareLate = on; CareLateHour = time; break;
                case CareKind.Meal: CareMeal = on; CareMealMinutes = time; break;
                case CareKind.Game: CareGame = on; CareGameMinutes = time; break;
                case CareKind.Bored: CareBored = on; CareBoredMinutes = time; break;
            }
        }
    }

    [DataContract]
    internal sealed class Release
    {
        [DataMember(Name = "tag_name")] public string Tag;
        [DataMember(Name = "draft")] public bool Draft;
        [DataMember(Name = "prerelease")] public bool Prerelease;
        [DataMember(Name = "assets")] public ReleaseAsset[] Assets;
    }

    [DataContract]
    internal sealed class ReleaseAsset
    {
        [DataMember(Name = "id")] public long Id;
        [DataMember(Name = "name")] public string Name;
        [DataMember(Name = "browser_download_url")] public string Url;
        [DataMember(Name = "size")] public long Size;
    }

    internal sealed class UpdateFile
    {
        internal string Version;
        internal string Path;
        internal string Hash;
        internal long Size;
    }

    internal sealed class Updater
    {
        private readonly string folder;
        private readonly string app;
        private readonly bool local;
        internal Func<Release> Latest = Companion.FetchLatestRelease;
        internal Func<string, string> Signer = SignedBy;
        internal Action<ProcessStartInfo> Run = delegate(ProcessStartInfo command)
        {
            using (Process process = Process.Start(command)) if (process == null) throw new IOException("The update installer did not start.");
        };

        internal Updater(string data, string executable, bool smoke)
        {
            folder = Path.GetFullPath(Path.Combine(data, "updates"));
            app = executable;
            local = smoke;
            if (smoke)
            {
                Latest = delegate { throw new Exception("The update check needs a fake release."); };
                Run = delegate { throw new Exception("The update installer needs a fake process start."); };
            }
        }

        // Where updates download. A smoke worker keeps its data in a folder of its own, so its check asks here.
        internal string Folder { get { return folder; } }

        // The package manager that installed her, from the marker her installer writes, or null when she updates herself.
        // "manual" or no marker leaves her updater alone; a marker she can't read or doesn't know still holds it back. It's
        // read in her own folder, where her installer writes it and where her own update would install her, even when this
        // Capri.exe runs from somewhere else. A Store copy always updates through the Store, whatever a website install left there.
        internal string Package()
        {
            if (Packaged.Is) return Packaged.Store;
            string path = Path.Combine(Path.GetDirectoryName(folder), SetupFiles.Marker);
            try { File.GetAttributes(path); }
            catch (FileNotFoundException) { return null; }
            catch (DirectoryNotFoundException) { return null; }
            catch (Exception) { return "your package manager"; }
            try
            {
                string name = File.ReadAllText(path).Trim();
                if (name == "manual") return null;
                return Array.IndexOf(SetupFiles.Managers, name) >= 0 ? name : "your package manager";
            }
            catch (Exception) { return "your package manager"; }
        }

        internal static ReleaseAsset Installer(Release release)
        {
            ReleaseAsset first = null;
            ReleaseAsset plain = null;
            if (release == null || release.Assets == null) return null;
            foreach (ReleaseAsset asset in release.Assets)
            {
                if (asset == null || asset.Name == null || !asset.Name.StartsWith("Capri-Setup", StringComparison.OrdinalIgnoreCase) || !asset.Name.EndsWith(".exe", StringComparison.OrdinalIgnoreCase) || asset.Name.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0) continue;
                if (string.Equals(asset.Name, "Capri-Setup-" + (release.Tag ?? "").TrimStart('v', 'V') + ".exe", StringComparison.OrdinalIgnoreCase)) return asset;
                if (string.Equals(asset.Name, "Capri-Setup.exe", StringComparison.OrdinalIgnoreCase)) plain = asset;
                if (first == null) first = asset;
            }
            return plain ?? first;
        }

        internal UpdateFile Download(Release release)
        {
            Version version;
            if (release == null || release.Draft || release.Prerelease || !Companion.ReleaseVersion(release.Tag, out version)) throw new BrainException("This release can't be installed.");
            ReleaseAsset asset = Installer(release);
            if (asset == null) throw new BrainException("This release has no Capri installer.");
            if (asset.Size <= 0 || asset.Size > 512L * 1024 * 1024) throw new BrainException("The update size is invalid.");
            Address(asset.Url);
            ReleaseAsset sums = null;
            foreach (ReleaseAsset entry in release.Assets)
                if (entry != null && string.Equals(entry.Name, "SHA256SUMS.txt", StringComparison.OrdinalIgnoreCase))
                {
                    if (sums != null) throw new BrainException("This release has more than one checksum file.");
                    sums = entry;
                }
            string hash = null;
            if (sums != null)
            {
                using (MemoryStream memory = new MemoryStream())
                {
                    Copy(sums.Url, memory, 1024 * 1024, -1);
                    memory.Position = 0;
                    using (StreamReader reader = new StreamReader(memory)) hash = Checksum(reader.ReadToEnd(), asset.Name);
                }
            }
            UpdateFile update = new UpdateFile { Version = version.Revision == 0 ? version.ToString(3) : version.ToString(4), Hash = hash, Size = asset.Size };
            update.Path = Path.Combine(folder, "Capri-Setup-" + update.Version + "-" + asset.Id + ".exe");
            Directory.CreateDirectory(folder);
            string partial = update.Path + ".partial";
            if (File.Exists(partial)) File.Delete(partial);
            if (File.Exists(update.Path))
            {
                Verify(update.Path, update, true);
                return update;
            }
            try
            {
                using (FileStream target = new FileStream(partial, FileMode.CreateNew, FileAccess.Write, FileShare.None)) Copy(asset.Url, target, asset.Size, asset.Size);
                Verify(partial, update);
                File.Move(partial, update.Path);
                return update;
            }
            finally { if (File.Exists(partial)) File.Delete(partial); }
        }

        internal static string Checksum(string text, string name)
        {
            string found = null;
            foreach (string line in text.Split('\n'))
            {
                Match match = Regex.Match(line.TrimEnd('\r'), @"^([a-fA-F0-9]{64})[ \t]+\*?(.+)$");
                if (!match.Success || match.Groups[2].Value != name) continue;
                if (found != null) throw new BrainException("The installer checksum is listed twice.");
                found = match.Groups[1].Value;
            }
            if (found == null) throw new BrainException("The installer checksum is missing.");
            return found;
        }

        private Uri Address(string address)
        {
            Uri uri;
            if (!Uri.TryCreate(address, UriKind.Absolute, out uri) || uri.UserInfo.Length != 0 || uri.Fragment.Length != 0) throw new BrainException("The update download address is invalid.");
            if (local && uri.IsLoopback && uri.Scheme == Uri.UriSchemeHttp) return uri;
            if (uri.Scheme != Uri.UriSchemeHttps || !uri.IsDefaultPort || uri.Host != "github.com" || !uri.AbsolutePath.StartsWith("/lachydotmcg/capri-desktop/releases/download/", StringComparison.Ordinal)) throw new BrainException("The update download address is invalid.");
            return uri;
        }

        private void Copy(string address, Stream target, long limit, long expected)
        {
            Uri uri = Address(address);
            ServicePointManager.SecurityProtocol |= (SecurityProtocolType)3072;
            Stopwatch elapsed = Stopwatch.StartNew();
            for (int redirect = 0; redirect < 6; redirect++)
            {
                HttpWebRequest request = (HttpWebRequest)WebRequest.Create(uri);
                request.UserAgent = "Capri-Desktop";
                request.Timeout = 15000;
                request.ReadWriteTimeout = 15000;
                request.AllowAutoRedirect = false;
                using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
                {
                    int status = (int)response.StatusCode;
                    if (status == 301 || status == 302 || status == 303 || status == 307 || status == 308)
                    {
                        Uri next;
                        if (!Uri.TryCreate(uri, response.Headers["Location"], out next) || next.UserInfo.Length != 0 || (next.Scheme != Uri.UriSchemeHttps && !(local && next.IsLoopback && next.Scheme == Uri.UriSchemeHttp))) throw new BrainException("The update download moved to an invalid address.");
                        uri = next;
                        continue;
                    }
                    if (status != 200 || response.ContentLength > limit || (expected >= 0 && response.ContentLength >= 0 && response.ContentLength != expected)) throw new BrainException("The update download is incomplete.");
                    using (Stream source = response.GetResponseStream())
                    {
                        byte[] buffer = new byte[65536];
                        long total = 0;
                        int count;
                        while ((count = source.Read(buffer, 0, buffer.Length)) > 0)
                        {
                            total += count;
                            if (total > limit || elapsed.Elapsed.TotalMinutes > 10) throw new BrainException("The update download didn't finish.");
                            target.Write(buffer, 0, count);
                        }
                        if ((expected >= 0 && total != expected) || (response.ContentLength >= 0 && total != response.ContentLength)) throw new BrainException("The update download is incomplete.");
                    }
                    return;
                }
            }
            throw new BrainException("The update download moved too many times.");
        }

        private void Verify(string path, UpdateFile update, bool cached = false)
        {
            string problem = null;
            using (FileStream file = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                if (file.Length != update.Size) problem = "The update download is incomplete.";
                else if (update.Hash != null)
                    using (SHA256 sha = SHA256.Create())
                        if (!string.Equals(BitConverter.ToString(sha.ComputeHash(file)).Replace("-", ""), update.Hash, StringComparison.OrdinalIgnoreCase)) problem = "The update checksum doesn't match. It won't run.";
                if (problem == null)
                {
                    string own = Signer(app);
                    if (own != null && !string.Equals(own, Signer(path), StringComparison.Ordinal)) throw new BrainException("The update signer doesn't match Capri. It won't run.");
                    if (update.Hash == null && own == null) throw new BrainException("This update has no checksum or matching signature. It won't run.");
                }
            }
            if (problem != null) { if (cached) File.Delete(path); throw new BrainException(problem); }
        }

        internal void Install(UpdateFile update, int parent, long started)
        {
            if (update == null || !string.Equals(Path.GetDirectoryName(Path.GetFullPath(update.Path)), folder, StringComparison.OrdinalIgnoreCase) || !update.Path.EndsWith(".exe", StringComparison.OrdinalIgnoreCase) || parent <= 0 || started <= 0) throw new BrainException("The update isn't ready to install.");
            using (FileStream file = new FileStream(update.Path, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                Verify(update.Path, update);
                string package = Package();
                if (package != null) throw new BrainException("Update through " + package + ".");
                Run(new ProcessStartInfo(update.Path, "--update " + parent.ToString(System.Globalization.CultureInfo.InvariantCulture) + " " + started.ToString(System.Globalization.CultureInfo.InvariantCulture)) { UseShellExecute = false, CreateNoWindow = true, WorkingDirectory = folder });
            }
        }

        internal static string SignedBy(string path)
        {
            TrustFile file = new TrustFile { Size = (uint)Marshal.SizeOf(typeof(TrustFile)), Path = path };
            IntPtr pointer = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(TrustFile)));
            Marshal.StructureToPtr(file, pointer, false);
            TrustData data = new TrustData { Size = (uint)Marshal.SizeOf(typeof(TrustData)), Ui = 2, Choice = 1, File = pointer, State = 1, Flags = 128 };
            Guid action = new Guid("00AAC56B-CD44-11D0-8CC2-00C04FC295EE");
            try
            {
                int result = WinVerifyTrust(new IntPtr(-1), ref action, ref data);
                if (result == unchecked((int)0x800B0100)) return null;
                if (result != 0) throw new BrainException("Windows couldn't verify the update signature. It won't run.");
                X509Certificate certificate = X509Certificate.CreateFromSignedFile(path);
                try { using (SHA256 sha = SHA256.Create()) return BitConverter.ToString(sha.ComputeHash(certificate.GetRawCertData())); }
                finally { certificate.Reset(); }
            }
            finally
            {
                data.State = 2;
                WinVerifyTrust(new IntPtr(-1), ref action, ref data);
                Marshal.DestroyStructure(pointer, typeof(TrustFile));
                Marshal.FreeHGlobal(pointer);
            }
        }

        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        private struct TrustFile
        {
            internal uint Size;
            [MarshalAs(UnmanagedType.LPWStr)] internal string Path;
            internal IntPtr File;
            internal IntPtr Subject;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct TrustData
        {
            internal uint Size;
            internal IntPtr Policy;
            internal IntPtr Sip;
            internal uint Ui;
            internal uint Revocation;
            internal uint Choice;
            internal IntPtr File;
            internal uint State;
            internal IntPtr StateData;
            internal IntPtr Url;
            internal uint Flags;
            internal uint Context;
            internal IntPtr Signatures;
        }

        [DllImport("wintrust.dll", ExactSpelling = true)] private static extern int WinVerifyTrust(IntPtr window, ref Guid action, ref TrustData data);
    }

    internal sealed class Clip
    {
        // Art that only some moments need loads off her thread when she might need it and is let go after this long undrawn:
        // every facing-left set, and the clips made lazy (her perch talking). The rest loads with her, as it always has.
        internal const int RestAfter = 90000;
        private static readonly System.Collections.Generic.List<Clip> all = new System.Collections.Generic.List<Clip>();
        private readonly string name;
        private readonly bool lazy;
        private readonly bool flippable;
        private readonly Clip source;
        private readonly object gate = new object();
        private Bitmap strip;
        // her artist's facing-left frames, for the clips that have them (her perches): her red arm and leg swap sides, so a
        // mirror of Strip isn't her. They're stored mirrored back onto Strip's cells and drawn mirrored like the rest.
        private Bitmap flipped;
        private bool fetching;
        private int stripUsed, flippedUsed;
        private readonly int count;
        private readonly double fps;
        private readonly float shiftX, shiftY;
        // The cells a strip can still come in after her own art moved on, a skin's or Legacy stand's: this wide means count cells
        // at fps, drawn unshifted, with no facing-left set of their own.
        private int oldWide, oldCount;
        private double oldFps;
        internal int Count { get { return source != null ? source.Count : Old ? oldCount : count; } }
        internal double Fps { get { return source != null ? source.Fps : Old ? oldFps : fps; } }
        internal readonly float Height;
        // How far a cell's middle sits from the middle of her square, as a share of her size. Narrow cells cut to the art need it.
        internal float ShiftX { get { return source != null ? source.ShiftX : Old ? 0 : shiftX; } }
        internal float ShiftY { get { return source != null ? source.ShiftY : Old ? 0 : shiftY; } }

        internal Clip(string name, int count, double fps, float height, float shiftX = 0, float shiftY = 0, bool lazy = false)
        {
            this.name = name;
            this.lazy = lazy;
            this.count = count;
            this.fps = fps;
            Height = height;
            this.shiftX = shiftX;
            this.shiftY = shiftY;
            if (!Companion.HasArt(Resource(false))) throw new FileNotFoundException("Capri's " + name + " animation is missing. Rebuild with assets/sprites.");
            flippable = Companion.HasArt(Resource(true));
            if (!lazy) strip = Companion.LoadArt(Resource(false));
            lock (all) all.Add(this);
        }

        // Another clip's art under a new name, like her dance: her idle with a nod on top.
        internal Clip(Clip art)
        {
            source = art;
            Height = art.Height;
        }

        internal Clip Older(int wide, int cells, double rate)
        {
            oldWide = wide;
            oldCount = cells;
            oldFps = rate;
            return this;
        }

        // Whether the art that's in sits in the old cells: a skin's strip, or Legacy stand's.
        internal bool Old { get { return source != null ? source.Old : oldWide > 0 && Strip.Width == oldWide; } }

        private bool Turns { get { return flippable && !Old; } }

        private string Resource(bool left) { return "Capri.Sprite." + name + (left ? "_flipped" : "") + ".png"; }

        // Her facing-right art, or her only art. A lazy clip that isn't in yet loads on the spot.
        internal Bitmap Strip
        {
            get
            {
                if (source != null) return source.Strip;
                stripUsed = Environment.TickCount;
                Bitmap art = strip;
                if (art != null) return art;
                lock (gate)
                {
                    if (strip == null) strip = Companion.LoadArt(Resource(false));
                    return strip;
                }
            }
        }

        // Her facing-left art, or null for clips without any and while it loads, which asking for it starts. Until it's in
        // she's drawn as a mirror of Strip.
        internal Bitmap Flipped
        {
            get
            {
                if (source != null) return source.Flipped;
                if (!Turns) return null;
                flippedUsed = Environment.TickCount;
                Bitmap art = flipped;
                if (art == null) Warm(true);
                return art;
            }
        }

        // The facing-left art straight away, loading it here if it isn't in. For her smoke test.
        internal Bitmap FlippedNow
        {
            get
            {
                if (source != null) return source.FlippedNow;
                if (!Turns) return null;
                flippedUsed = Environment.TickCount;
                lock (gate)
                {
                    if (flipped == null) flipped = Companion.LoadArt(Resource(true));
                    return flipped;
                }
            }
        }

        internal bool HasFlipped { get { return source != null ? source.HasFlipped : Turns; } }

        // Loads the art for that way round here and now, if it isn't in, for when she needs it this frame.
        internal void Load(bool left)
        {
            if (source != null) { source.Load(left); return; }
            bool wantLeft = left && Turns;
            if (wantLeft) flippedUsed = Environment.TickCount; else stripUsed = Environment.TickCount;
            lock (gate)
            {
                if (wantLeft && flipped == null) flipped = Companion.LoadArt(Resource(true));
                else if (!wantLeft && strip == null) strip = Companion.LoadArt(Resource(false));
            }
        }

        // Whether the art for that way round is in, so she can show it without waiting: facing left, that's her artist's
        // flipped set when the clip has one.
        internal bool Ready(bool left)
        {
            if (source != null) return source.Ready(left);
            return left && Turns ? flipped != null : strip != null;
        }

        // Starts loading the art for that way round off her thread, and counts as using it, so it stays in while she asks.
        internal void Warm(bool left)
        {
            if (source != null) { source.Warm(left); return; }
            bool wantLeft = left && Turns;
            if (wantLeft) flippedUsed = Environment.TickCount; else stripUsed = Environment.TickCount;
            lock (gate)
            {
                if (fetching || (wantLeft ? flipped != null : strip != null)) return;
                fetching = true;
            }
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                Bitmap art = null;
                // A load that fails, out of memory say, leaves her drawn as she was, and the next ask tries again.
                try { art = Companion.LoadArt(Resource(wantLeft)); }
                catch (Exception) { }
                lock (gate)
                {
                    fetching = false;
                    if (art == null) return;
                    if (wantLeft && flipped == null) flipped = art;
                    else if (!wantLeft && strip == null) strip = art;
                    else art.Dispose();
                }
            });
        }

        // Lets go of art undrawn for RestAfter: lazy clips' own, and every facing-left set. Called on her thread, between frames.
        internal static void RestAll(int now)
        {
            Clip[] clips;
            lock (all) clips = all.ToArray();
            foreach (Clip clip in clips) clip.Rest(now);
        }

        private void Rest(int now)
        {
            lock (gate)
            {
                if (fetching) return;
                if (lazy && strip != null && unchecked(now - stripUsed) > RestAfter) { strip.Dispose(); strip = null; }
                if (flipped != null && unchecked(now - flippedUsed) > RestAfter) { flipped.Dispose(); flipped = null; }
            }
        }

        internal static void ReloadAll()
        {
            Clip[] clips;
            lock (all) clips = all.ToArray();
            foreach (Clip clip in clips) clip.Reload();
        }

        private void Reload()
        {
            if (source != null) return;
            lock (gate)
            {
                Bitmap wasStrip = strip, wasFlipped = flipped;
                strip = lazy ? null : Companion.LoadArt(Resource(false));
                flipped = null;
                if (wasStrip != null) wasStrip.Dispose();
                if (wasFlipped != null) wasFlipped.Dispose();
            }
        }

        // How much of her art is in memory, in bytes, for her smoke test.
        internal static long Loaded()
        {
            Clip[] clips;
            lock (all) clips = all.ToArray();
            long bytes = 0;
            foreach (Clip clip in clips)
                lock (clip.gate)
                    foreach (Bitmap art in new[] { clip.strip, clip.flipped })
                        if (art != null) bytes += 4L * art.Width * art.Height;
            return bytes;
        }

        internal static void DisposeAll()
        {
            Clip[] clips;
            lock (all) { clips = all.ToArray(); all.Clear(); }
            foreach (Clip clip in clips)
                lock (clip.gate)
                {
                    if (clip.strip != null) clip.strip.Dispose();
                    if (clip.flipped != null) clip.flipped.Dispose();
                    clip.strip = clip.flipped = null;
                }
        }
    }

    internal sealed class Note
    {
        internal double Born;
        internal int Side;
        internal int Shape;
        internal double Seed;
    }

    internal sealed partial class Companion : Form
    {
        // her artist's standing set: 60 frames at the 24 fps they're stamped with. Its float is taken out of the frames, so her
        // toes stay on the row every standing clip ends on and her face stays still in its cell, and her breathing floats her
        // instead. The cells are cut to her outline, 11 px right of her square's middle in 384 px art at her standing scale,
        // which keeps her body where it is in those clips. Facing left she's in her artist's flipped set on the same cells.
        private const float IdleShiftX = 11f / 384 * 1.11f;
        private readonly Clip idle = new Clip("idle", 60, 24, 1.11f, IdleShiftX).Older(Mods.OldIdleWide, 16, 8);
        // Her closed eye on frames 25 to 32 of that loop, and her mouth for that face, drawn where it sits in the cell.
        private readonly Clip idleBlink = new Clip("idle_blink", 8, 24, 1.11f, IdleShiftX);
        private readonly Clip idleBlinkGlitch = new Clip("idle_blink_glitch", 8, 24, 1.11f, IdleShiftX);
        private readonly Clip idleMouth = new Clip("idle_mouth", 5, 12, 1.11f, IdleShiftX);
