        // Any key alone or with any of Alt (1), Ctrl (2), Shift (4) and Win (8), which are RegisterHotKey's own flags, and middle click
        // or a side mouse button too. A modifier on its own, a left or right click or an IME placeholder never counts.
        internal static bool Bindable(int mods, int vk) { return (mods & ~15) == 0 && vk > 0 && vk < 0xFF && Array.IndexOf(NotKeys, vk) < 0; }

        private static readonly int[] NotKeys = { 0x01, 0x02, 0x10, 0x11, 0x12, 0x5B, 0x5C, 0xA0, 0xA1, 0xA2, 0xA3, 0xA4, 0xA5, 0xE5, 0xE7 };

        // Middle click, Mouse 4 and Mouse 5. RegisterHotKey can't take them, so a bound one is watched instead.
        internal static bool ByMouse(int vk) { return vk >= 0x04 && vk <= 0x06; }

        private static readonly string[] MouseWords = { "Middle click", "Mouse 4", "Mouse 5" };

        // Keys carries Ctrl, Alt and Shift. The Windows key comes separately, because Keys has no flag for it.
        internal static int HotMods(Keys keys, bool win) { return ((keys & Keys.Alt) != 0 ? 1 : 0) | ((keys & Keys.Control) != 0 ? 2 : 0) | ((keys & Keys.Shift) != 0 ? 4 : 0) | (win ? 8 : 0); }

        internal static string ModNames(int mods) { return ((mods & 8) != 0 ? "Win + " : "") + ((mods & 2) != 0 ? "Ctrl + " : "") + ((mods & 1) != 0 ? "Alt + " : "") + ((mods & 4) != 0 ? "Shift + " : ""); }

        internal static string KeyName(int mods, int vk) { return ModNames(mods) + KeyWord(vk); }

        private static readonly int[] WordedKeys = { 0x10, 0x11, 0x12, 0x03, 0x08, 0x09, 0x0C, 0x0D, 0x13, 0x14, 0x1B, 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, 0x28, 0x2C, 0x2D, 0x2E, 0x2F, 0x5D, 0x5F, 0x6A, 0x6B, 0x6C, 0x6D, 0x6E, 0x6F, 0x90, 0x91, 0xA6, 0xA7, 0xA8, 0xA9, 0xAA, 0xAB, 0xAC, 0xAD, 0xAE, 0xAF, 0xB0, 0xB1, 0xB2, 0xB3, 0xB4, 0xB5, 0xB6, 0xB7 };
        private static readonly string[] KeyWords = { "Shift", "Ctrl", "Alt", "Break", "Backspace", "Tab", "Clear", "Enter", "Pause", "Caps Lock", "Esc", "Space", "Page Up", "Page Down", "End", "Home", "Left", "Up", "Right", "Down", "Print Screen", "Insert", "Delete", "Help", "Menu", "Sleep", "Num *", "Num +", "Num Separator", "Num -", "Num .", "Num /", "Num Lock", "Scroll Lock", "Browser Back", "Browser Forward", "Browser Refresh", "Browser Stop", "Browser Search", "Browser Favorites", "Browser Home", "Volume Mute", "Volume Down", "Volume Up", "Next Track", "Previous Track", "Stop Media", "Play/Pause", "Mail", "Media Select", "App 1", "App 2" };

        // The name on the key: letters and digits as they are, F1 to F24, and words for the rest.
        private static string KeyWord(int vk)
        {
            if ((vk >= 0x41 && vk <= 0x5A) || (vk >= 0x30 && vk <= 0x39)) return ((char)vk).ToString();
            if (vk >= 0x70 && vk <= 0x87) return "F" + (vk - 0x6F);
            if (vk >= 0x60 && vk <= 0x69) return "Num " + (vk - 0x60);
            if (ByMouse(vk)) return MouseWords[vk - 0x04];
            int at = Array.IndexOf(WordedKeys, vk);
            if (at >= 0) return KeyWords[at];
            // Punctuation moves around between keyboard layouts, so it's named by what this keyboard types.
            char typed = (char)(Native.MapVirtualKey(vk, 2) & 0xFFFF);
            return typed > ' ' ? typed.ToString() : "Key " + vk;
        }

        // A key that types, alone or with only Shift, stops typing in other apps while it's hers: RegisterHotKey takes it everywhere.
        internal static bool Swallows(int mods, int vk) { return (mods & 11) == 0 && ((vk >= 0x41 && vk <= 0x5A) || (vk >= 0x30 && vk <= 0x39) || (vk >= 0x60 && vk <= 0x6F) || (vk >= 0xBA && vk <= 0xC0) || (vk >= 0xDB && vk <= 0xDF) || vk == 0xE2 || vk == 0x20 || vk == 0x0D || vk == 0x09 || vk == 0x08); }

        // Saved keys from any version: one that isn't a key goes back to its default, and mute can't share talk's.
        internal static void CheckKeys(Preferences value)
        {
            if (!Bindable(value.TalkMods, value.TalkVk)) { value.TalkMods = 3; value.TalkVk = 0x56; }
            if (!Bindable(value.MuteMods, value.MuteVk) || (value.MuteMods == value.TalkMods && value.MuteVk == value.TalkVk)) { value.MuteMods = 3; value.MuteVk = 0x4E; }
            if (!Bindable(value.TypeMods, value.TypeVk)) { value.TypeMods = 3; value.TypeVk = 0x54; }
            if (!Bindable(value.HideMods, value.HideVk)) { value.HideMods = 3; value.HideVk = 0x48; }
            if (!Bindable(value.QuietMods, value.QuietVk)) { value.QuietMods = 3; value.QuietVk = 0x50; }
            if (!PushBindable(value.PushMods, value.PushVk)) { value.PushMods = 0; value.PushVk = 0; }
            if (!Bindable(value.GameMods, value.GameVk)) { value.GameMods = 3; value.GameVk = 0x47; }
            Unclash(value);
        }

        // Her keys, in the order the Mainframe shows them: talk, mute mic, type to her, hide or show her, quiet, Gaming Mode.
        private static readonly string[] KeyJobs = { "talk", "mute", "typing", "hide", "quiet", "Gaming Mode" };
        private static readonly int[][] SpareKeys = { null, null, new[] { 0x54, 0x59, 0x55, 0x49, 0x4F }, new[] { 0x48, 0x4A, 0x4B, 0x4C, 0x42 }, new[] { 0x50, 0x44, 0x52, 0x4A, 0x4B }, new[] { 0x47, 0x4D, 0x42, 0x55, 0x59 } };

        // Talk and mute were her first keys. A newer type, hide or quiet key that lands on an earlier one, as 0.7.3's new defaults
        // could, moves to the first free Ctrl + Alt spare, so mute on Ctrl + Alt + H stays mute instead of hiding her.
        internal static void Unclash(Preferences value)
        {
            int[] bound = { value.TalkMods, value.TalkVk, value.MuteMods, value.MuteVk, value.TypeMods, value.TypeVk, value.HideMods, value.HideVk, value.QuietMods, value.QuietVk, value.GameMods, value.GameVk };
            for (int slot = 2; slot < KeyJobs.Length; slot++)
            {
                if (!Clashes(bound, slot, bound[slot * 2], bound[slot * 2 + 1], slot)) continue;
                foreach (int vk in SpareKeys[slot])
                    if (!Clashes(bound, slot, 3, vk, KeyJobs.Length)) { bound[slot * 2] = 3; bound[slot * 2 + 1] = vk; break; }
            }
            value.TypeMods = bound[4];
            value.TypeVk = bound[5];
            value.HideMods = bound[6];
            value.HideVk = bound[7];
            value.QuietMods = bound[8];
            value.QuietVk = bound[9];
            value.GameMods = bound[10];
            value.GameVk = bound[11];
        }

        // Whether a key matches one of the other slots before below.
        private static bool Clashes(int[] bound, int slot, int mods, int vk, int below)
        {
            for (int i = 0; i < below; i++) if (i != slot && bound[i * 2] == mods && bound[i * 2 + 1] == vk) return true;
            return false;
        }

        internal string SetHotkey(int slot, Keys keys) { return SetHotkey(slot, HotMods(keys, false), (int)(keys & Keys.KeyCode)); }

        internal string SetHotkey(int slot, int mods, int vk)
        {
            if (slot == PushSlot) return SetPushKey(mods, vk);
            if (!Bindable(mods, vk)) return "Press a key, alone or with Ctrl, Alt, Shift or Win.";
            string name = KeyName(mods, vk);
            int[] bound = { preferences.TalkMods, preferences.TalkVk, preferences.MuteMods, preferences.MuteVk, preferences.TypeMods, preferences.TypeVk, preferences.HideMods, preferences.HideVk, preferences.QuietMods, preferences.QuietVk, preferences.GameMods, preferences.GameVk };
            for (int i = 0; i < KeyJobs.Length; i++)
                if (i != slot && mods == bound[i * 2] && vk == bound[i * 2 + 1]) return name + " is already her " + KeyJobs[i] + " key.";
            if (preferences.PushVk != 0 && mods == preferences.PushMods && vk == preferences.PushVk) return name + " is already her push-to-talk key.";
            if (!testing && IsHandleCreated)
            {
                if (slot == 1)
                {
                    bool live = muteKey;
                    if (live) Native.UnregisterHotKey(Handle, MuteKeyId);
                    bool free = ByMouse(vk) || Native.RegisterHotKey(Handle, MuteKeyId, mods | 0x4000, vk);
                    if (free && !live && !ByMouse(vk)) Native.UnregisterHotKey(Handle, MuteKeyId);
                    if (!free)
                    {
                        if (live) muteKey = ByMouse(preferences.MuteVk) || Native.RegisterHotKey(Handle, MuteKeyId, preferences.MuteMods | 0x4000, preferences.MuteVk);
                        return name + " is taken by another app. Try another.";
                    }
                }
                else
                {
                    int id = slot == 0 ? TalkKeyId : slot == 2 ? TypeKeyId : slot == 3 ? HideKeyId : slot == 4 ? QuietKeyId : GameKeyId;
                    if (slot == 0 ? talkKey : slot == 2 ? typeKey : slot == 3 ? hideKey : slot == 4 ? quietKey : gameKey) Native.UnregisterHotKey(Handle, id);
                    bool held = ByMouse(vk) || Native.RegisterHotKey(Handle, id, mods | 0x4000, vk);
                    bool kept = held || ByMouse(bound[slot * 2 + 1]) || Native.RegisterHotKey(Handle, id, bound[slot * 2] | 0x4000, bound[slot * 2 + 1]);
                    if (slot == 0) talkKey = kept; else if (slot == 2) typeKey = kept; else if (slot == 3) hideKey = kept; else if (slot == 4) quietKey = kept; else gameKey = kept;
                    if (!held) return name + " is taken by another app. Try another.";
                }
            }
            if (slot == 0) { preferences.TalkMods = mods; preferences.TalkVk = vk; }
            else if (slot == 1) { preferences.MuteMods = mods; preferences.MuteVk = vk; }
            else if (slot == 2) { preferences.TypeMods = mods; preferences.TypeVk = vk; }
            else if (slot == 3) { preferences.HideMods = mods; preferences.HideVk = vk; }
            else if (slot == 4) { preferences.QuietMods = mods; preferences.QuietVk = vk; }
            else { preferences.GameMods = mods; preferences.GameVk = vk; }
            SavePreferences();
            WatchMouse();
            if (!testing) { mainframe.ShowShortcut(talkKey, true); mainframe.ShowKeys(typeKey, hideKey, quietKey, gameKey); }
            mainframe.Hotkeys(TalkKeyName, MuteKeyName, TypeKeyName, HideKeyName, QuietKeyName, GameKeyName);
            return null;
        }

        // A bound mouse button is checked about 30 times a second, only while one of her keys is a mouse button.
        private readonly System.Windows.Forms.Timer mouseKeys = new System.Windows.Forms.Timer { Interval = 30 };
        private readonly bool[] mouseHeld = new bool[6];
        // A mouse button also counts when it went down and back up between two checks (the low bit), so a quick tap isn't missed.
        internal static Func<int, bool> KeyHeld = delegate(int vk) { return (Native.GetAsyncKeyState(vk) & (ByMouse(vk) ? 0x8001 : 0x8000)) != 0; };

        private void WatchMouse()
        {
            if (!testing && (preferences.PushVk != 0 || ByMouse(preferences.TalkVk) || ByMouse(preferences.MuteVk) || ByMouse(preferences.TypeVk) || ByMouse(preferences.HideVk) || ByMouse(preferences.QuietVk) || ByMouse(preferences.GameVk)))
            {
                // A click from before she started watching doesn't count.
                if (!mouseKeys.Enabled) foreach (int vk in new[] { 0x04, 0x05, 0x06 }) Native.GetAsyncKeyState(vk);
                mouseKeys.Start();
            }
            else mouseKeys.Stop();
        }

        // A press counts once, when the button goes down with exactly its modifiers held, like RegisterHotKey's keys. It isn't
        // swallowed, so the button still does its own job in the app under it. While a new key is being picked, nothing fires.
        internal void WatchMouseKeys()
        {
            int[] bound = { preferences.TalkMods, preferences.TalkVk, preferences.MuteMods, preferences.MuteVk, preferences.TypeMods, preferences.TypeVk, preferences.HideMods, preferences.HideVk, preferences.QuietMods, preferences.QuietVk, preferences.GameMods, preferences.GameVk };
            int[] ids = { TalkKeyId, MuteKeyId, TypeKeyId, HideKeyId, QuietKeyId, GameKeyId };
            int mods = (KeyHeld(0x12) ? 1 : 0) | (KeyHeld(0x11) ? 2 : 0) | (KeyHeld(0x10) ? 4 : 0) | (KeyHeld(0x5B) || KeyHeld(0x5C) ? 8 : 0);
            // Each button is read once a check: reading it clears its quick-tap bit, so a second key on the same button would miss the tap.
            System.Collections.Generic.Dictionary<int, bool> buttons = new System.Collections.Generic.Dictionary<int, bool>();
            for (int slot = 0; slot < ids.Length; slot++)
            {
                int vk = bound[slot * 2 + 1];
                bool down = false;
                if (ByMouse(vk) && !buttons.TryGetValue(vk, out down)) { down = KeyHeld(vk); buttons[vk] = down; }
                bool pressed = down && !mouseHeld[slot] && mods == bound[slot * 2];
                mouseHeld[slot] = down;
                if (!pressed || (slot == 1 && !muteKey) || mainframe.Picking) continue;
                Message press = Message.Create(Handle, 0x0312, new IntPtr(ids[slot]), IntPtr.Zero);
                WndProc(ref press);
            }
            WatchPush();
        }

        internal int BubbleTime { get { return Math.Max(0, Math.Min(2, preferences.BubbleTime)); } }

        internal void SetBubbleTime(int level)
        {
            preferences.BubbleTime = Math.Max(0, Math.Min(2, level));
            SavePreferences();
        }

        private double BubbleHold(int length) { return Math.Min(14, 4 + length * 0.05) * new[] { 0.5, 1, 2 }[BubbleTime]; }
        internal static double CommentHold(int length, int time) { return (4 + length * 0.05) * new[] { 0.5, 1, 2 }[time]; }

        internal void SetSleepAfter(int seconds)
        {
            preferences.SleepAfter = Math.Max(0, Math.Min(3600, seconds));
            if (preferences.SleepAfter == 0 && (ownNap || (Asleep && !napping))) WakeRest(false);
            SavePreferences();
        }

        private bool SleepDue(long quiet) { return preferences.SleepAfter > 0 && quiet >= preferences.SleepAfter * 1000L; }

        internal int PerchFps { get { return preferences.PerchFps; } }

        // Power saver: Off, In games or Always, from HABITS or her settings tool.
        internal int PowerSaver { get { return preferences.PowerSaver; } }

        internal void SetPowerSaver(int level)
        {
            preferences.PowerSaver = Math.Max(0, Math.Min(2, level));
            SavePreferences();
            mainframe.Sync();
        }

        // Power saver is working now: Always, or In games while a game or anything full screen is in front.
        internal bool Saving { get { return preferences.PowerSaver == 2 || preferences.PowerSaver == 1 && frontBusy; } }

        // Her quarter-second signals' ticks: while Power saver works, her background checks run on every 4th, once a second.
        internal const int SaverEvery = 4;
        private int signalTicks;

        private bool BackgroundDue(int tick) { return !Saving || tick % SaverEvery == 0; }

        // One signals tick under Power saver: her ears' pace follows it, and it says whether the background checks run this tick.
        private bool SaverTick() { Ears.Gentle = Saving; return BackgroundDue(++signalTicks); }

        // How often she looks at her mic's mute switch for Hey Capri, and at Windows' default mic for Windows speech, in seconds.
        private double MicLookGap { get { return Saving ? 6 : 2; } }

        internal void SetPerchFps(int fps)
        {
            preferences.PerchFps = PerchRate(fps);
            SavePreferences();
        }

        // The nearest perch fps choice, and 30 when it was never set.
        internal static int PerchRate(int fps)
        {
            if (fps <= 0) return 30;
            int near = 0;
            for (int i = 0; i < PerchRates.Length; i++) if (Math.Abs(PerchRates[i] - fps) < Math.Abs(PerchRates[near] - fps)) near = i;
            return PerchRates[near];
        }

        internal void SetSoundLevel(int percent)
        {
            Sfx.Level = Math.Max(0, Math.Min(100, percent));
            preferences.Sounds = Sfx.Level;
            SavePreferences();
            Sfx.Play(Cue.Hop);
        }

        private bool localAddressTyped;

        internal string ChooseCustomModel(string name, string[] installed)
        {
            name = (name ?? "").Trim();
            if (name.Length == 0) return "Type a model name first.";
            string address = Brain.LocalAddress(preferences.LocalAddress);
            if (preferences.Tier == 0 && address != null && (localAddressTyped || brain.Model == null))
            {
                ChooseLocalBrain(new Cloud(Brain.LocalPort(address), name, address), name, null);
                mainframe.ShowCloud(brain.Remote, null);
                return "Using " + name + " at " + address + ".";
            }
            if (brain.Local != null) return "Custom models need Ollama, a local server or an API key.";
            if (brain.Model == null) return "Find her a brain first.";
            Cloud remote = brain.Remote;
            if (remote == null && installed != null && Array.IndexOf(installed, name) < 0 && Array.IndexOf(installed, name + ":latest") < 0) return "Ollama doesn't have it. Run: ollama pull " + name;
            if (remote != null && remote.Kind != "local" && !Brain.ModelFits(remote.Kind, name)) return "That isn't a model for " + remote.Company + ".";
            if (preferences.Tier == 1 && remote != null && remote.Kind == "openrouter" && !name.EndsWith(":free", StringComparison.Ordinal)) return "MEDIUM INTELLIGENCE needs a :free model. Paid models go under MAX INTELLIGENCE.";
            ChooseModel(name);
            if (remote == null) { mainframe.ShowOllama(installed ?? new[] { name }, name); return "Using " + name + "."; }
            if (remote.Kind == "local") { mainframe.ShowCloud(remote, null); return "Using " + name + " on " + remote.Name + "."; }
            if (cloudModels == null) cloudModels = new System.Collections.Generic.List<string> { remote.Model };
            if (!cloudModels.Contains(name)) cloudModels.Add(name);
            mainframe.ShowCloud(remote, cloudModels);
            return "Using " + name + ". If it doesn't answer, it isn't on your key.";
        }

        internal void ToggleDance()
        {
            preferences.NoDance = !preferences.NoDance;
            danceItem.Checked = !preferences.NoDance;
            SavePreferences();
            mainframe.Sync();
            if (preferences.NoDance && (clip == dance || clip == perchDance)) { Play(seat != null ? perch : idle); UpdateAnimation(); }
        }

        private void CheckMusic(double now)
        {
            if (!musicBusy && !preferences.NoDance && !hidden && now - musicAt >= 2)
            {
                musicBusy = true;
                musicAt = now;
                ThreadPool.QueueUserWorkItem(delegate
                {
                    bool on = false;
                    try { on = MusicPlaying(); } catch (Exception) { }
                    Post(delegate { musicBusy = false; musicOn = on; });
                });
            }
            bool dancing = clip == dance || clip == perchDance;
            if (!musicOn) danceHeld = false;
            bool wanted = danceAsked || (musicOn && !preferences.NoDance && preferences.Motion && !danceHeld);
            // Mid-job she bops along on her task panel too: the job keeps her thinking and voice chat may be on for them to cut
            // in, so only her talking stops it there (Lachy, 29 Oct: "she didnt bop her head when i played the songs").
            bool busy = speech != null || (working != null ? now < voiceUntil : talkState != TalkState.Off || InChat);
            bool free = wanted && !hidden && !dragging && !pressed && !riding && !falling && !hanging && !walking && outro == null && !busy && !Hushed && !ownRest;
            if (dancing && !free) { Play(seat != null || onPanel ? perch : idle); UpdateAnimation(); }
            else if (!dancing && free && (clip == idle || clip == perch || clip == laydown)) { SitUp(false); Play(seat != null || onPanel ? perchDance : dance); frames.Start(); }
            groove.Want(!testing && musicOn && !preferences.NoDance && preferences.Motion && !hidden);
        }

        private void CheckHome(double now)
        {
            if (homeBusy || now - homeAt < 15) return;
            homeBusy = true;
            homeAt = now;
            ThreadPool.QueueUserWorkItem(delegate
            {
                bool game = false, song = false;
                try
                {
                    Process[] running = Process.GetProcessesByName("Cyberpunk2077");
                    game = running.Length > 0;
                    foreach (Process process in running) process.Dispose();
                    foreach (OpenWindow window in Hands.Windows()) if ((string.Equals(window.Program, "Spotify", StringComparison.OrdinalIgnoreCase) || (window.Title ?? "").IndexOf("YouTube", StringComparison.OrdinalIgnoreCase) >= 0) && Hands.NightCity(window.Title)) song = true;
                    // A paused YouTube tab keeps its title, so the song has to be playing too.
                    if (song) song = MusicPlaying();
                }
                catch (Exception) { }
                Post(delegate
                {
                    homeBusy = false;
                    bool free = preferences.CheckIns && !Hushed && (!hidden || docked) && !quitting && !dragging && !pressed && !InChat && !typer.Visible && !menu.Visible && speech == null && talkState == TalkState.Off && !onPanel && outro == null;
                    string line = Cheer(game, song, clock.Elapsed.TotalSeconds, free);
                    if (line != null) SayOwn("", line);
                });
            });
        }

        private void CheckLag(double now)
        {
            if (now - lagAt < 15) return;
            lagAt = now;
            long idle, total;
            if (!Native.CpuTimes(out idle, out total)) return;
            double busy = lagTotal == 0 || total <= lagTotal ? 0 : 1 - (double)(idle - lagIdle) / (total - lagTotal);
            lagIdle = idle;
            lagTotal = total;
            bool free = preferences.CheckIns && !Hushed && !hidden && !quitting && !dragging && !pressed && !InChat && !typer.Visible && !menu.Visible && speech == null && talkState == TalkState.Off && !onPanel && outro == null && !Native.Gaming();
            string line = Lagging(busy, now, free);
            if (line != null) SayOwn("", line);
        }

        // Her joke once the CPU has been over 90% busy four checks in a row, about a minute, while she's free, or null.
        private string Lagging(double busy, double now, bool free)
        {
            lagHot = busy >= 0.9 ? lagHot + 1 : 0;
            if (lagHot < 4 || !free || now - lagSaid < LagGap) return null;
            lagHot = 0;
            lagSaid = now;
            return Lines.Pick(LagLines);
        }

        // Her cheer when the game starts or a Night City song comes on and she's free, or null. One she misses while busy waits for the next time.
        private string Cheer(bool game, bool song, double now, bool free)
        {
            bool started = game && !homeGame, cameOn = song && !homeSong;
            homeGame = game;
            homeSong = song;
            if (!free) return null;
            if (started && now - gameCheered >= HomeGap) { gameCheered = now; return Lines.Pick(HomeGameLines); }
            if (cameOn && now - songCheered >= HomeGap) { songCheered = now; return Lines.Pick(HomeSongLines); }
            return null;
        }

        internal static Func<bool> MusicPlaying = delegate { return MediaPlaying() || PlayerLoud(); };
        private static bool mediaMissing;
        private static readonly string[] SilentPlayers = { "AIMP", "foobar2000", "winamp", "MusicBee", "Clementine", "strawberry", "MediaMonkey" };
        private static GameEars playerEars;
        private static int playerOpen, playerLooked, playerHeard;

        // AIMP and players like it don't tell Windows what's on, so she goes by whether one is making sound. A gap between songs doesn't count.
        private static bool PlayerLoud()
        {
            lock (SilentPlayers)
            {
                if (playerLooked == 0 || unchecked(Environment.TickCount - playerLooked) >= 10000)
                {
                    playerLooked = Environment.TickCount;
                    // One list of what's running, not one per player: each list is a snapshot of every process on the PC.
                    int found = 0, rank = SilentPlayers.Length;
                    foreach (Process each in Process.GetProcesses())
                    {
                        for (int i = 0; i < rank; i++) if (string.Equals(each.ProcessName, SilentPlayers[i], StringComparison.OrdinalIgnoreCase)) { rank = i; found = each.Id; break; }
                        each.Dispose();
                    }
                    if (found != playerOpen)
                    {
                        if (playerEars != null) playerEars.Dispose();
                        playerEars = null;
                        playerOpen = found;
                        if (found != 0)
                        {
                            playerEars = new GameEars(found);
                            playerEars.Start();
                        }
                    }
                }
                if (playerEars == null) return false;
                if (playerEars.Level > 0.01) playerHeard = Environment.TickCount;
                return playerHeard != 0 && unchecked(Environment.TickCount - playerHeard) < 4000;
            }
        }

        // Read from the same look at Windows' sessions as her mini player's.
        private static bool MediaPlaying()
        {
            if (mediaMissing) return false;
            try
            {
                System.Collections.Generic.List<Tune> sessions = Tunes.Shared();
                if (sessions == null) return false;
                foreach (Tune tune in sessions)
                {
                    if (!tune.Playing || tune.Changing || tune.Video) continue;
                    if (IsMusicApp(tune.App)) return true;
                    if (tune.Music && IsSong(tune.Title, tune.Artist, TimeSpan.FromSeconds(tune.Length))) return true;
                }
                return false;
            }
            catch (TypeLoadException) { mediaMissing = true; return false; }
            catch (Exception) { return false; }
        }

        internal static bool IsMusicApp(string id) { return id != null && Regex.IsMatch(id, @"spotify|zunemusic|applemusic|itunes|amazonmusic|tidal|deezer|foobar|musicbee|winamp|aimp|soundcloud|pandora", RegexOptions.IgnoreCase); }

        internal static bool IsSong(string title, string artist, TimeSpan length)
        {
            if (Regex.IsMatch(title ?? "", @"official\s+(music\s+)?(video|audio|visuali[sz]er)|\blyrics?\b|\bremix\b|\bmix\b|playlist|\blo-?fi\b|beats to|\bradio\b|\bdj\b|full album|nightcore|sped up|slowed|\bfeat\.|\bft\.|[(\[]audio[)\]]", RegexOptions.IgnoreCase)) return true;
            return !string.IsNullOrWhiteSpace(artist) && length > TimeSpan.Zero && length <= TimeSpan.FromMinutes(12);
        }

        // Her mini player: while something plays it shows what, read from Windows' media session about once a second off her
        // window's thread, and she perches on it like a window edge.
        private void CheckPlayer(double now)
        {
            if (!PlayerAllowed) { HidePlayer(); return; }
            if (!tuneBusy && now - tuneAt >= 1)
            {
                tuneBusy = true;
                tuneAt = now;
                double asked = Tunes.Now;
                ThreadPool.QueueUserWorkItem(delegate
                {
                    Tune tune = null;
                    try { tune = Tunes.Read(); } catch (Exception) { }
                    Post(delegate { tuneBusy = false; Tuned(tune, clock.Elapsed.TotalSeconds, asked); });
                });
            }
            if (!player.Visible) return;
            PlayerLegs();
            PlayerLayer(false);
        }

        // What's playing came back. It shows while something plays and stays up a minute after a pause. Closing it keeps it
        // away until nothing has played for a bit, and it keeps out of full-screen games and videos.
        private void Tuned(Tune tune, double now, double asked)
        {
            if (tune != null && tune.Playing) tuneHeard = now;
            else if (playerClosed && now - tuneHeard >= PlayerQuiet) { playerClosed = false; tuneHeard = -1; }
            bool allowed = PlayerAllowed && !playerClosed;
            bool up = allowed && tune != null && tuneHeard >= 0 && now - tuneHeard < PlayerLinger && (preferences.PlayerFullScreen || !FullScreen());
            // Never out from under them while they're using it.
            if (!up && allowed && player.Busy && (!FullScreen() || preferences.PlayerFullScreen)) { up = true; tune = tune ?? player.Tune; }
            if (!up) { HidePlayer(); return; }
            // A read from before their last press may not have the press in it yet.
            if (player.Visible && asked < player.SentAt + 0.3) return;
            ShowPlayer(tune, now);
        }

        private bool PlayerAllowed { get { return !preferences.NoPlayer && !quitting && !docked && (!hidden || fullScreenHidden && !manualHidden && preferences.PlayerFullScreen); } }

        private void ShowPlayer(Tune tune, double now)
        {
            bool fresh = !player.Visible;
            player.Motion = preferences.Motion;
            player.ShowTune(tune, preferences.HasPlayerSpot ? new Point(preferences.PlayerX, preferences.PlayerY) : (Point?)null);
            if (fresh) { PassThrough(); PlayerLayer(true); playerHopUntil = now + 10; }
            if (playerHopUntil >= 0 && (now > playerHopUntil || HopOnPlayer())) playerHopUntil = -1;
            ReadHeart();
        }

        // A song already liked on Spotify shows her heart filled: Spotify's own heart is read once per song, off her window's thread.
        private void ReadHeart()
        {
            Tune shown = player.Tune;
            if (heartBusy || shown == null || !shown.Spotify || shown.Key == heartRead) return;
            heartBusy = true;
            heartRead = shown.Key;
            string key = shown.Key;
            double asked = Tunes.Now;
            ThreadPool.QueueUserWorkItem(delegate
            {
                bool? has = null;
                try { has = Tunes.Hearted(); } catch (Exception) { }
                Post(delegate { heartBusy = false; if (has.HasValue) player.Hearted(key, has.Value, asked); });
            });
        }

        private void HidePlayer()
        {
            playerHopUntil = -1;
            heartRead = null;
            if (!player.Visible) return;
            // Off its edge before it goes: she stands up and falls to whatever's below it.
            if (seat != null && seat.Window == player.Handle) { StandUp(); Fall(); }
            player.Hide();
        }

        // As it comes up with Wander on, she hops onto its top edge near its left end, like Lachy's picture. With Wander off she
        // stays where she was put, and sits on it when they drop her there.
        private bool HopOnPlayer()
        {
            if (seat != null && seat.Window == player.Handle) return true;
            bool settled = talkState == TalkState.Off || (talkState == TalkState.Talking && replyDone >= 0 && clock.Elapsed.TotalSeconds - replyDone > 8);
            if (!preferences.Wander || preferences.NoSitting || napAsked || napping || hidden || dragging || pressed || riding || onPanel || falling || hanging || walking || InChat || typer.Visible || menu.Visible || speech != null || !settled || (seat != null && seat.Free) || outro != null || (clip != idle && clip != perch && clip != dance && clip != perchDance)) return false;
            Rectangle plate = player.Plate;
            int x = plate.Left + (int)(plate.Width * MiniPlayer.Perch);
            Ledge spot = Around().Find(ledge => ledge.Window == player.Handle && ledge.Left <= x && x <= ledge.Right);
            if (spot == null || spot.Y - Headroom() < Screen.FromPoint(new Point(x, spot.Y)).Bounds.Top) return false;
            GlitchOut(delegate { Hop(spot, x); }, false);
            return true;
        }

        // Her legs over its plate, so the song's name moves out from under them.
        private void PlayerLegs() { player.Sitting(seat != null && seat.Window == player.Handle && !hidden ? (int?)Hip().X : null, preferences.Size, facingLeft); }

        // It sits just under her: over other windows with Always on top on, and among them with it off.
        private void PlayerLayer(bool now)
        {
            if (!player.IsHandleCreated || !IsHandleCreated) return;
            IntPtr front = Native.GetForegroundWindow();
            bool top = preferences.OnTop || preferences.PlayerFullScreen && FullScreen();
            if (!now && front == playerFront && top == playerTop) return;
            playerFront = front;
            playerTop = top;
            player.Above = top;
            if (!top) { Native.SetWindowPos(player.Handle, Handle, 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010); return; }
            Native.SetWindowPos(player.Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            lastForeground = new IntPtr(-1);
            StayOnTop();
        }

        // Presses go to the app one at a time, in the order they were made, off her window's thread.
        private void PlayerCommand(string what)
        {
            if (what == "menu") { ShowPlayerMenu(); return; }
            if (what == "close") { playerClosed = true; HidePlayer(); return; }
            if (player.Tune == null) return;
            lock (playerPresses)
            {
                playerPresses.Enqueue(new System.Collections.Generic.KeyValuePair<Tune, string>(player.Tune, what));
                if (playerSending) return;
                playerSending = true;
            }
            ThreadPool.QueueUserWorkItem(delegate
            {
                while (true)
                {
                    System.Collections.Generic.KeyValuePair<Tune, string> press;
                    lock (playerPresses)
                    {
                        if (playerPresses.Count == 0) { playerSending = false; return; }
                        press = playerPresses.Dequeue();
                    }
                    bool sent = false;
                    try { sent = Tunes.Send(press.Key, press.Value); } catch (Exception) { }
                    Post(delegate { player.Sent(press.Value, sent); tuneAt = -10; });
                }
            });
        }

        private void ShowPlayerMenu()
        {
            Tune tune = player.Tune;
            playerOpenItem.Text = "Open " + Tunes.AppName(tune != null ? tune.App : null);
            playerOpenItem.Enabled = tune != null;
            playerMenu.Show(Cursor.Position);
        }

        internal bool PlayerOn { get { return !preferences.NoPlayer; } }

        internal void TogglePlayer()
        {
            preferences.NoPlayer = !preferences.NoPlayer;
            SavePreferences();
            mainframe.Sync();
            if (preferences.NoPlayer) HidePlayer();
            else { playerClosed = false; tuneAt = -10; }
        }

        private void SavePlayerSpot(Point corner)
        {
            preferences.PlayerX = corner.X;
            preferences.PlayerY = corner.Y;
            preferences.HasPlayerSpot = true;
            SavePreferences();
        }

        private System.Collections.Generic.List<Ledge> Spots()
        {
            System.Collections.Generic.List<Ledge> spots = new System.Collections.Generic.List<Ledge>();
            int room = Headroom();
            foreach (Ledge ledge in Around())
            {
                if (!ledge.Icon.IsEmpty || ledge.Right - ledge.Left < preferences.Size / 2) continue;
                if (seat != null && ledge.Window == seat.Window && ledge.Floor == seat.Floor) continue;
                if (ledge.Y - room < Screen.FromPoint(new Point(ledge.Left, ledge.Y)).Bounds.Top) continue;
                spots.Add(ledge);
            }
            return spots;
        }

        private bool Wander()
        {
            Rectangle area = WanderArea();
            if (!area.IsEmpty)
            {
                Point beside = WanderPoint(area, preferences.Size, random.NextDouble(), random.NextDouble());
                Ledge perch = new Ledge { Left = beside.X - 8, Right = beside.X + 8, Y = beside.Y, Floor = true, Free = true, Aside = true };
                GlitchOut(delegate { Hop(perch, beside.X); }, false);
                return true;
            }
            System.Collections.Generic.List<Ledge> spots = Spots();
            if (spots.Count == 0) return false;
            Ledge spot = WanderSpot(spots, preferences.Size, random.NextDouble());
            int margin = preferences.Size / 4;
            int x = spot.Left + margin + random.Next(Math.Max(1, spot.Right - spot.Left - 2 * margin));
            GlitchOut(delegate { Hop(spot, x); }, false);
            return seat == spot;
        }

        private Rectangle WanderArea()
        {
            Sight front = Computer.Glimpse();
            return front == null || !FullScreen() ? Rectangle.Empty : Screen.FromRectangle(front.Bounds).Bounds;
        }

        // Longer ledges get more of her visits, so a short strip of window doesn't keep pulling her back.
        internal static Ledge WanderSpot(System.Collections.Generic.List<Ledge> spots, int size, double pick)
        {
            long total = 0;
            foreach (Ledge ledge in spots) total += Math.Max(1, ledge.Right - ledge.Left - 2 * (size / 4));
            long at = (long)(pick * total);
            foreach (Ledge ledge in spots)
            {
                at -= Math.Max(1, ledge.Right - ledge.Left - 2 * (size / 4));
                if (at < 0) return ledge;
            }
            return spots[spots.Count - 1];
        }

        // Where she lands with something full screen in front: a side of it, about halfway up, clear of the crosshair in the
        // middle and the health bars along the bottom (john_sandevistan, 31 Oct).
        internal static Point WanderPoint(Rectangle area, int size, double across, double down)
        {
            int margin = Math.Min(size / 2, area.Width / 8), band = area.Width / 6;
            int x = across < 0.5 ? area.Left + margin + (int)(across * 2 * band) : area.Right - margin - (int)((across - 0.5) * 2 * band);
            return new Point(x, area.Top + area.Height * 2 / 5 + (int)(down * area.Height / 5));
        }

        private void Hop(Ledge spot, int x)
        {
            lying = false;
            hanging = false;
            walking = false;
            seat = null;
            anchor = Seated(x, spot.Y);
            Land(spot, true);
            if (seat != spot) { anchor = KeepOnScreen(anchor); Play(arrive); dropAfter = true; }
            Static(false, null);
            frames.Start();
        }

        private void SitHere()
        {
            if (hidden || riding || onPanel) return;
            Halt();
            hanging = false;
            Point hip = Hip();
            Land(new Ledge { Left = hip.X - 8, Right = hip.X + 8, Y = hip.Y, Floor = true, Free = true });
            frames.Start();
        }

        private void HangHere()
        {
            if (hidden || riding || onPanel) return;
            SitUp(false);
            Halt();
            dropAfter = false;
            walking = false;
            seat = null;
            falling = false;
            fallTo = null;
            hanging = true;
            Play(dangle);
            frames.Start();
            SavePreferences();
        }

        private void LetGo()
        {
            hanging = false;
            Play(glitch);
            frames.Start();
            if (!Drop()) SavePreferences();
        }

        private void StandUp()
        {
            SitUp(false);
            Halt();
            hanging = false;
            walking = false;
            if (seat != null) asideAt = seat.Aside ? anchor : (Point?)null;
            seat = null;
            coveredSince = -1;
            seatLost = -1;
            falling = false;
            fallTo = null;
            leanAngle = 0;
            Play(glitch);
            frames.Start();
        }

        private bool Asleep { get { return clip == sleep || clip == laydownSleep || clip == perchSleep; } }

        private void LoseSeat()
        {
            bool sleeping = napping && Asleep, sat = clip == perchSleep;
            StandUp();
            // Asleep sitting up on a window that closes, minimises or gets covered, she sleeps on standing where she is.
            if (sat) { Play(sleep); return; }
            if (sleeping) { napping = false; napAsked = true; }
        }

        internal static bool LiePlace(Ledge ledge, Point hip, Rectangle area, int size, bool left, out int x, out bool way)
        {
            x = hip.X;
            way = left;
            if (ledge.Free || !ledge.Icon.IsEmpty) return false;
            int torso = (int)Math.Ceiling(size * LieTorso), reach = (int)Math.Ceiling(size * LieReach);
            int toes = (int)Math.Ceiling(size * (LyingRight.Right - LieRight));
            int rightFrom = Math.Max(ledge.Left + torso, area.Left + reach), rightTo = Math.Min(ledge.Right, area.Right - toes);
            int leftFrom = Math.Max(ledge.Left, area.Left + toes), leftTo = Math.Min(ledge.Right - torso, area.Right - reach);
            bool fitsRight = rightFrom <= rightTo, fitsLeft = leftFrom <= leftTo;
            if (!fitsRight && !fitsLeft) return false;
            int rightX = Math.Max(rightFrom, Math.Min(hip.X, rightTo)), leftX = Math.Max(leftFrom, Math.Min(hip.X, leftTo));
            way = fitsLeft && (!fitsRight || Math.Abs(leftX - hip.X) < Math.Abs(rightX - hip.X) || (left && Math.Abs(leftX - hip.X) == Math.Abs(rightX - hip.X)));
            x = way ? leftX : rightX;
            return true;
        }

        internal static Ledge NapPlace(System.Collections.Generic.IEnumerable<Ledge> places, Point hip, Rectangle area, int size, bool left, out int x, out bool way)
        {
            Ledge nearest = null;
            long distance = long.MaxValue;
            x = hip.X;
            way = left;
            foreach (Ledge place in places)
            {
                int placeX;
                bool placeLeft;
                int headroom = (int)Math.Ceiling(size * (SitY - LyingRight.Top));
                if (place.Y < hip.Y || place.Y > area.Bottom || place.Y - headroom < area.Top || !LiePlace(place, hip, area, size, left, out placeX, out placeLeft)) continue;
                long dx = placeX - hip.X, dy = place.Y - hip.Y;
                long away = dx * dx + dy * dy;
                if (away >= distance) continue;
                distance = away;
                nearest = place;
                x = placeX;
                way = placeLeft;
            }
            return nearest;
        }

        // Which way she'd lie along her ledge: her own way if her body has ledge under it and her hair stays on screen, else
        // the other way, else null. Facing right she lies back from her hip to the left, so that's where the room has to be.
        private bool? LieWay()
        {
            if (seat == null || seat.Free || !seat.Icon.IsEmpty || riding || onPanel || walking || falling || hanging || dragging || hidden) return null;
            Point hip = Hip();
            Rectangle area = Screen.FromPoint(hip).WorkingArea;
            int torso = (int)Math.Ceiling(preferences.Size * LieTorso), reach = (int)Math.Ceiling(preferences.Size * LieReach);
            bool right = hip.X - seat.Left >= torso && hip.X - reach >= area.Left;
            bool left = seat.Right - hip.X >= torso && hip.X + reach <= area.Right;
            if (facingLeft ? left : right) return facingLeft;
            if (facingLeft ? right : left) return !facingLeft;
            return null;
        }

        // From sitting, she lies down along her ledge, her hip where it was, glitching into her artist's lay-down set.
        private bool LieDown()
        {
            bool? way = LieWay();
            if (lying || way == null || clip != perch) return false;
            Point hip = Hip();
            facingLeft = way.Value;
            lying = true;
            nextLie = -1;
            anchor = Seated(hip.X, seat.Y);
            Location = anchor;
            // Her loop and its glitch load here and now; the rest follows off her thread while she lies.
            laydown.Load(facingLeft);
            laydownGlitch.Load(facingLeft);
            WarmLie();
            Play(preferences.Motion ? laydownGlitch : laydown);
            Static(false, null);
            frames.Start();
            return true;
        }

        // She sits back up where she lay, her hip where it was: with her perch's glitch, unless something else takes over.
        private void SitUp(bool glitched = true)
        {
            if (!lying) return;
            Point hip = Hip();
            lying = false;
            nextLie = -1;
            anchor = new Point(anchor.X + hip.X - Hip().X, anchor.Y);
            if (seat != null && seat.Floor) anchor = Seated(hip.X, seat.Y);
            Location = anchor;
            if (!glitched || seat == null) return;
            Play(preferences.Motion ? perchGlitch : perch);
            frames.Start();
        }

        // While she lies, the rest of her lay-down set loads off her thread, facing her way: her blinks, her glitch, and her
        // talking frames once she's answering or in voice chat. Sleeping loads when she nods off.
        private void WarmLie()
        {
            laydown.Warm(facingLeft);
            laydownBlink.Warm(facingLeft);
            laydownBlinkGlitch.Warm(facingLeft);
            laydownGlitch.Warm(facingLeft);
            if (TalkingNow || talkState != TalkState.Off || chatting) laydownTalk.Warm(facingLeft);
        }

        // Quiet stretches give her an occasional lie-down. Sleep follows their idle setting, with a longer gap between naps.
        private void CheckLie(double now, long quiet)
        {
            if (lieBy >= 0)
            {
                if (now > lieBy || lying || dragging || riding || hanging || hidden) lieBy = -1;
                else if (clip == perch && SittingStill) { lieBy = -1; LieDown(); return; }
            }
            bool calm = RestFree(now) && quiet >= LieQuiet * 1000;
            if (!calm)
            {
                nextLie = -1;
                if (ownRest) WakeRest(false);
                return;
            }
            if (ownRest && restUntil >= 0 && now >= restUntil) { WakeRest(false); return; }
            if (!ownRest && (walking || falling || hanging || outro != null || (clip != idle && clip != perch && clip != laydown))) return;
            if (SleepDue(quiet) && now >= nextNap)
            {
                if (!ownRest) ownLie = !lying;
                ownRest = ownNap = true;
                if (preferences.NoSitting && seat == null)
                {
                    nextNap = now + NapGap + random.NextDouble() * NapSpread;
                    Play(sleep);
                    frames.Start();
                    return;
                }
            }
            if (!ownRest)
            {
                if (lying || preferences.NoSitting) return;
                if (nextLie < 0) nextLie = now + LieGap + random.NextDouble() * LieSpread;
                if (now < nextLie) return;
                ownRest = true;
                ownLie = true;
                ownNap = false;
                restUntil = now + LieStay + random.NextDouble() * LieStaySpread;
            }
            SettleRest(now, ownNap);
        }

        private void Tumble(double now)
        {
            if (thrown) { Fly(now); return; }
            double step = Math.Max(0, Math.Min(0.05, now - fallStep));
            fallStep = now;
            Point hip = Hip();
            if (fallTo == null) fallTo = Ledges.Below(Around(), hip, 0, int.MaxValue, 0, Headroom());
            if (fallTo == null) { falling = false; SavePreferences(); return; }
            fallSpeed += preferences.Size * 11 * step;
            int drop = (int)Math.Ceiling(fallSpeed * step);
            if (hip.Y + drop >= fallTo.Y) Land(fallTo);
            else anchor.Y += drop;
        }

        private void Land(Ledge ledge, bool arriving = false)
        {
            SitUp(false);
            fallTo = null;
            walking = false;
            if (ledge.Window != IntPtr.Zero)
            {
                Rectangle bounds;
                if (!Ledges.Showing(ledge.Window, out bounds) || !Ledges.Seatable(ledge.Window, bounds)) return;
                if (bounds != ledge.Bounds) { ledge.Left = bounds.Left; ledge.Right = bounds.Right; ledge.Y = bounds.Top; ledge.Bounds = bounds; }
            }
            falling = false;
            thrown = false;
            coveredSince = -1;
            seatLost = -1;
            int x = ledge.Icon.IsEmpty ? Math.Max(ledge.Left + 8, Math.Min(Hip().X, ledge.Right - 8)) : ledge.Icon.Left + ledge.Icon.Width / 2;
            Rectangle area = Screen.FromPoint(new Point(x, ledge.Y - 1)).WorkingArea;
            int rightmost = area.Right - (int)Math.Ceiling(preferences.Size * (PerchedBody.Right - SitX));
            if (ledge.Icon.IsEmpty && ledge.Right >= area.Right - 8 && BodyOnScreen(anchor, Body).Right >= area.Right - 2) x = rightmost;
            x = Math.Max(area.Left + (int)Math.Ceiling(preferences.Size * (SitX - PerchedBody.Left)), Math.Min(x, rightmost));
            seat = ledge;
            leanAngle = 0;
            anchor = Seated(x, ledge.Y);
            Play(arriving && preferences.Motion && !instant ? perchArrive : perchGlitch);
            SavePreferences();
        }

        // While she's thrown her fall is a flight, which Tumble hands to Fly.
        private bool Flying { get { return falling && thrown; } }

        // A gap in their cursor's track with no move in it means it sat still until just before the next one.
        private const double TrailGap = 0.03;

        // How fast their cursor went over the last span seconds up to now, in pixels a second: from where it was then to where
        // it is, going straight between the spots it was seen at. Before the first spot it was there.
        internal static PointF TrailSpeed(System.Collections.Generic.IList<System.Collections.Generic.KeyValuePair<double, Point>> track, double now, double span)
        {
            if (track.Count == 0 || span <= 0) return PointF.Empty;
            PointF to = TrailAt(track, now), from = TrailAt(track, now - span);
            return new PointF((float)((to.X - from.X) / span), (float)((to.Y - from.Y) / span));
        }

        private static PointF TrailAt(System.Collections.Generic.IList<System.Collections.Generic.KeyValuePair<double, Point>> track, double at)
        {
            if (at <= track[0].Key) return track[0].Value;
            for (int i = 1; i < track.Count; i++)
            {
                if (at > track[i].Key) continue;
                double began = Math.Max(track[i - 1].Key, track[i].Key - TrailGap), length = track[i].Key - began;
                double part = at <= began ? 0 : length <= 0 ? 1 : (at - began) / length;
                Point a = track[i - 1].Value, b = track[i].Value;
                return new PointF((float)(a.X + (b.X - a.X) * part), (float)(a.Y + (b.Y - a.Y) * part));
            }
            return track[track.Count - 1].Value;
        }

        // Let go while their cursor's still going fast, she's thrown at its speed (Zr4, F63: "grab her and throw her by mouse
        // speed"). Slower, she drops like before, and mid-job dragging her stays as it was.
        private bool Throw(double now)
        {
            if (onPanel || hidden || docked || riding || working != null || job != null || trail.Count == 0) return false;
            PointF speed = TrailSpeed(trail, now, ThrowSpan);
            double scale = TalkScale(), vx = speed.X, vy = speed.Y, fast = Math.Sqrt(vx * vx + vy * vy);
            if (fast < ThrowFrom * scale) return false;
            double most = ThrowMost * scale;
            if (fast > most) { vx *= most / fast; vy *= most / fast; fast = most; }
            Launch(vx, vy, now);
            Grudge(fast / scale, now);
            return true;
        }

        // She leaves their hand at vx, vy pixels a second, kept to the screen she's on.
        private void Launch(double vx, double vy, double now)
        {
            SitUp(false);
            seat = null;
            hanging = false;
            walking = false;
            dropAfter = false;
            fallTo = null;
            falling = true;
            thrown = true;
            fallSpeed = 0;
            fallStep = now;
            flyX = anchor.X;
            flyY = anchor.Y;
            flyAt = anchor;
            flyVX = vx;
            flyVY = vy;
            flyArea = Screen.FromPoint(new Point(anchor.X + Width / 2, anchor.Y + Height / 2)).WorkingArea;
            flyBegan = now;
            flyHardest = 0;
            flyBumped = -1;
            flyBounces = flyFloors = 0;
            flyLedges = null;
            dizzyUntil = -1;
            leanAngle = 0;
            spin = 0;
            // She tumbles the way she's thrown, faster the harder it is.
            spinRate = preferences.Motion ? Math.Max(-1080, Math.Min(1080, vx * 0.28 + (vx < 0 ? -1 : 1) * Math.Abs(vy) * 0.1)) : 0;
            Play(dangle);
            frames.Start();
        }

        // One frame of her flight: gravity and air drag, bounces off her screen's sides, top and taskbar that lose some speed each
        // time, and a ledge she comes down onto catches her like a fall. A soft bounce off the taskbar lands her on it.
        private void Fly(double now)
        {
            double step = Math.Max(0, Math.Min(0.05, now - fallStep));
            fallStep = now;
            // Moved by something else mid-flight, like a screen going away, she carries on from there.
            if (anchor != flyAt) { flyX = anchor.X; flyY = anchor.Y; }
            if (Screen.FromRectangle(flyArea).WorkingArea != flyArea) flyArea = Screen.FromPoint(new Point(anchor.X + Width / 2, anchor.Y + Height / 2)).WorkingArea;
            if (clip == idle) Play(dangle);
            int size = preferences.Size, hipDown = PaddingSize + (int)(size * SitY), hipAcross = PaddingSize + (int)(size * SitX);
            bool sits = !preferences.NoSitting;
            RectangleF body = Body;
            double left = flyArea.Left - PaddingSize - (int)(size * body.Left), right = flyArea.Right - PaddingSize - (int)Math.Ceiling(size * body.Right);
            double top = flyArea.Top - PaddingSize - (int)(size * body.Top);
            // She bounces where she'd sit on the taskbar, her hip on its edge, but never with her feet past the bottom of the screen.
            double feet = flyArea.Bottom - PaddingSize - (int)Math.Ceiling(size * body.Bottom);
            double floor = sits ? Math.Min(flyArea.Bottom - hipDown, Screen.FromRectangle(flyArea).Bounds.Bottom - PaddingSize - (int)Math.Ceiling(size * body.Bottom)) : feet;
            if (sits && (flyLedges == null || now - flyLedgesAt >= 0.25)) { flyLedges = Around(); flyLedgesAt = now; }
            double gravity = size * 11, settle = size * 2.2, calm = 900 * TalkScale();
            int steps = Math.Max(1, (int)Math.Ceiling(step / 0.004));
            double dt = step / steps;
            for (int i = 0; i < steps; i++)
            {
                double hipWas = flyY + hipDown;
                flyVY += gravity * dt;
                double keep = Math.Exp(-ThrowDrag * dt);
                flyVX *= keep;
                flyVY *= keep;
                flyX += flyVX * dt;
                flyY += flyVY * dt;
                Spin(dt, calm);
                if (flyX < left) { Hit(Math.Abs(flyVX), now); flyX = Math.Min(right, left + (left - flyX) * WallBounce); flyVX = Math.Abs(flyVX) * WallBounce; spinRate = -spinRate * 0.8; }
                else if (flyX > right) { Hit(Math.Abs(flyVX), now); flyX = Math.Max(left, right - (flyX - right) * WallBounce); flyVX = -Math.Abs(flyVX) * WallBounce; spinRate = -spinRate * 0.8; }
                if (flyY < top) { Hit(Math.Abs(flyVY), now); flyY = Math.Min(floor, top + (top - flyY) * WallBounce); flyVY = Math.Abs(flyVY) * WallBounce; }
                if (sits && flyVY > 0)
                {
                    double hipNow = flyY + hipDown;
                    int hipX = (int)Math.Round(flyX) + hipAcross;
                    Ledge onto = null;
                    foreach (Ledge ledge in flyLedges)
                    {
                        if (ledge.Floor || ledge.Y < hipWas || ledge.Y > hipNow || ledge.Right - ledge.Left < 24 || hipX < ledge.Left || hipX > ledge.Right) continue;
                        if (ledge.Y - Headroom() < Screen.FromPoint(new Point(hipX, ledge.Y)).Bounds.Top) continue;
                        if (onto == null || ledge.Y < onto.Y) onto = ledge;
                    }
                    if (onto != null)
                    {
                        double impact = flyVY;
                        anchor = new Point((int)Math.Round(flyX), onto.Y - hipDown);
                        Land(onto);
                        if (seat == onto) { Landed(impact, now); return; }
                        // Its window's gone or can't seat her any more: she flies on past it.
                        flyLedges.Remove(onto);
                    }
                }
                if (flyY >= floor)
                {
                    double impact = flyVY;
                    flyY = floor;
                    if (impact > settle && flyFloors < 6) { Hit(impact, now); flyVY = -impact * FloorBounce; flyVX *= FloorGrip; spinRate *= 0.6; flyFloors++; }
                    else { Settle(impact, now, sits); return; }
                }
            }
            anchor = new Point((int)Math.Round(flyX), (int)Math.Round(flyY));
            flyAt = anchor;
            // A flight that somehow never settles carries on as a plain fall.
            if (now - flyBegan > FlightLongest) { thrown = false; if (!sits) { falling = false; SavePreferences(); } }
        }

        // Her tumble slows in the air, and once she's slowed down or bounced off the taskbar she rights herself before she lands.
        // None with reduced motion.
        private void Spin(double dt, double calm)
        {
            if (!preferences.Motion) { spin = spinRate = 0; return; }
            spin += spinRate * dt;
            spinRate *= Math.Exp(-0.6 * dt);
            if (flyFloors == 0 && flyVX * flyVX + flyVY * flyVY >= calm * calm) return;
            double off = spin - 360 * Math.Round(spin / 360);
            spinRate += (-off * 60 - spinRate * 14) * dt;
        }

        // How far she's turned in her tumble, for drawing.
        private float Turn() { return Flying && preferences.Motion ? (float)spin : 0; }

        // She hits a side, the top or the taskbar at impact pixels a second.
        private void Hit(double impact, double now)
        {
            flyBounces++;
            flyHardest = Math.Max(flyHardest, impact);
            if (impact / TalkScale() < BumpFrom || now - flyBumped < 0.12) return;
            flyBumped = now;
            anchor = new Point((int)Math.Round(flyX), (int)Math.Round(flyY));
            Bump();
        }

        // An impact she feels: a thud, and with motion on a short screen tear where she hit.
        private void Bump()
        {
            bumps++;
            if (instant || hidden || !IsHandleCreated) return;
            Sfx.Play(Cue.Bonk);
            Static(false, null);
        }

        // Slow at the taskbar, she lands on it like any fall. With Sit on windows off she just stops there.
        private void Settle(double impact, double now, bool sits)
        {
            anchor = new Point((int)Math.Round(flyX), (int)Math.Round(flyY));
            flyAt = anchor;
            if (sits) Land(new Ledge { Floor = true, Left = flyArea.Left, Right = flyArea.Right, Y = flyArea.Bottom });
            else
            {
                falling = false;
                thrown = false;
                SavePreferences();
            }
            Landed(impact, now);
        }

        // Down after a flight: a hard one thuds, leaves her dizzy for a beat and gets a word out of her, and the third throw in
        // two minutes gets her sulk.
        private void Landed(double impact, double now)
        {
            thrown = false;
            spin = spinRate = 0;
            double scale = TalkScale(), hardest = Math.Max(flyHardest, impact) / scale;
            if (impact / scale >= BumpFrom) Bump();
            bool dizzy = hardest >= DizzyFrom;
            if (dizzy) { dizzyFrom = now; dizzyUntil = now + DizzyFor; dizzyGlitchAt = now + 0.9; }
            if (sulkLine) { sulkLine = false; Yelp("throws you", Lines.Pick(SulkLines), true); }
            else if (dizzy && throwsAt.Count == 1) Yelp("throws you", Lines.Pick(DizzyLines), true);
        }

        private bool Dizzy(double now) { return now >= dizzyFrom && now < dizzyUntil; }

        // Dizzy, her head swims around her hip and settles. Not with reduced motion, or while she's held, riding or falling.
        private float Sway(double now)
        {
            if (!preferences.Motion || !Dizzy(now) || dragging || falling || riding || onPanel) return 0;
            double fade = Math.Min(1, (dizzyUntil - now) / (DizzyFor * 0.6));
            return (float)(DizzySway * Math.Sin((now - dizzyFrom) * Math.PI * 2 * 1.3) * fade);
        }

        // Every throw counts toward her grudge: the second in two minutes gets a warning and the third starts her sulk. A hard
        // first one gets a yelp and a glitch as she flies.
        private void Grudge(double fast, double now)
        {
            throwsAt.RemoveAll(at => now - at > SulkWindow || at > now);
            throwsAt.Add(now);
            if (fast >= ThrowHard) Static(false, Cue.Hop);
            if (throwsAt.Count >= SulkThrows) { throwsAt.Clear(); Sulk(now); sulkLine = true; return; }
            string line = throwsAt.Count == 2 ? Lines.Pick(WarnLines) : fast >= ThrowHard ? Lines.Pick(ThrowLines) : null;
            if (line != null) Yelp("throws you", line, false);
        }

        // Her short line about being thrown or touched: in her bubble straight away, or said in her voice like her pat lines.
        // Never over a chat, a reply on its way, her typing box or a job, though one of these lines still up gives way to the
        // next. shown is what her bubble says they did, or null for a line she says on her own.
        private void Yelp(string shown, string line, bool voiced)
        {
            if (hidden || docked || InChat || typer.Visible || working != null || job != null) return;
            if ((speech != null || talkState != TalkState.Off) && asking != yelpTicket) return;
            heard = shown ?? "sulk";
            box.Prompt = shown == null ? "" : "> sys: ";
            yelpTicket = ++asking;
            if (shown == null) remarkTicket = yelpTicket;
            if (voiced) Answer(yelpTicket, line, TalkState.Talking);
            else Begin(yelpTicket, line, TalkState.Talking, null);
        }

        private bool Sulking { get { return sulkSince >= 0; } }

        private void Sulk(double now)
        {
            sulkSince = now;
            sulkBothered = now;
            sulkDodges = 0;
            dodgeAt = dodgeSaidAt = -10;
            // A cursor that's already close when she starts sulking hasn't come at her.
            shyInside = true;
            shyAt = -1;
            frames.Start();
            Agent told = agent;
            if (told != null) told.Tell("They just threw Capri around three times in two minutes, so she's sulking: she won't let them pick her up until they say sorry, give her a head pat or leave her alone for five minutes. She still answers and helps them as usual.");
        }

        // She makes up with them and forgets the throws: they said sorry, gave her a head pat, or left her be long enough.
        private void Forgive()
        {
            if (!Sulking) return;
            sulkSince = -1;
            sulkLine = false;
            throwsAt.Clear();
            shyAt = -1;
            Agent told = agent;
            if (told != null) told.Tell("Capri forgave them for throwing her around and isn't sulking any more.");
        }

        // Left alone five minutes, she gets over it by herself.
        private void CheckSulk(double now)
        {
            if (!Sulking || now - sulkBothered < SulkAlone) return;
            Forgive();
            if (!Hushed) Yelp(null, Lines.Pick(AloneLines), true);
        }

        // Sulking, she keeps an eye on their cursor: one that comes at her fast gets a hop away, at most every DodgeGap seconds.
        // One that comes slowly can reach her, so a head pat can make up with her.
        private void Shy(double now)
        {
            Point cursor = MouseAt();
            int margin = Math.Max(16, (int)(preferences.Size * 0.18f));
            bool inside = Rectangle.Inflate(BodyOnScreen(anchor, seat != null ? PerchedBody : Body), margin, margin).Contains(cursor);
            double gap = now - shyAt, dx = cursor.X - shyCursor.X, dy = cursor.Y - shyCursor.Y;
            bool fast = shyAt >= 0 && gap > 0 && gap < 0.3 && Math.Sqrt(dx * dx + dy * dy) / gap >= DodgeSpeed * TalkScale();
            bool came = inside && !shyInside && fast;
            shyInside = inside;
            shyCursor = cursor;
            shyAt = now;
            if (came && now - dodgeAt >= DodgeGap && !hidden && !docked && !pressed && !dragging && !falling && !riding && !onPanel && outro == null && working == null && job == null && !Asleep) Dodge(cursor, now);
        }

        // Sulking, she glitches a short hop away from their cursor: along her ledge if it has room one way or the other, or else
        // across the air, kept on her screen, falling onto what's below if she'd been sitting (Zr4, F44).
        private void Dodge(Point cursor, double now)
        {
            dodgeAt = now;
            sulkBothered = now;
            dodges++;
            sulkDodges++;
            Point hip = Hip();
            Rectangle area = Screen.FromPoint(hip).WorkingArea;
            int size = preferences.Size, hop = (int)(size * (0.85 + random.NextDouble() * 0.4));
            int away = cursor.X > hip.X ? -1 : 1;
            if (seat != null && !seat.Free && seat.Icon.IsEmpty)
            {
                int low = Math.Max(seat.Left, area.Left) + size / 3, high = Math.Min(seat.Right, area.Right) - size / 3;
                if (high > low)
                {
                    int there = Math.Max(low, Math.Min(high, hip.X + away * hop)), back = Math.Max(low, Math.Min(high, hip.X - away * hop));
                    int x = Math.Abs(there - cursor.X) >= Math.Abs(back - cursor.X) ? there : back;
                    if (Math.Abs(x - cursor.X) >= size / 2 && Math.Abs(x - hip.X) >= size / 4)
                    {
                        Ledge spot = seat;
                        GlitchOut(delegate { Hop(spot, x); }, false);
                        Fuss(now);
                        return;
                    }
                }
            }
            RectangleF shape = seat != null ? PerchedBody : Body;
            Point to = Within(new Point(anchor.X + away * hop, anchor.Y), area, shape);
            if (Math.Abs(to.X - anchor.X) < size / 3) to = Within(new Point(anchor.X - away * hop, anchor.Y), area, shape);
            bool free = seat != null && seat.Free, drop = seat != null && !free && !preferences.NoSitting, beside = free && seat.Aside;
            int freeY = free ? seat.Y : 0, shift = to.X - anchor.X;
            GlitchOut(delegate
            {
                if (free) { int freeX = Hip().X + shift; Hop(new Ledge { Left = freeX - 8, Right = freeX + 8, Y = freeY, Floor = true, Free = true, Aside = beside }, freeX); return; }
                SitUp(false);
                seat = null;
                hanging = false;
                walking = false;
                anchor = to;
                Location = anchor;
                Play(instant || !preferences.Motion ? idle : arrive);
                Static(false, null);
                frames.Start();
                if (!drop) return;
                if (clip == arrive) dropAfter = spawnFall = true;
                else Fall();
            }, false);
            Fuss(now);
        }

        // What she says as she hops away: always the first time in a sulk, then now and then.
        private void Fuss(double now)
        {
            if (sulkDodges > 1 && now - dodgeSaidAt < DodgeSaid) return;
            dodgeSaidAt = now;
            Yelp("reaches for you", sulkDodges == 1 ? FirstDodgeLine : Lines.Pick(DodgeLines), true);
        }

        // An apology to her, typed or said: "sorry", "I'm sorry Capri", "my bad", "forgive me", and sorry in a few other languages.
        private static readonly Regex SorrySaid = new Regex(@"\b(?:sorry|sry|soz|sowwy|apologi[sz]e|my bad|forgive me|lo siento|perd[oó]n(?:ame)?|d[eé]sol[eé]e?|entschuldigung|tut mir leid|scusa(?:mi)?|mi dispiace|desculpa|przepraszam|прости|извини)\b|ごめん|すみません|미안|죄송|对不起|對不起|抱歉", RegexOptions.IgnoreCase);
        // The words around a plain apology: her name, "I'm so", "for throwing you" and the like.
        private static readonly Regex SorryWords = new Regex(@"^(?:sorry|sry|soz|sowwy|i|i'm|im|i’m|am|so|soo+|really|truly|very|super|capri|choom|babe|bestie|hey|oh|ok|okay|please|pls|plz|forgive|me|my|bad|apologi[sz]e|for|about|throwing|threw|throw|tossing|tossed|yeeting|yeeted|yeet|you|that|it|earlier|again|the|thing|won't|wont|won’t|do|will|never|i'll|ill|i’ll|lol|haha|a|lot|lo|siento|perd[oó]n|perdona|perd[oó]name|d[eé]sol[eé]e?|entschuldigung|tut|mir|leid|scusa|scusami|mi|dispiace|desculpa|przepraszam|прости|извини)$", RegexOptions.IgnoreCase);

        internal static bool Apology(string text) { return text != null && SorrySaid.IsMatch(text); }

        // Nothing but an apology, so her forgiving line is the whole answer. Anything more goes on to her brain as usual.
        internal static bool OnlyApology(string text)
        {
            if (!Apology(text)) return false;
            foreach (string word in Regex.Split(text.Trim(), @"[^\p{L}\p{N}'’]+"))
                if (word.Length > 0 && !SorryWords.IsMatch(word)) return false;
            return true;
        }

        private void HoldSeat(double now)
        {
            if (seat.Window == IntPtr.Zero) return;
            Rectangle bounds;
            if (!Ledges.Showing(seat.Window, out bounds) || !Ledges.Seatable(seat.Window, bounds))
            {
                if (seatLost < 0) seatLost = now;
                if (!Ledges.Alive(seat.Window) || now - seatLost >= 0.3) LoseSeat();
                return;
            }
            seatLost = -1;
            if (bounds == seat.Bounds) return;
            seatMovedAt = now;
            int dx = bounds.Width == seat.Bounds.Width ? bounds.Left - seat.Bounds.Left : 0;
            int x = Math.Max(bounds.Left + 8, Math.Min(Hip().X + dx, bounds.Right - 8));
            seat.Bounds = bounds;
            seat.Left = bounds.Left;
            seat.Right = bounds.Right;
            seat.Y = bounds.Top;
            if (lying)
            {
                int heldRestX;
                bool heldRestLeft;
                if (!LiePlace(seat, new Point(x, seat.Y), Screen.FromPoint(new Point(x, seat.Y)).WorkingArea, preferences.Size, facingLeft, out heldRestX, out heldRestLeft)) { LoseSeat(); return; }
                x = heldRestX;
                facingLeft = heldRestLeft;
            }
            if (!walking) { anchor = Seated(x, bounds.Top); return; }
            int was = anchor.X;
            anchor = Standing(x, bounds.Top);
            walkTo += anchor.X - was;
            int edge = Standing(bounds.Right - (int)(preferences.Size * 0.41f) - 8, bounds.Top).X;
            walkTo = Math.Max(Standing(bounds.Left + (int)(preferences.Size * 0.1f) + 8, bounds.Top).X, Math.Min(walkTo, edge));
        }

        private void CheckSeat(double now)
        {
            if (seat == null || falling || seat.Floor || docked) return;
            if (!seat.Icon.IsEmpty && now - iconsAt > 2) RefreshIcons();
            if (!Ledges.Covered(seat, Hip().X, Skip())) { coveredSince = -1; return; }
            if (coveredSince < 0) coveredSince = now;
            if (now - coveredSince >= 0.7) LoseSeat();
        }

        private void RefreshIcons()
        {
            if (iconsBusy) return;
            iconsBusy = true;
            ThreadPool.QueueUserWorkItem(delegate
            {
                System.Collections.Generic.List<Rectangle> found;
                try { found = Ledges.Icons(); } catch { found = new System.Collections.Generic.List<Rectangle>(); }
                Post(delegate
                {
                    iconsBusy = false;
                    icons = found;
                    iconsAt = clock.Elapsed.TotalSeconds;
                    if (seat != null && !seat.Icon.IsEmpty && !falling && !found.Contains(seat.Icon)) StandUp();
                });
            });
        }

        internal bool Sitting { get { return !preferences.NoSitting; } }

        internal void ToggleSitting()
        {
            preferences.NoSitting = !preferences.NoSitting;
            sitItem.Checked = !preferences.NoSitting;
            if (preferences.NoSitting && (seat != null || falling)) { SitUp(false); seat = null; falling = false; walking = false; Play(idle); UpdateAnimation(); }
            SavePreferences();
        }

        private void React()
        {
            if (WakeRest(!SleepBusy)) { RenderFrame(); return; }
            if (hanging) { LetGo(); return; }
            EndWalk();
            clicks++;
            if (clip == wake) return;
            Play(lying ? laydownGlitch : seat != null || onPanel ? perchGlitch : glitch);
            if (!hidden) frames.Start();
            RenderFrame();
        }

        private void SetHidden(bool value)
        {
            manualHidden = value;
            if (docked && !value) return;
            if (value && !hidden) { GlitchOut(delegate { ShowHidden(true); }); return; }
            ShowHidden(value);
        }

        private void ShowHidden(bool value)
        {
            manualHidden = value;
            ApplyHidden(value || fullScreenHidden);
        }

        internal bool KeepAwake { get { return !preferences.NoKeepAwake; } }
        internal bool HideFullScreen { get { return preferences.HideFullScreen; } }
        internal bool PlayerFullScreen { get { return preferences.PlayerFullScreen; } }
        internal bool ExploreAway { get { return preferences.ExploreAway; } }
        // The test walks every row, so it sees them all except for the one step that checks Settings as people first see it.
        private bool simpleTest;
        internal bool AdvancedSettings { get { return (testing && !simpleTest) || preferences.AdvancedSettings; } }
        internal void ToggleAdvancedSettings() { preferences.AdvancedSettings = !preferences.AdvancedSettings; SavePreferences(); }
        // For a check to see Settings as people first see it. ToggleAdvancedSettings can't do that under test.
        internal void InSimpleSettings(Action check)
        {
            bool simpleWas = simpleTest, advancedWas = preferences.AdvancedSettings;
            try
            {
                simpleTest = true;
                preferences.AdvancedSettings = false;
                check();
            }
            finally
            {
                simpleTest = simpleWas;
                preferences.AdvancedSettings = advancedWas;
            }
        }
        internal int ExploreAfter { get { return preferences.ExploreAfter > 0 ? preferences.ExploreAfter : 300; } }

        internal void ToggleKeepAwake()
        {
            preferences.NoKeepAwake = !preferences.NoKeepAwake;
            CheckKeepAwake();
            SavePreferences();
            mainframe.Sync();
        }

        private void CheckKeepAwake()
        {
            if (testing && keepAwakeTest == null) return;
            bool wanted = KeepAwake && !quitting && (job != null || working != null || lookout.Count > 0);
            if (wanted == keepAwakeWanted) return;
            keepAwakeWanted = wanted;
            uint state = Native.ES_CONTINUOUS | (wanted ? Native.ES_SYSTEM_REQUIRED | Native.ES_DISPLAY_REQUIRED : 0);
            if (keepAwakeTest != null) keepAwakeTest(state); else Native.SetThreadExecutionState(state);
        }

        internal void ToggleHideFullScreen()
        {
            preferences.HideFullScreen = !preferences.HideFullScreen;
            CheckFullScreen(FullScreen());
            SavePreferences();
            mainframe.Sync();
        }

        internal void TogglePlayerFullScreen()
        {
            preferences.PlayerFullScreen = !preferences.PlayerFullScreen;
            tuneAt = -10;
            if (!testing) CheckPlayer(clock.Elapsed.TotalSeconds);
            SavePreferences();
            mainframe.Sync();
        }

        internal void ToggleExploreAway()
        {
            preferences.ExploreAway = !preferences.ExploreAway;
            StopExplore();
            SavePreferences();
            mainframe.Sync();
        }

        internal void SetExploreAfter(int seconds)
        {
            preferences.ExploreAfter = seconds > 0 ? seconds : 300;
            StopExplore();
            SavePreferences();
            mainframe.Sync();
        }

        private void CheckForeground(double now)
        {
            bool full = FullScreen();
            CheckFullScreen(full);
            if (!full) LeaveAside(now);
            if (now < frontChecked) return;
            frontChecked = now + 1;
            Sight ahead = Computer.Glimpse();
            frontBusy = full || (ahead != null && ahead.Window == Native.GetForegroundWindow() && Computer.GameWindow(ahead));
            // Over a game with nothing to do she gives way to it. Listening, talking, clipping or working, she keeps her place so her ears and hands don't stutter.
            Native.Lower(frontBusy && working == null && !chatting && !preferences.HeyCapri && !preferences.ClipGames && talkState == TalkState.Off);
        }

        private void CheckFullScreen(bool full)
        {
            // Fullscreen does not take her controls away (Lachy, 2 Nov: keep her draggable and clickable).
            bool through = full && !docked;
            if (through || fullThrough) { fullThrough = through; PassThrough(); }
            bool shouldHide = preferences.HideFullScreen && full && !gaming.Asked;
            if (fullScreenHidden == shouldHide) return;
            // Hiding closes her bubble and her voice with it, so she finishes her line first.
            if (shouldHide && Voicing) return;
            fullScreenHidden = shouldHide;
            if (!docked && hidden != (manualHidden || shouldHide)) ApplyHidden(manualHidden || shouldHide);
        }

        internal bool FullScreenDisplay { get { return fullThrough || (!testing && Native.FillsScreen()); } }

        // Beside something full screen she sits on nothing, clear of the game or video. Once it's gone she drops onto what's under
        // her, the taskbar if nothing else, even mid-nap or stood up there by a display change, instead of staying in the middle of
        // their screen (john_sandevistan, 1 and 3 Nov).
        private void LeaveAside(double now)
        {
            if (!Aside || hidden || docked || dragging || pressed || riding || walking || falling || hanging || outro != null || working != null) return;
            Point hip = Hip();
            Ledge under = Ledges.Below(Around(), hip, 0, int.MaxValue, 0, Headroom());
            if (under == null)
            {
                Rectangle area = Screen.FromPoint(hip).WorkingArea;
                under = new Ledge { Floor = true, Left = area.Left, Right = area.Right, Y = area.Bottom };
            }
            LoseSeat();
            asideAt = null;
            fallTo = under;
            falling = true;
            thrown = false;
            fallSpeed = 0;
            fallStep = now;
            Play(dangle);
            frames.Start();
        }

        // Beside something full screen: on her spot there, or stood up on it and not moved since.
        private bool Aside { get { return seat != null ? seat.Aside : asideAt == anchor; } }

        private void StopExplore()
        {
            if (!exploring && !exploreBusy) return;
            exploring = false;
            ExploreHold(false);
            exploreWindow = IntPtr.Zero;
            exploreTicket++;
            watchTicket++;
            herPointer.End();
        }

        // Her sign stays up the whole time she explores while they're away, so whoever comes back sees why the page is
        // scrolling, and it goes once their first touch stops her (#106).
        private bool exploreHeld;

        private void ExploreHold(bool on)
        {
            if (on == exploreHeld) return;
            exploreHeld = on;
            if (on) InControl.Begin(); else InControl.End();
        }

        private bool ExploreFree()
        {
            return preferences.ExploreAway && !hidden && !docked && !quitting && !dragging && !pressed && !riding && !onPanel && !GamingOn
                && job == null && working == null && !typer.Visible && !menu.Visible && (!chatting || local) && !pushing && !transcribing && !Hushed && !screenOff && !FullScreen();
        }

        private void CheckExplore(double now)
        {
            if (!preferences.ExploreAway) { StopExplore(); return; }
            long humanQuiet = awayInput.Quiet();
            if (humanQuiet < (long)ExploreAfter * 1000) exploreTired = false;
            // Half an hour is plenty: her wheel counts as input, and past that their screen should get to turn off and their PC to sleep.
            if (exploring && now - exploreBegan >= ExploreFor) exploreTired = true;
            if (exploreTired || !ExploreFree() || humanQuiet < (long)ExploreAfter * 1000 || (exploring && Native.GetForegroundWindow() != exploreWindow)) { StopExplore(); return; }
            if (exploreBusy || now < exploreAt) return;
            exploreAt = now + 4 + random.NextDouble() * 5;
            Sight page = Computer.Glimpse();
            if (!Computer.ExploreAllowed(page, false, true) || page.Window != Native.GetForegroundWindow()) { StopExplore(); return; }
            Point cursorAt = Computer.CursorAt();
            int awayTicket = exploreTicket;
            exploreBusy = true;
            ThreadPool.QueueUserWorkItem(delegate
            {
                Rectangle pageBounds = Rectangle.Empty;
                bool paused = false;
                try
                {
                    paused = Computer.Media(page.Title) && Computer.ExplorePaused(page, Tunes.Shared());
                    pageBounds = Computer.ExplorePage(page, cursorAt, paused);
                }
                catch (Exception) { }
                Post(delegate
                {
                    exploreBusy = false;
                    if (awayTicket != exploreTicket || !ExploreFree() || awayInput.Quiet() < (long)ExploreAfter * 1000) return;
                    Sight still = Computer.Glimpse();
                    if (pageBounds.IsEmpty || still == null || still.Window != page.Window || still.Title != page.Title || Native.GetForegroundWindow() != page.Window || Computer.CursorAt() != cursorAt
                        || Native.GetAncestor(Native.WindowFromPoint(new Native.Point(cursorAt.X, cursorAt.Y)), 2) != page.Window) { StopExplore(); return; }
                    if (!exploring)
                    {
                        exploring = true;
                        ExploreHold(true);
                        exploreBegan = now;
                        exploreWindow = page.Window;
                        herPointer.Begin(Head());
                        nextGlance = now + Math.Min(20, GlanceGap);
                    }
                    exploreFrom = herPointer.Tip;
                    exploreTo = new Point(pageBounds.Left + pageBounds.Width / 4 + random.Next(Math.Max(1, pageBounds.Width / 2)), pageBounds.Top + pageBounds.Height / 4 + random.Next(Math.Max(1, pageBounds.Height / 2)));
                    exploreMoved = clock.Elapsed.TotalSeconds;
                    if (!Computer.ScrollAway(page, pageBounds, still, cursorAt, Computer.CursorAt(), Native.GetAncestor(Native.WindowFromPoint(new Native.Point(cursorAt.X, cursorAt.Y)), 2), FullScreen(),
                        delegate { return awayTicket == exploreTicket && Native.GetForegroundWindow() == page.Window && awayInput.Quiet() >= (long)ExploreAfter * 1000; }, paused)) StopExplore();
                    else { awayInput.Own(); CheckGlance(clock.Elapsed.TotalSeconds, humanQuiet, true); }
                    frames.Start();
                });
            });
        }

        private void MoveExplorePointer(double now)
        {
            if (!exploring) return;
            double progress = Math.Max(0, Math.Min(1, (now - exploreMoved) / 0.8));
            double eased = progress * progress * (3 - 2 * progress);
            herPointer.MoveTo(new Point(exploreFrom.X + (int)((exploreTo.X - exploreFrom.X) * eased), exploreFrom.Y + (int)((exploreTo.Y - exploreFrom.Y) * eased)));
        }

        private void ApplyHidden(bool value)
        {
            if (quitting) return;
            if (value) StopExplore();
            if (docked && !value) { dockHid = true; gaming.Off(); }
            if (value) WakeRest(true);
            outro = null;
            hidden = value;
            visibilityItem.Text = value ? "Show Capri" : "Hide Capri";
            if (value) { SitUp(false); StopRide(); LeavePanel(true); seat = null; falling = false; hanging = false; walking = false; dropAfter = false; pendingClick = false; clickDelay.Stop(); frames.Stop(); Hide(); pill.Hide(); typer.Hide(); CloseTalk(); StopChat(); }
            else { anchor = KeepOnScreen(anchor); Location = anchor; Play(instant || !preferences.Motion ? grin : arrive); Show(); RenderFrame(); UpdateAnimation(); Static(true, Cue.Arrive); }
            mainframe.Sync();
        }

        private void RestoreAtCursor()
        {
            WakeRest(true);
            StopRide();
            LeavePanel(false);
            seat = null;
            falling = false;
            walking = false;
            Rectangle area = Screen.FromPoint(Cursor.Position).WorkingArea;
            anchor = new Point(area.Right - Width - 28, area.Bottom - Height - 12);
            ShowHidden(false);
            DropSoon();
        }

