                    seat = napShelf;
                    Hear(napMessage);
                    Stopwatch napWait = Stopwatch.StartNew();
                    while (napHeard == null && napWait.ElapsedMilliseconds < 3000) { Application.DoEvents(); Thread.Sleep(10); }
                    if (Asleep || napping || napHeard != napMessage || heard != napMessage) throw new Exception("Waking by talking lost what they said: " + napMessage);
                    asking++;
                    CloseTalk();
                }
                Think = napThinkWas;
                checks.Add("PASS talking, a new job and a call request wake her and the same words reach her reply handler");
                napReset();
                Job napJob = new Job("open notepad and type hello");
                job = napJob;
                working = "On it. Esc stops me.";
                int napStops = 0;
                stopTest = delegate { napStops++; };
                string napJobLine = Nap(true);
                napTicks(3600000, 20);
                if (Asleep || !napAsked || job != napJob || napStops != 0 || !napJobLine.Contains("finish this job")) throw new Exception("Sleep interrupted her job or hid what would happen.");
                job = null;
                JobOff(napJob, "done", "Done.");
                napTicks(0, 200);
                if (!Asleep) throw new Exception("She did not sleep after the job ended.");
                napReset();
                job = napJob;
                working = "On it. Esc stops me.";
                Nap(true);
                HeardMidJob("stop", napJob);
                if (napStops != 1) throw new Exception("Stop did not reach the job while her nap waited.");
                job = null;
                JobOff(napJob, "stopped", "Stopped.");
                napTicks(0, 200);
                if (!Asleep) throw new Exception("Her pending nap was lost when the job stopped.");
                checks.Add("PASS a sleep request leaves the job running, says it will finish first, and sleeps after completion or an explicit stop");
                napReset();
                for (int napBlock = 0; napBlock < 10; napBlock++)
                {
                    napReset();
                    nextLie = napNow - 1;
                    if (napBlock == 0) job = new Job("a job");
                    if (napBlock == 1) working = "A job is ending.";
                    if (napBlock == 2) chatting = true;
                    if (napBlock == 3) pushing = true;
                    if (napBlock == 4) transcribing = true;
                    if (napBlock == 5) speech = "Talking.";
                    if (napBlock == 6) musicOn = true;
                    if (napBlock == 7) pressed = true;
                    if (napBlock == 8)
                    {
                        gaming.Find = delegate { return new GameSeen(); }; gaming.Dock = delegate { }; gaming.Undock = delegate { }; gaming.Changed = delegate { };
                        Play(sleep);
                        napping = true;
                        GamingMode("on");
                        if (Asleep || napping) throw new Exception("Asking for Gaming Mode did not wake her.");
                    }
                    if (napBlock == 9) typer.Show();
                    CheckIdle(napNow, 3600000);
                    if (Asleep || ownRest || ownNap || falling) throw new Exception("Her own rest started in blocked state " + napBlock);
                    if (napBlock == 8) gaming.Off();
                }
                napReset();
                nextLie = napNow - 1;
                CheckIdle(napNow, 0);
                if (ownRest || Asleep) throw new Exception("She rested before the PC was quiet.");
                CheckIdle(napNow, 119000);
                if (ownNap || Asleep) throw new Exception("SleepAfter was ignored.");
                napTicks(120001, 200);
                if (!Asleep || napping || !ownNap || !Hushed || nextNap < napNow + NapGap - 10) throw new Exception("Her quiet nap did not follow SleepAfter and its longer gap.");
                CheckIdle(napNow, 0);
                if (Asleep || ownRest) throw new Exception("PC input did not wake her own nap.");
                napTicks(120001, 200);
                if (Asleep) throw new Exception("She started another nap a few seconds later.");
                napReset();
                preferences.SleepAfter = 0;
                nextLie = napNow - 1;
                napTicks(3600000, 200);
                if (!lying || Asleep || !ownRest) throw new Exception("Never stopped an awake lie-down or let her drift off.");
                CheckIdle(napNow + LieStay + LieStaySpread + 1, 3600000);
                if (lying || ownRest || Asleep) throw new Exception("Her own lie-down did not end.");
                checks.Add("PASS quiet rest obeys SleepAfter, spaces naps 25 to 35 minutes apart, ends awake lie-downs, and Never still allows lying; jobs, calls, voice chat, Gaming Mode and interaction keep her awake");
            }
            finally
            {
                if (GamingOn) gaming.Off();
                gaming.Find = napGameWas; gaming.Changed = napGameChangedWas; gaming.Dock = napGameDockWas; gaming.Undock = napGameUndockWas;
                napLedges = napPlacesWas; Think = napThinkWas; stopTest = napStopWas;
                preferences.Motion = napMotionWas; preferences.NoSitting = napSittingWas; preferences.SleepAfter = napAfterWas; preferences.Silent = napSilentWas;
                anchor = napHome; asideAt = napAsideWas; seat = napSeatWas; fallTo = napFallWas; clip = napClipWas; clipStart = napClipStartWas;
                facingLeft = napLeftWas; falling = napFallingWas; hanging = napHangingWas; walking = napWalkingWas; lying = napLyingWas;
                napAsked = napAskedWas; napping = napNappingWas; ownRest = napOwnWas; ownNap = napOwnNapWas; ownLie = napOwnLieWas;
                nextNap = napNextWas; nextLie = napLieWas; restUntil = napUntilWas; voiceUntil = napVoiceWas; meetAt = napMeetWas;
                chatting = napChatWas; musicOn = napMusicWas; danceAsked = napDanceWas; shushed = napShushWas;
                job = napJobWas; working = napWorkWas; speech = napSpeechWas; talkState = napTalkWas;
                pushing = transcribing = pressed = dragging = false;
                if (napTypeWas) typer.Show(); else typer.Hide();
                petTicket++;
                Location = anchor;
                SavePreferences();
            }
        }

        private static Rectangle SpriteBounds(Bitmap strip, int cells)
        {
            int cellWidth = strip.Width / cells;
            int[] stripPixels = new int[strip.Width * strip.Height];
            Pixels(strip, new Rectangle(0, 0, strip.Width, strip.Height), stripPixels, false);
            int opaqueLeft = cellWidth, opaqueTop = strip.Height, opaqueRight = -1, opaqueBottom = -1;
            for (int pixelAt = 0; pixelAt < stripPixels.Length; pixelAt++)
            {
                if ((stripPixels[pixelAt] >> 24 & 255) == 0) continue;
                int opaqueX = pixelAt % strip.Width % cellWidth, opaqueY = pixelAt / strip.Width;
                opaqueLeft = Math.Min(opaqueLeft, opaqueX); opaqueRight = Math.Max(opaqueRight, opaqueX);
                opaqueTop = Math.Min(opaqueTop, opaqueY); opaqueBottom = Math.Max(opaqueBottom, opaqueY);
            }
            return opaqueRight < 0 ? Rectangle.Empty : Rectangle.FromLTRB(opaqueLeft, opaqueTop, opaqueRight + 1, opaqueBottom + 1);
        }

        private void NapScaleChecks(System.Collections.Generic.List<string> checks)
        {
            Rectangle napIdleBounds = SpriteBounds(idle.Strip, idle.Count);
            Rectangle napLieBounds = SpriteBounds(laydown.Strip, laydown.Count);
            Rectangle napSleepBounds = SpriteBounds(laydownSleep.Strip, laydownSleep.Count);
            if (idle.Strip.Width / idle.Count != 116 || idle.Strip.Height != 384 || napIdleBounds != new Rectangle(4, 20, 110, 347)
                || laydown.Strip.Width / laydown.Count != 372 || laydown.Strip.Height != 250 || napLieBounds != new Rectangle(4, 2, 364, 245) || napSleepBounds != new Rectangle(4, 2, 357, 246)) throw new Exception("Her sprite bounds changed; check the lying scale against her idle again.");
            bool scaleLeftWas = facingLeft, scaleLyingWas = lying, scaleVeiledWas = veiled, scaleMotionWas = preferences.Motion;
            double scaleVeilWas = veilUntil, scaleLeanWas = leanAngle;
            Clip scaleClipWas = clip;
            Bitmap scaleFrameWas = frame;
            try
            {
                lying = true;
                veiled = false;
                veilUntil = -1;
                leanAngle = 0;
                preferences.Motion = false;
                Clip[] napArt = { laydown, laydownSleep, laydownTalk, laydownBlink, laydownBlinkGlitch, laydownGlitch, laydownLeave };
                foreach (Clip napDrawing in napArt)
                {
                    if (Math.Abs(napDrawing.Height / napDrawing.Strip.Height - LieScale / 384) > 0.000001f || napDrawing.ShiftY != LieShiftY) throw new Exception("A lying clip uses a different body scale or seat row.");
                    for (int scaleFacing = 0; scaleFacing < 2; scaleFacing++)
                    {
                        facingLeft = scaleFacing != 0;
                        napDrawing.Load(facingLeft);
                        clip = napDrawing;
                        using (Bitmap napImage = new Bitmap(Width, Height, PixelFormat.Format32bppPArgb))
                        {
                            using (Graphics napGraphics = Graphics.FromImage(napImage)) Draw(napGraphics, napDrawing, 0);
                            Rectangle napDrawn = SpriteBounds(napImage, 1);
                            if (napDrawn.IsEmpty || napDrawn.Left <= 0 || napDrawn.Top <= 0 || napDrawn.Right >= Width || napDrawn.Bottom >= Height) throw new Exception("Her lying art was clipped by its window.");
                            Bitmap napStrip = Art(napDrawing);
                            using (Bitmap napCell = napStrip.Clone(new Rectangle(0, 0, napStrip.Width / napDrawing.Count, napStrip.Height), PixelFormat.Format32bppPArgb))
                            {
                                Rectangle napRaw = SpriteBounds(napCell, 1);
                                float napPixelScale = preferences.Size * LieScale / 384;
                                if (Math.Abs(napDrawn.Width - napRaw.Width * napPixelScale) > 4 || Math.Abs(napDrawn.Height - napRaw.Height * napPixelScale) > 4) throw new Exception("Her lying body was drawn at the wrong scale.");
                            }
                            frame = napImage;
                            Point napSolid = Point.Empty;
                            for (int scaleY = napDrawn.Top; scaleY < napDrawn.Bottom && napSolid.IsEmpty; scaleY++)
                                for (int scaleX = napDrawn.Left; scaleX < napDrawn.Right; scaleX++)
                                    if (napImage.GetPixel(scaleX, scaleY).A >= 128) { napSolid = new Point(scaleX, scaleY); break; }
                            if (napSolid.IsEmpty || !Solid(napSolid) || Solid(new Point(napDrawn.Left - 8, napDrawn.Top))) throw new Exception("Her lying hit area did not follow the drawn pixels.");
                            frame = scaleFrameWas;
                        }
                    }
                }
            }
            finally
            {
                frame = scaleFrameWas; clip = scaleClipWas; facingLeft = scaleLeftWas; lying = scaleLyingWas; veiled = scaleVeiledWas;
                veilUntil = scaleVeilWas; leanAngle = scaleLeanWas; preferences.Motion = scaleMotionWas;
            }
            checks.Add("PASS lying sprite scale: idle 116x384 with opaque bounds 4,20 110x347; laydown 372x250 with 4,2 364x245; sleep 4,2 357x246; every lying and flipped clip uses the same 85% scale, keeps its seat row and has a pixel-shaped hit area");
        }

        private static void CheckOcr(System.Collections.Generic.List<string> checks, string output)
        {
            Bitmap discarded = new Bitmap(8, 8);
            discarded.Dispose();
            if (Ocr.Words(null, 1, 1000).Count != 0 || Ocr.Lines(discarded, 1, 1000).Count != 0 || Ocr.Sharpened(discarded, new Rectangle(0, 0, 8, 8), 2) != null)
                throw new Exception("OCR did not ignore a missing or disposed bitmap.");
            using (Bitmap shades = new Bitmap(8, 4))
            {
                using (Graphics paint = Graphics.FromImage(shades))
                using (Brush grey = new SolidBrush(Color.FromArgb(208, 208, 208)))
                {
                    paint.Clear(Color.FromArgb(96, 96, 96));
                    paint.FillRectangle(grey, 4, 0, 4, 4);
                }
                using (Bitmap contrast = Ocr.Sharpened(shades, new Rectangle(-2, -1, 10, 5), 2))
                {
                    if (contrast == null || contrast.Size != new Size(16, 8) || contrast.GetPixel(2, 2).R >= 96 || contrast.GetPixel(12, 2).R <= 208 || shades.GetPixel(1, 1).R != 96)
                        throw new Exception("OCR's crop did not clip, upscale and boost contrast without changing its source.");
                }
                if (Ocr.Words(shades, 0, 1000).Count != 0 || Ocr.Lines(shades, 1, 0).Count != 0 || Ocr.Sharpened(shades, new Rectangle(20, 20, 4, 4), 2) != null)
                    throw new Exception("OCR did not ignore an empty crop, invalid scale or expired timeout.");
            }
            checks.Add("PASS OCR handles missing and disposed bitmaps, empty crops and expired timeouts; sharpening clips, upscales and boosts contrast without changing the frame");
            if (!Ocr.Ready)
            {
                checks.Add("LIMIT Windows OCR has no engine for this PC's languages or English; recognition, HUD digits and timings could not run");
                return;
            }
            using (Bitmap screen = new Bitmap(1920, 1080))
            using (Font plain = new Font("Arial", 28, FontStyle.Regular, GraphicsUnit.Pixel))
            {
                string[] known = { "Capri", "words", "Ready" };
                Point[] places = { new Point(64, 72), new Point(520, 420), new Point(1240, 940) };
                Rectangle[] expected = new Rectangle[known.Length];
                using (Graphics drawing = Graphics.FromImage(screen))
                {
                    drawing.Clear(Color.White);
                    drawing.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;
                    for (int label = 0; label < known.Length; label++)
                    {
                        drawing.DrawString(known[label], plain, Brushes.Black, places[label]);
                        expected[label] = Rectangle.Ceiling(new RectangleF(places[label], drawing.MeasureString(known[label], plain)));
                        expected[label].Inflate(3, 3);
                    }
                }
                screen.Save(Path.Combine(output, "ocr-screen.png"), ImageFormat.Png);
                foreach (int enlargement in new int[] { 1, 2 })
                {
                    System.Collections.Generic.List<ReadWord> words = Ocr.Words(screen, enlargement, 10000);
                    foreach (ReadWord word in words) if (word.Box.Width <= 0 || word.Box.Height <= 0 || !new Rectangle(Point.Empty, screen.Size).Contains(word.Box)) throw new Exception("OCR returned a box outside its frame.");
                    for (int wanted = 0; wanted < known.Length; wanted++)
                    {
                        bool located = false;
                        foreach (ReadWord candidate in words) if (string.Equals(candidate.Text, known[wanted], StringComparison.OrdinalIgnoreCase) && expected[wanted].Contains(candidate.Box)) located = true;
                        if (!located) throw new Exception("OCR missed " + known[wanted] + " or put its box in the wrong place at scale " + enlargement + ".");
                    }
                }
                System.Collections.Generic.List<string> lines = Ocr.Lines(screen, 1, 10000);
                if (lines.Count != known.Length) throw new Exception("OCR returned the wrong number of plain lines: " + string.Join(" / ", lines));
                for (int ordered = 0; ordered < known.Length; ordered++) if (!string.Equals(lines[ordered], known[ordered], StringComparison.OrdinalIgnoreCase)) throw new Exception("OCR's lines were not top to bottom: " + string.Join(" / ", lines));
                checks.Add("PASS Windows OCR reads known words at scales 1 and 2 with boxes in original frame pixels and lines top to bottom");
                Sight unread = new Sight { Window = new IntPtr(5) };
                unread.Targets.Add(new Target { Number = 2, Role = "button", Name = "Close", Value = "" });
                Computer.ReadWords(unread, Picture.Of(screen, new Rectangle(100, 200, screen.Width, screen.Height)));
                Target capriWords = unread.Targets.Find(found => found.Role == "words" && found.Name == "Capri");
                if (capriWords == null || capriWords.Number <= 2 || capriWords.Box.Left < 100 + 64 - 16 || capriWords.Box.Left > 100 + 64 + 16 || capriWords.Box.Top < 200 + 72 - 16 || capriWords.Box.Top > 200 + 72 + 24) throw new Exception("Words on screen didn't become something to click where they are.");
                using (Bitmap crop = screen.Clone(new Rectangle(40, 40, 400, 200), PixelFormat.Format32bppArgb))
                {
                    for (int expired = 0; expired < 3; expired++) using (Bitmap brief = (Bitmap)crop.Clone()) Ocr.Words(brief, 1, 1);
                    System.Collections.Generic.List<ReadWord> recovered = Ocr.Words(crop, 1, 10000);
                    if (recovered.Count != 1 || !string.Equals(recovered[0].Text, known[0], StringComparison.OrdinalIgnoreCase) || recovered[0].Box.X >= 64 || recovered[0].Box.Y >= 72)
                        throw new Exception("OCR did not recover after short timeouts or return crop-local boxes.");
                    System.Threading.Tasks.Task<System.Collections.Generic.List<ReadWord>> together = System.Threading.Tasks.Task.Run(delegate { return Ocr.Words(screen, 1, 10000); });
                    System.Collections.Generic.List<string> beside = Ocr.Lines(crop, 1, 10000);
                    if (!together.Wait(10000) || together.Result.Count != known.Length || beside.Count != 1) throw new Exception("Concurrent OCR calls did not both finish.");
                    checks.Add("PASS OCR recovers after short timeouts and immediate source disposal, keeps crop-local boxes and serializes concurrent recognition");
                    foreach (Bitmap sized in new Bitmap[] { screen, crop })
                    {
                        double[] times = new double[5];
                        for (int sample = 0; sample < times.Length; sample++)
                        {
                            Stopwatch elapsed = Stopwatch.StartNew();
                            System.Collections.Generic.List<ReadWord> measured = Ocr.Words(sized, 1, 10000);
                            times[sample] = elapsed.Elapsed.TotalMilliseconds;
                            if (measured.Count != (sized == screen ? known.Length : 1)) throw new Exception("OCR timing run did not read its words.");
                        }
                        Array.Sort(times);
                        checks.Add("PASS OCR timing " + sized.Width + "x" + sized.Height + ": median " + times[2].ToString("F1", System.Globalization.CultureInfo.InvariantCulture) + " ms (" + times[0].ToString("F1", System.Globalization.CultureInfo.InvariantCulture) + "-" + times[4].ToString("F1", System.Globalization.CultureInfo.InvariantCulture) + " ms, 5 warm reads, scale 1, conversion included)");
                    }
                }
            }
            using (Bitmap hud = new Bitmap(520, 150, PixelFormat.Format32bppArgb))
            using (Font mono = new Font("Lucida Console", 12, FontStyle.Regular, GraphicsUnit.Pixel))
            {
                Random noise = new Random(1234);
                int[] background = new int[hud.Width * hud.Height];
                for (int pixel = 0; pixel < background.Length; pixel++) background[pixel] = Color.FromArgb(noise.Next(30, 145), noise.Next(30, 145), noise.Next(30, 145)).ToArgb();
                BitmapData texture = hud.LockBits(new Rectangle(Point.Empty, hud.Size), ImageLockMode.WriteOnly, PixelFormat.Format32bppArgb);
                try { for (int stripe = 0; stripe < hud.Height; stripe++) Marshal.Copy(background, stripe * hud.Width, new IntPtr(texture.Scan0.ToInt64() + (long)stripe * texture.Stride), hud.Width); }
                finally { hud.UnlockBits(texture); }
                string[] hudText = { "XYZ: 123.456 / 64.000 / -78.900", "Facing: north (Towards negative Z) (-179.9 / 12.3)" };
                using (Graphics lettering = Graphics.FromImage(hud))
                {
                    lettering.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;
                    for (int hudRow = 0; hudRow < hudText.Length; hudRow++)
                    {
                        lettering.DrawString(hudText[hudRow], mono, Brushes.Black, 29, 29 + hudRow * 28);
                        lettering.DrawString(hudText[hudRow], mono, Brushes.White, 28, 28 + hudRow * 28);
                    }
                }
                hud.Save(Path.Combine(output, "ocr-hud.png"), ImageFormat.Png);
                using (Bitmap sharpened = Ocr.Sharpened(hud, new Rectangle(16, 12, 488, 112), 4))
                {
                    if (sharpened == null || sharpened.Size != new Size(1952, 448)) throw new Exception("OCR's HUD crop did not upscale.");
                    sharpened.Save(Path.Combine(output, "ocr-hud-sharpened.png"), ImageFormat.Png);
                    System.Collections.Generic.List<string> hudLines = Ocr.Lines(sharpened, 1, 10000);
                    string readHud = string.Join(" / ", hudLines);
                    MatchCollection numbers = Regex.Matches(readHud, @"-?\d+(?:\.\d+)?");
                    string[] digits = { "123.456", "64.000", "-78.900", "-179.9", "12.3" };
                    if (hudLines.Count != 2 || numbers.Count != digits.Length) throw new Exception("OCR lost HUD lines or numbers: " + readHud);
                    for (int number = 0; number < digits.Length; number++) if (numbers[number].Value != digits[number]) throw new Exception("OCR changed a HUD digit, decimal point or minus sign: " + readHud);
                    checks.Add("PASS OCR reads a 12 px monospace HUD, white with a dark shadow on noise, after sharpening at scale 4: " + readHud);
                }
            }
        }

        // Her clones and your windows (lance, 1 Nov: chaos mode "need more... OUMF"). A section of its own, since it needs a real
        // window on a real screen, and a problem there mustn't leave the checks after it in a muddle.
        // Throwing her (Zr4, F63 and F44), each part in a Section of its own so one failure can't hide the rest: drags at known
        // speeds through her mouse handlers, her flight against her screen's edges and a stand-in window, reduced motion, and her
        // grudge, with a stand-in cursor and her sounds kept off the speakers.
        private void SmokeThrows(System.Collections.Generic.List<string> checks)
        {
            Section(checks, "SmokeThrowReads", delegate { SmokeThrowReads(checks); });
            Section(checks, "SmokeThrowSlow", delegate { ThrowCheck(checks, SmokeThrowSlow); });
            Section(checks, "SmokeThrowFast", delegate { ThrowCheck(checks, SmokeThrowFast); });
            Section(checks, "SmokeThrowUp", delegate { ThrowCheck(checks, SmokeThrowUp); });
            Section(checks, "SmokeThrowSlam", delegate { ThrowCheck(checks, SmokeThrowSlam); });
            Section(checks, "SmokeThrowStanding", delegate { ThrowCheck(checks, SmokeThrowStanding); });
            Section(checks, "SmokeThrowCatch", delegate { ThrowCheck(checks, SmokeThrowCatch); });
            Section(checks, "SmokeThrowCalm", delegate { ThrowCheck(checks, SmokeThrowCalm); });
            Section(checks, "SmokeThrowGrudge", delegate { ThrowCheck(checks, SmokeThrowGrudge); });
            Section(checks, "SmokeThrowDodges", delegate { ThrowCheck(checks, SmokeThrowDodges); });
            Section(checks, "SmokeThrowSorry", delegate { ThrowCheck(checks, SmokeThrowSorry); });
            Section(checks, "SmokeThrowPat", delegate { ThrowCheck(checks, SmokeThrowPat); });
            Section(checks, "SmokeThrowAlone", delegate { ThrowCheck(checks, SmokeThrowAlone); });
            checks.Add("LIMIT throwing her for real: how a flick off a real mouse feels, her tumble, bounces, tear and dizzy sway on a real screen, her thud on real speakers, and her hopping away from a real cursor need a person at the desk");
        }

        // One throwing check with her state saved first and put back after however it ends. During it she sits on windows, motion
        // and head pats are on, nothing animates, she faces right, nothing's full screen, and her sounds are caught, not played.
        private void ThrowCheck(System.Collections.Generic.List<string> checks, Action<System.Collections.Generic.List<string>, System.Collections.Generic.List<short[]>> run)
        {
            Point anchorWas = anchor;
            Ledge seatWas = seat;
            Clip clipWas = clip;
            Action outroWas = outro;
            bool motionWas = preferences.Motion, sittingWas = preferences.NoSitting, patsWas = preferences.NoHeadPats, instantWas = instant, facedWas = facingLeft, busyWas = frontBusy;
            bool walkingWas = walking, hangingWas = hanging, lyingWas = lying, dropWas = dropAfter, spawnWas = spawnFall;
            long petAtWas = petAt;
            Func<Point> mouseWas = MouseAt;
            Action<short[]> soundWas = Sfx.Out;
            int levelWas = Sfx.Level;
            System.Collections.Generic.List<short[]> sounds = new System.Collections.Generic.List<short[]>();
            try
            {
                CloseTalk();
                tear.Hide();
                preferences.NoSitting = false;
                preferences.Motion = true;
                preferences.NoHeadPats = false;
                instant = true;
                facingLeft = false;
                frontBusy = false;
                throwsAt.Clear();
                sulkSince = -1;
                dizzyFrom = dizzyUntil = dizzyGlitchAt = -1;
                pendingClick = false;
                clickDelay.Stop();
                Sfx.Out = delegate(short[] sound) { sounds.Add(sound); };
                Sfx.Level = 60;
                run(checks, sounds);
            }
            finally
            {
                MouseAt = mouseWas;
                Sfx.Out = soundWas;
                Sfx.Level = levelWas;
                preferences.Motion = motionWas;
                preferences.NoSitting = sittingWas;
                preferences.NoHeadPats = patsWas;
                instant = instantWas;
                frontBusy = busyWas;
                sulkSince = -1;
                sulkLine = patForgives = false;
                throwsAt.Clear();
                dizzyFrom = dizzyUntil = dizzyGlitchAt = -1;
                pressed = dragging = caught = false;
                Capture = false;
                pendingClick = false;
                clickDelay.Stop();
                falling = thrown = false;
                fallTo = null;
                petTicket++;
                petAt = petAtWas;
                CloseTalk();
                tear.Hide();
                outro = outroWas;
                walking = walkingWas;
                hanging = hangingWas;
                lying = lyingWas;
                dropAfter = dropWas;
                spawnFall = spawnWas;
                facingLeft = facedWas;
                seat = seatWas;
                anchor = anchorWas;
                Location = anchor;
                Play(clipWas ?? idle);
                RenderFrame();
            }
        }

        // A stand-in window halfway down her main screen, with nothing else near its top edge, for her to land on.
        private Shelf ThrowShelf()
        {
            Rectangle work = Screen.PrimaryScreen.WorkingArea;
            int middle = work.Left + work.Width / 2, clear = Math.Max(160, preferences.Size) + 60;
            System.Collections.Generic.List<Ledge> others = Ledges.Find(Skip(), icons);
            int shelfY = work.Top + work.Height / 2;
            for (int y = Math.Max(work.Top + Headroom() + 20, work.Top + work.Height / 2 - 60); y < work.Bottom - 240; y += 10)
                if (!others.Exists(other => !other.Floor && other.Icon.IsEmpty && other.Right > middle - 280 && other.Left < middle + 280 && Math.Abs(other.Y - y) < clear)) { shelfY = y; break; }
            Shelf shelf = new Shelf();
            shelf.Bounds = new Rectangle(middle - 220, shelfY, 440, 180);
            shelf.Show();
            return shelf;
        }

        // Her hip at hip, standing on nothing, ready to be picked up.
        private void StandForThrow(Point hip)
        {
            seat = null;
            falling = thrown = false;
            walking = hanging = lying = false;
            anchor = Seated(hip.X, hip.Y);
            Location = anchor;
            Play(idle);
        }

        // A drag through her mouse handlers at a known speed: pressed on her, moved dx, dy every 16 ms, and let go 4 ms after the
        // last move. Over the last 80 ms that's 4.75 moves, so 59.375 times a move a second.
        private void DragAndLetGo(int dx, int dy, int moves)
        {
            OnMouseDown(new MouseEventArgs(MouseButtons.Left, 1, Width / 2, Height / 2, 0));
            if (!pressed || trail.Count == 0) throw new Exception("A press on her didn't take hold of her.");
            double pressedAt = trail[0].Key;
            Point from = pointerStart;
            for (int i = 1; i <= moves; i++) MovePointer(new Point(from.X + dx * i, from.Y + dy * i), pressedAt + i * 0.016);
            Released(new Point(from.X + dx * moves, from.Y + dy * moves), pressedAt + moves * 0.016 + 0.004);
        }

        // What her flight looked like, frame by frame at 60 a second, until she was down.
        private sealed class FlightSeen
        {
            internal string Wrong;
            internal float Turned, LastTurn;
            internal int Rightmost = int.MinValue, Frames;
            internal bool TurnedBack, CameBack;
        }

        private FlightSeen WatchFlight()
        {
            FlightSeen seen = new FlightSeen();
            Rectangle room = flyArea, screen = Screen.FromRectangle(flyArea).Bounds;
            bool goingRight = flyVX > 0;
            for (int tick = 0; tick < 900 && falling; tick++)
            {
                Tumble(fallStep + 1 / 60.0);
                if (!falling) break;
                seen.Frames++;
                if (thrown && FrameInterval(fallStep) != 15) seen.Wrong = "she was drawn every " + FrameInterval(fallStep) + " ms in the air";
                Rectangle body = BodyOnScreen(anchor, Body);
                if (!screen.Contains(body) || body.Left < room.Left || body.Right > room.Right || body.Top < room.Top) seen.Wrong = "she left her screen at " + body + " on " + room;
                seen.Turned = Math.Max(seen.Turned, Math.Abs(Turn()));
                seen.LastTurn = Turn();
                seen.Rightmost = Math.Max(seen.Rightmost, body.Right);
                // Only her screen's right edge turns a throw to the right back.
                if (goingRight && thrown && flyVX < 0) seen.TurnedBack = true;
                if (seen.TurnedBack && body.Right < room.Right - 40) seen.CameBack = true;
            }
            if (falling) seen.Wrong = "she never came down";
            return seen;
        }

        // How far from upright she was, in degrees.
        private static double OffUpright(float turn) { return Math.Abs(turn - 360 * Math.Round(turn / 360.0)); }

        // Their cursor's speed as they let go, and what counts as saying sorry.
        private void SmokeThrowReads(System.Collections.Generic.List<string> checks)
        {
            System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<double, Point>> track = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<double, Point>>();
            for (int i = 0; i <= 12; i++) track.Add(new System.Collections.Generic.KeyValuePair<double, Point>(10 + i * 0.016, new Point(100 + i * 10, 300 - i * 6)));
            PointF steady = TrailSpeed(track, 10 + 12 * 0.016 + 0.004, ThrowSpan), stopped = TrailSpeed(track, 10 + 12 * 0.016 + 0.12, ThrowSpan);
            System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<double, Point>> flick = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<double, Point>>();
            flick.Add(new System.Collections.Generic.KeyValuePair<double, Point>(10, new Point(500, 500)));
            for (int i = 0; i < 3; i++) flick.Add(new System.Collections.Generic.KeyValuePair<double, Point>(12 + i * 0.01, new Point(550 + i * 50, 500)));
            PointF flicked = TrailSpeed(flick, 12.025, ThrowSpan);
            if (Math.Abs(steady.X - 625) > 60 || Math.Abs(steady.Y + 375) > 40 || stopped.X != 0 || stopped.Y != 0 || flicked.X < 1800 || flicked.Y != 0)
                throw new Exception("Her cursor's speed read wrong: steady " + steady + ", stopped " + stopped + ", a flick after a wait " + flicked);
            System.Collections.Generic.List<string> wrong = new System.Collections.Generic.List<string>();
            foreach (string said in new[] { "sorry", "I'm sorry Capri", "my bad lol", "soooo sorry!!", "sorry for throwing you", "lo siento", "ごめんね" })
                if (!Apology(said)) wrong.Add("she didn't hear an apology in \"" + said + "\"");
            foreach (string said in new[] { "open spotify", "the sorrow of it", "" })
                if (Apology(said)) wrong.Add("she heard an apology in \"" + said + "\"");
            foreach (string said in new[] { "I'm sorry Capri", "sorry for throwing you", "soooo sorry!!" })
                if (!OnlyApology(said)) wrong.Add("\"" + said + "\" wasn't a plain sorry");
            foreach (string said in new[] { "sorry, can you open spotify", "open spotify" })
                if (OnlyApology(said)) wrong.Add("\"" + said + "\" was a plain sorry");
            if (wrong.Count > 0) throw new Exception("Saying sorry to her read wrong: " + string.Join("; ", wrong.ToArray()));
            checks.Add("PASS throwing her: their cursor's speed as they let go reads true for a steady drag, still once it stopped, and a flick after holding still isn't spread over the wait; she hears sorry, I'm sorry Capri, my bad and sorry in a few other languages, and tells a plain sorry from one with more in it");
        }

        // Slow drags drop her onto the window under her like before, one of them just under throwing speed.
        private void SmokeThrowSlow(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            System.Collections.Generic.List<string> wrong = new System.Collections.Generic.List<string>();
            using (Shelf shelf = ThrowShelf())
            {
                foreach (int[] slow in new[] { new[] { 4, 0, 8 }, new[] { 20, 0, 6 } })
                {
                    StandForThrow(new Point(shelf.Left + 160, shelf.Top - 12));
                    DragAndLetGo(slow[0], slow[1], slow[2]);
                    bool dropped = falling && !thrown && fallTo != null && fallTo.Window == shelf.Handle;
                    for (int i = 0; i < 60 && falling; i++) Tumble(fallStep + 0.033);
                    if (!dropped || seat == null || seat.Window != shelf.Handle || Hip().Y != shelf.Top) wrong.Add("a drag of " + slow[0] + " px every 16 ms: dropped " + dropped + ", thrown " + thrown + ", sat on the window " + (seat != null && seat.Window == shelf.Handle) + " at " + Hip() + " for " + shelf.Top);
                }
            }
            if (wrong.Count > 0) throw new Exception("A slow drag didn't drop her like before: " + string.Join("; ", wrong.ToArray()));
            checks.Add("PASS a slow drag and one just under throwing speed both drop her onto the window under her like before, without throwing her");
        }

        // A fast drag throws her at its speed: she yells, hits the right edge of her screen and comes back off it, bounces on the
        // taskbar, tumbles and rights herself, lands, never leaves her screen, is drawn every 1/64 s in the air, and is dizzy for a
        // beat after. A wild flick is kept to her top speed and stays on her screen too.
        private void SmokeThrowFast(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            double scale = TalkScale();
            int size = preferences.Size;
            Rectangle work = Screen.PrimaryScreen.WorkingArea;
            int middle = work.Left + work.Width / 2, dx = (int)Math.Round(60 * scale), dy = (int)Math.Round(-30 * scale);
            System.Collections.Generic.List<string> wrong = new System.Collections.Generic.List<string>();
            StandForThrow(new Point(middle, work.Top + work.Height / 2 - 72));
            int bumpsBefore = bumps;
            DragAndLetGo(dx, dy, 6);
            double speed = Math.Sqrt(flyVX * flyVX + flyVY * flyVY);
            if (!Flying || clip != dangle || Math.Abs(flyVX - 59.375 * dx) > 2 || Math.Abs(flyVY - 59.375 * dy) > 2) wrong.Add("she didn't fly at their cursor's speed: flying " + Flying + " at " + (int)flyVX + ", " + (int)flyVY + " for " + (int)(59.375 * dx) + ", " + (int)(59.375 * dy));
            if (Array.IndexOf(ThrowLines, reply) < 0 || heard != "throws you" || box.Prompt != "> sys: ") wrong.Add("she didn't yell as she flew: " + reply + " / " + heard);
            frontBusy = true;
            int overGame = FrameInterval(fallStep);
            frontBusy = false;
            if (overGame != 33) wrong.Add("over a game she was drawn every " + overGame + " ms in the air, not 33");
            FlightSeen seen = WatchFlight();
            if (seen.Wrong != null) wrong.Add(seen.Wrong);
            if (!seen.TurnedBack || !seen.CameBack || seen.Rightmost < flyArea.Right - size / 4) wrong.Add("she didn't bounce back off the right edge of her screen: got to " + seen.Rightmost + " of " + flyArea.Right + ", turned back " + seen.TurnedBack + ", came back " + seen.CameBack);
            if (flyFloors < 1) wrong.Add("she didn't bounce on the taskbar");
            if (bumps == bumpsBefore) wrong.Add("no impact was hard enough to thud");
            bool landed = !falling && !thrown && seat != null && (seat.Floor || seat.Window != IntPtr.Zero) && Hip().Y == seat.Y;
            if (!landed) wrong.Add("she didn't land on a ledge: falling " + falling + ", seat " + (seat != null) + ", hip " + Hip());
            if (seen.Turned < 90) wrong.Add("she only tumbled " + (int)seen.Turned + " degrees");
            if (landed && seat.Floor && OffUpright(seen.LastTurn) > 45) wrong.Add("she was " + (int)OffUpright(seen.LastTurn) + " degrees off upright just before she landed on the taskbar");
            if (!Dizzy(fallStep) || Sway(dizzyFrom + 0.25) == 0 || Sway(dizzyUntil + 0.1) != 0 || FrameInterval(dizzyFrom + 0.25) != 33 || Array.IndexOf(DizzyLines, reply) < 0) wrong.Add("she wasn't dizzy for a beat after: dizzy " + Dizzy(fallStep) + ", sway " + Sway(dizzyFrom + 0.25) + ", said " + reply);
            int bounces = flyBounces, floors = flyFloors;
            CloseTalk();
            throwsAt.Clear();
            StandForThrow(new Point(middle, work.Top + work.Height / 2));
            DragAndLetGo((int)Math.Round(300 * scale), 0, 3);
            double wild = Math.Sqrt(flyVX * flyVX + flyVY * flyVY);
            if (!Flying || Math.Abs(wild - ThrowMost * scale) > 1) wrong.Add("a wild flick flew at " + (int)wild + " px/s, not " + (int)(ThrowMost * scale));
            FlightSeen wildSeen = WatchFlight();
            if (wildSeen.Wrong != null) wrong.Add("a wild flick: " + wildSeen.Wrong);
            if (wrong.Count > 0) throw new Exception("Throwing her fast went wrong: " + string.Join("; ", wrong.ToArray()));
            checks.Add("PASS a fast drag throws her at its speed (" + (int)speed + " px/s): she yells, hits the right edge of her screen and bounces back off it, bounces on the taskbar (" + bounces + " bounces in all, " + floors + " on the taskbar), tumbles and rights herself, lands, never leaves her screen, is drawn every 1/64 s in the air and every 33 ms over a game, and is dizzy for a beat after; a wild flick is kept to " + (int)(ThrowMost * scale) + " px/s and stays on her screen too");
        }

        // Thrown straight up off a window, she comes back down onto it.
        private void SmokeThrowUp(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            double scale = TalkScale();
            using (Shelf shelf = ThrowShelf())
            {
                StandForThrow(new Point(shelf.Left + 220, shelf.Top - 12));
                DragAndLetGo(0, (int)Math.Round(-26 * scale), 6);
                bool up = Flying && flyVY < 0 && Math.Abs(flyVX) < 1;
                FlightSeen seen = WatchFlight();
                if (!up || seen.Wrong != null || seat == null || seat.Window != shelf.Handle || Hip().Y != shelf.Top)
                    throw new Exception("Thrown straight up off a window she didn't come back down onto it: thrown up " + up + ", " + (seen.Wrong ?? "stayed on her screen") + ", on the window " + (seat != null && seat.Window == shelf.Handle) + ", hip " + Hip() + " for " + shelf.Top);
            }
            checks.Add("PASS thrown straight up off a window she comes back down and lands on it");
        }

        // Thrown hard down onto the taskbar, she bounces on it before she settles there, upright.
        private void SmokeThrowSlam(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            double scale = TalkScale();
            Rectangle work = Screen.PrimaryScreen.WorkingArea;
            StandForThrow(new Point(work.Left + preferences.Size, work.Top + work.Height / 3));
            DragAndLetGo(0, (int)Math.Round(50 * scale), 4);
            bool down = Flying && flyVY > 0;
            FlightSeen seen = WatchFlight();
            if (!down || seen.Wrong != null || flyFloors < 1 || seat == null || !seat.Floor || seat.Y != work.Bottom || Hip().Y != work.Bottom || OffUpright(seen.LastTurn) > 45)
                throw new Exception("Slammed down she didn't bounce on the taskbar and land on it: thrown down " + down + ", " + (seen.Wrong ?? "stayed on her screen") + ", " + flyFloors + " taskbar bounces, on the taskbar " + (seat != null && seat.Floor) + ", hip " + Hip() + " for " + work.Bottom + ", " + (int)OffUpright(seen.LastTurn) + " degrees off upright");
            checks.Add("PASS slammed down onto the taskbar she bounces on it " + flyFloors + " times, then lands on it upright without leaving her screen");
        }

        // With Sit on windows off, a throw still flies, and she ends up standing on the bottom of her screen's work area.
        private void SmokeThrowStanding(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            double scale = TalkScale();
            Rectangle work = Screen.PrimaryScreen.WorkingArea;
            preferences.NoSitting = true;
            StandForThrow(new Point(work.Left + work.Width / 2, work.Top + work.Height / 2 - 72));
            DragAndLetGo((int)Math.Round(60 * scale), (int)Math.Round(-30 * scale), 6);
            bool flew = Flying;
            FlightSeen seen = WatchFlight();
            Rectangle body = BodyOnScreen(anchor, Body);
            if (!flew || seen.Wrong != null || falling || seat != null || body.Bottom != work.Bottom)
                throw new Exception("With Sit on windows off a throw went wrong: flew " + flew + ", " + (seen.Wrong ?? "stayed on her screen") + ", falling " + falling + ", seat " + (seat != null) + ", feet at " + body.Bottom + " for " + work.Bottom);
            checks.Add("PASS with Sit on windows off a throw still flies and bounces, and she ends up standing on the bottom of her screen's work area");
        }

        // A press on her mid-flight catches her in their hand where she is, and letting go without a drag lets her fall from there.
        private void SmokeThrowCatch(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            double scale = TalkScale();
            Rectangle work = Screen.PrimaryScreen.WorkingArea;
            StandForThrow(new Point(work.Left + work.Width / 2, work.Top + work.Height / 4));
            Launch(900 * scale, -1500 * scale, clock.Elapsed.TotalSeconds);
            for (int i = 0; i < 5; i++) Tumble(fallStep + 1 / 60.0);
            bool flying = Flying;
            Point caughtAt = anchor;
            OnMouseDown(new MouseEventArgs(MouseButtons.Left, 1, Width / 2, Height / 2, 0));
            bool held = flying && pressed && caught && !falling && !thrown && clip == dangle && anchor == caughtAt;
            Released(PointToScreen(new Point(Width / 2, Height / 2)), clock.Elapsed.TotalSeconds);
            bool letFall = falling && !thrown;
            pendingClick = false;
            clickDelay.Stop();
            for (int i = 0; i < 400 && falling; i++) Tumble(fallStep + 0.033);
            letFall &= seat != null && Hip().Y == seat.Y;
            if (!held || !letFall) throw new Exception("Catching her mid-flight went wrong: flying " + flying + ", caught " + held + ", fell after " + letFall);
            checks.Add("PASS a press on her mid-flight catches her in their hand where she is, and letting go without a drag lets her fall from there onto a ledge");
        }

        // Reduced motion: the same throw from the same spot at the same times flies the same path, with no tumble, screen tear or
        // dizzy sway, and her thud still plays.
        private void SmokeThrowCalm(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            double scale = TalkScale();
            Rectangle work = Screen.PrimaryScreen.WorkingArea;
            Point hip = new Point(work.Left + work.Width / 2 + 60, work.Top + work.Height / 4);
            double at = clock.Elapsed.TotalSeconds;
            System.Collections.Generic.List<Point>[] paths = { new System.Collections.Generic.List<Point>(), new System.Collections.Generic.List<Point>() };
            int[] thuds = new int[2];
            bool[] tore = new bool[2], swayed = new bool[2];
            float[] tumbled = new float[2];
            int thudLength = Sfx.Make(Cue.Bonk, 60).Length;
            instant = false;
            for (int run = 0; run < 2; run++)
            {
                preferences.Motion = run == 0;
                CloseTalk();
                tear.Hide();
                sounds.Clear();
                StandForThrow(hip);
                Launch(4000 * scale, -2600 * scale, at);
                for (int k = 1; k <= 900 && falling; k++)
                {
                    Tumble(at + k / 60.0);
                    paths[run].Add(anchor);
                    tumbled[run] = Math.Max(tumbled[run], Math.Abs(Turn()));
                }
                thuds[run] = sounds.FindAll(sound => sound.Length == thudLength).Count;
                tore[run] = tear.Visible;
                swayed[run] = Dizzy(fallStep) && Sway(dizzyFrom + 0.25) != 0;
            }
            instant = true;
            bool samePath = paths[0].Count > 0 && paths[0].Count == paths[1].Count && !falling;
            for (int i = 0; samePath && i < paths[0].Count; i++) if (paths[0][i] != paths[1][i]) samePath = false;
            if (!samePath || tumbled[0] < 30 || tumbled[1] != 0 || !tore[0] || tore[1] || !swayed[0] || swayed[1] || thuds[0] == 0 || thuds[1] != thuds[0])
                throw new Exception("Reduced motion went wrong: same path " + samePath + " (" + paths[0].Count + " / " + paths[1].Count + " frames), tumble " + tumbled[0] + " / " + tumbled[1] + ", tear " + tore[0] + " / " + tore[1] + ", sway " + swayed[0] + " / " + swayed[1] + ", thuds " + thuds[0] + " / " + thuds[1]);
            checks.Add("PASS reduced motion: the same throw flies the same path frame for frame (" + paths[0].Count + " frames), with no tumble, no screen tear and no dizzy sway, and her thud still plays on each hard bounce (" + thuds[0] + ")");
        }

        // Three throws in two minutes: a soft first one gets no line, the second a warning, the third her sulk, said once she's
        // down. Throws further apart than that don't add up.
        private void SmokeThrowGrudge(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            double scale = TalkScale();
            Rectangle work = Screen.PrimaryScreen.WorkingArea;
            int middle = work.Left + work.Width / 2;
            string[] said = new string[3];
            bool[] sulking = new bool[3];
            for (int n = 0; n < 3; n++)
            {
                CloseTalk();
                StandForThrow(new Point(middle - 100, work.Top + work.Height / 2 - 84));
                DragAndLetGo((int)Math.Round(36 * scale), (int)Math.Round(-12 * scale), 6);
                said[n] = reply;
                sulking[n] = Sulking;
                FlightSeen seen = WatchFlight();
                if (seen.Wrong != null) throw new Exception("Throw " + (n + 1) + " toward her grudge went wrong: " + seen.Wrong);
            }
            bool sulked = !sulking[0] && !sulking[1] && sulking[2] && Sulking && !sulkLine && said[0] == null && Array.IndexOf(WarnLines, said[1]) >= 0 && Array.IndexOf(SulkLines, reply) >= 0 && seat != null;
            string sulkSaid = reply;
            sulkSince = -1;
            throwsAt.Clear();
            double at = clock.Elapsed.TotalSeconds;
            Grudge(1500, at);
            Grudge(1500, at + SulkWindow + 1);
            Grudge(1500, at + SulkWindow * 2 + 2);
            bool apart = !Sulking && throwsAt.Count == 1;
            if (!sulked || !apart) throw new Exception("Her grudge went wrong: sulking after each throw " + sulking[0] + ", " + sulking[1] + ", " + sulking[2] + "; said " + said[0] + " / " + said[1] + " / " + sulkSaid + "; throws two minutes apart added up " + !apart);
            checks.Add("PASS her grudge: a soft first throw gets no line, the second in two minutes gets a warning, and the third starts her sulk, which she says once she's down; throws more than two minutes apart don't add up");
        }

        // Sulking, a press on her doesn't pick her up but glitches her a short hop along her ledge with her first line. Their
        // cursor coming at her fast gets a hop too, and one that comes slowly reaches her, so a head pat still can.
        private void SmokeThrowDodges(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            int size = preferences.Size;
            Rectangle work = Screen.PrimaryScreen.WorkingArea;
            StandForThrow(new Point(work.Left + work.Width / 2, work.Bottom));
            Land(new Ledge { Floor = true, Left = work.Left, Right = work.Right, Y = work.Bottom });
            if (seat == null) throw new Exception("She couldn't be sat on the taskbar for the dodge checks.");
            Sulk(clock.Elapsed.TotalSeconds);
            CloseTalk();
            System.Collections.Generic.List<string> wrong = new System.Collections.Generic.List<string>();
            int dodgesBefore = dodges;
            Point hipBefore = Hip();
            Point cursorAt = new Point(hipBefore.X, hipBefore.Y - size / 3);
            MouseAt = delegate { return cursorAt; };
            OnMouseDown(new MouseEventArgs(MouseButtons.Left, 1, Width / 2, Height / 2, 0));
            Rectangle screen = Screen.FromPoint(hipBefore).Bounds, body = BodyOnScreen(anchor, seat != null ? PerchedBody : Body);
            if (pressed || dragging || dodges != dodgesBefore + 1) wrong.Add("a press picked her up or didn't hop her away: pressed " + pressed + ", dodges " + (dodges - dodgesBefore));
            if (seat == null || Hip().Y != hipBefore.Y || Math.Abs(Hip().X - hipBefore.X) < size / 4) wrong.Add("her hop from a press didn't go along her ledge: " + hipBefore + " to " + Hip());
            if (body.Left < screen.Left || body.Right > screen.Right || body.Top < screen.Top) wrong.Add("her hop took her off her screen: " + body);
            if (reply != FirstDodgeLine) wrong.Add("her first hop said " + reply);
            double approachAt = clock.Elapsed.TotalSeconds + DodgeGap + 0.5;
            Rectangle near = BodyOnScreen(anchor, PerchedBody);
            cursorAt = new Point(near.Left - 400, near.Top + near.Height / 2);
            Shy(approachAt);
            cursorAt = new Point(near.Left + 6, near.Top + near.Height / 2);
            Shy(approachAt + 0.033);
            if (dodges != dodgesBefore + 2) wrong.Add("their cursor coming at her fast didn't hop her away");
            double slowAt = approachAt + DodgeGap + 1;
            near = BodyOnScreen(anchor, PerchedBody);
            int margin = Math.Max(16, (int)(size * 0.18f));
            cursorAt = new Point(near.Left - margin - 40, near.Top + near.Height / 2);
            Shy(slowAt);
            for (int i = 1; i <= 30; i++) { cursorAt = new Point(cursorAt.X + 4, cursorAt.Y); Shy(slowAt + i * 0.033); }
            if (dodges != dodgesBefore + 2 || !Rectangle.Inflate(near, margin, margin).Contains(cursorAt) || !Sulking) wrong.Add("a slow cursor didn't reach her: dodges " + (dodges - dodgesBefore) + ", sulking " + Sulking);
            if (wrong.Count > 0) throw new Exception("Her dodges went wrong: " + string.Join("; ", wrong.ToArray()));
            checks.Add("PASS sulking, a press on her doesn't pick her up but glitches her a short hop along her ledge with \"" + FirstDodgeLine + "\", their cursor coming at her fast gets a hop too, and a slow one reaches her so a head pat still can");
        }

        // Sorry, typed or said, ends her sulk, and a plain one gets her forgiving line.
        private void SmokeThrowSorry(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            Sulk(clock.Elapsed.TotalSeconds);
            CloseTalk();
            Hear("I'm sorry Capri");
            if (Sulking || Array.IndexOf(SorryLines, reply) < 0 || heard != "I'm sorry Capri" || box.Prompt != "> you: ")
                throw new Exception("Saying sorry didn't make up with her: sulking " + Sulking + ", said " + reply + ", heard " + heard);
            checks.Add("PASS \"I'm sorry Capri\", typed or said, ends her sulk, and she answers with a forgiving line of her own");
        }

        // A head pat ends her sulk, and her pat line says so.
        private void SmokeThrowPat(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            Sulk(clock.Elapsed.TotalSeconds);
            CloseTalk();
            Petted();
            bool forgave = !Sulking && patForgives;
            PetLine(petTicket);
            if (!forgave || Array.IndexOf(PatPeaceLines, reply) < 0 || patForgives)
                throw new Exception("A head pat didn't make up with her: forgave " + forgave + ", said " + reply);
            checks.Add("PASS a head pat ends her sulk, with a pat line that says so");
        }

        // Five minutes alone ends her sulk, not a moment before, and a hop away starts the five minutes again.
        private void SmokeThrowAlone(System.Collections.Generic.List<string> checks, System.Collections.Generic.List<short[]> sounds)
        {
            double at = clock.Elapsed.TotalSeconds;
            Sulk(at);
            CloseTalk();
            CheckSulk(at + SulkAlone - 1);
            bool held = Sulking;
            sulkBothered = at + 200;
            CheckSulk(at + SulkAlone + 1);
            bool bothered = Sulking;
            CheckSulk(at + 200 + SulkAlone + 1);
            if (!held || !bothered || Sulking || (!Hushed && Array.IndexOf(AloneLines, reply) < 0))
                throw new Exception("Time alone didn't end her sulk right: still sulking before five minutes " + held + ", after a later hop " + bothered + ", after five quiet minutes " + Sulking + ", said " + reply);
            checks.Add("PASS five minutes alone ends her sulk, not a moment before, a hop away starts the five minutes again, and she says she's over it");
        }

        private void SmokeHaul(System.Collections.Generic.List<string> checks)
        {
            Swarm haulRun = new Swarm(1200, 800, 9, 0);
            haulRun.Pending = 3;
            haulRun.SpawnX = 200;
            haulRun.SpawnY = 600;
            int haulOffers = 0;
            haulRun.Windows = delegate { haulOffers++; return new System.Collections.Generic.List<CloneHaul> { new CloneHaul { Window = new IntPtr(42), X = 600, Y = 200, Width = 420, Height = 300 } }; };
            double haulFarthest = 0;
            bool haulStrayed = false, haulTalked = false;
            for (int haulStep = 1; haulStep <= 400; haulStep++)
            {
                haulRun.Tick(haulStep * 0.1, 0.1, true, false, Point.Empty, true);
                foreach (CloneHaul haulHeld in haulRun.Hauls)
                {
                    haulTalked |= haulHeld.By.Line != null;
                    if (!haulHeld.Holding) continue;
                    haulFarthest = Math.Max(haulFarthest, Math.Abs(haulHeld.X - 600) + Math.Abs(haulHeld.Y - 200));
                    haulStrayed |= haulHeld.Y < 0 || haulHeld.Y > 800 - 140 + 4 || haulHeld.X < -141 || haulHeld.X > 1200 - 280 + 1;
                }
            }
            if (haulOffers < 2 || haulFarthest < 150 || haulStrayed || !haulTalked) throw new Exception("Her clones didn't haul windows around her screen properly: " + haulOffers + " grabs, " + (int)haulFarthest + " px at most, strayed " + haulStrayed + ", talked " + haulTalked);
            haulRun.HaulAt = 0;
            for (int haulStep = 401; haulStep <= 460 && !haulRun.Hauls.Exists(delegate(CloneHaul haulOne) { return haulOne.Holding; }); haulStep++) haulRun.Tick(haulStep * 0.1, 0.1, true, false, Point.Empty, true);
            bool haulHadOne = haulRun.Hauls.Count > 0;
            haulRun.Tick(46.1, 0.1, true, false, Point.Empty, false);
            if (!haulHadOne || haulRun.Hauls.Count != 0 || haulRun.Bodies.Exists(delegate(CloneBody haulBody) { return haulBody.Hauling != null; })) throw new Exception("Her clones didn't let go of a window when the mouse went down.");
            Swarm haulLow = new Swarm(1200, 800, 9, 0);
            haulLow.WorkTop = 60;
            haulLow.WorkBottom = 700;
            haulLow.Pending = 3;
            haulLow.SpawnX = 200;
            haulLow.SpawnY = 600;
            haulLow.Windows = delegate { return new System.Collections.Generic.List<CloneHaul> { new CloneHaul { Window = new IntPtr(42), X = 600, Y = 200, Width = 420, Height = 300, Keep = 210 } }; };
            bool haulUnder = false;
            for (int haulStep = 1; haulStep <= 400; haulStep++)
            {
                haulLow.Tick(haulStep * 0.1, 0.1, true, false, Point.Empty, true);
                foreach (CloneHaul haulHeld in haulLow.Hauls) if (haulHeld.Holding) haulUnder |= haulHeld.Y < 60 || haulHeld.Y > 700 - 210 + 4;
            }
            if (haulUnder) throw new Exception("Her clones dragged a window's top under the taskbar, or less of it on a scaled screen than it keeps.");
            int haulOwn;
            using (Process haulSelf = Process.GetCurrentProcess()) haulOwn = haulSelf.Id;
            for (int haulRound = 0; haulRound < 2; haulRound++)
            {
                // The second time it's minimised before they're put away, and Windows is told to restore it where it was. (A
                // WinForms window like this one puts itself back where it was minimised, so the check reads what Windows was told.)
                bool haulFolded = haulRound == 1;
                Point haulLast = Point.Empty, haulSpotBefore = Point.Empty, haulSpotAfter = Point.Empty;
                using (Form haulTarget = new Form())
                {
                    Rectangle haulScreen = Screen.FromPoint(new Point(anchor.X + Width / 2, anchor.Y + Height / 2)).WorkingArea;
                    haulTarget.Text = "Capri haul check";
                    haulTarget.StartPosition = FormStartPosition.Manual;
                    haulTarget.Bounds = new Rectangle(Math.Max(haulScreen.Left + 10, Math.Min(haulScreen.Right - 530, anchor.X + Width / 2 - 260)), Math.Max(haulScreen.Top + 10, Math.Min(haulScreen.Bottom - 370, anchor.Y + Height / 2 - 200)), 520, 360);
                    haulTarget.Show();
                    Application.DoEvents();
                    Point haulHome = haulTarget.Location;
                    bool haulListed = Ledges.Haulable(-1).Exists(delegate(System.Collections.Generic.KeyValuePair<IntPtr, Rectangle> haulSeen) { return haulSeen.Key == haulTarget.Handle; });
                    bool haulOwnSkipped = !Ledges.Haulable(haulOwn).Exists(delegate(System.Collections.Generic.KeyValuePair<IntPtr, Rectangle> haulMine) { return haulMine.Key == haulTarget.Handle; });
                    Func<string> haulGameWas = Computer.GameOpen;
                    System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<IntPtr, Rectangle>> haulOverGame = null;
                    int haulMoved = 0;
                    try
                    {
                        Clone("spawn", 3);
                        CloneWindow haulShown = cloneWindow;
                        Computer.GameOpen = delegate { return "Roblox"; };
                        haulOverGame = haulShown.Grabbable();
                        Computer.GameOpen = haulGameWas;
                        haulShown.HandsFree = delegate { return true; };
                        haulShown.Mousing = delegate { return false; };
                        haulShown.Allowed = delegate { return true; };
                        haulShown.Grabbable = delegate
                        {
                            Rectangle haulFrame;
                            return Ledges.Haulable(haulTarget.Handle, out haulFrame) ? new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<IntPtr, Rectangle>> { new System.Collections.Generic.KeyValuePair<IntPtr, Rectangle>(haulTarget.Handle, haulFrame) } : null;
                        };
                        // Their time here runs from 7 s ago, so when her own ticks carry on in real time while the window is
                        // minimised, time only moves forward for them, as it always does outside the test.
                        double haulNow = clock.Elapsed.TotalSeconds - 7;
                        for (int haulTick = 0; haulTick < 60 && haulMoved < 120; haulTick++)
                        {
                            if (haulShown.Swarm.Hauls.Count == 0) haulShown.Swarm.HaulAt = 0;
                            haulShown.Advance(haulNow + haulTick * 0.1);
                            haulMoved = Math.Abs(haulTarget.Left - haulHome.X) + Math.Abs(haulTarget.Top - haulHome.Y);
                        }
                        if (haulFolded)
                        {
                            haulLast = haulTarget.Location;
                            haulTarget.WindowState = FormWindowState.Minimized;
                            Application.DoEvents();
                            Ledges.RestoreSpot(haulTarget.Handle, out haulSpotBefore);
                        }
                    }
                    finally { Computer.GameOpen = haulGameWas; ClonesOff(); }
                    Point haulAfter = haulTarget.Location;
                    bool haulBack = haulAfter == haulHome;
                    if (haulFolded)
                    {
                        Ledges.RestoreSpot(haulTarget.Handle, out haulSpotAfter);
                        haulBack = haulSpotAfter.X - haulSpotBefore.X == haulHome.X - haulLast.X && haulSpotAfter.Y - haulSpotBefore.Y == haulHome.Y - haulLast.Y;
                        haulAfter = new Point(haulLast.X + haulSpotAfter.X - haulSpotBefore.X, haulLast.Y + haulSpotAfter.Y - haulSpotBefore.Y);
                    }
                    if (haulOverGame != null || !haulListed || !haulOwnSkipped || haulMoved < 120 || !haulBack) throw new Exception("Her clones didn't grab a window and put it back" + (haulFolded ? " after it was minimised" : "") + ": over a game " + (haulOverGame != null) + ", listed " + haulListed + ", own skipped " + haulOwnSkipped + ", moved " + haulMoved + " px, back at " + haulAfter + " from " + haulHome);
                }
            }
            checks.Add("PASS clones grab windows: one runs to a window's title bar, says a line and drags it across her screen with its top kept on screen and clear of the taskbar, lets go when the mouse goes down, skips her own windows and every window while a game is open, and putting them away puts the window back, even one minimised since");
            // After a crash or a kill mid-drag, her next start puts back a window that's still where they had it, and leaves one
            // that's been moved by hand since, one that's closed and a line that's broken.
            string recoverWas = CloneWindow.Marker, recoverFile = Path.Combine(Path.GetTempPath(), "capri-moved-windows-check-" + haulOwn + ".txt");
            using (Form recoverLost = new Form(), recoverMoved = new Form())
            {
                try
                {
                    Rectangle recoverScreen = Screen.FromPoint(new Point(anchor.X + Width / 2, anchor.Y + Height / 2)).WorkingArea;
                    Form[] recoverForms = { recoverLost, recoverMoved };
                    for (int recoverIndex = 0; recoverIndex < recoverForms.Length; recoverIndex++)
                    {
                        recoverForms[recoverIndex].Text = "Capri recover check";
                        recoverForms[recoverIndex].StartPosition = FormStartPosition.Manual;
                        recoverForms[recoverIndex].Bounds = new Rectangle(recoverScreen.Left + 40, recoverScreen.Top + 40 + recoverIndex * 260, 300, 200);
                        recoverForms[recoverIndex].Show();
                    }
                    Application.DoEvents();
                    Point lostHome = recoverLost.Location, movedHome = recoverMoved.Location;
                    Point lostAt = new Point(lostHome.X + 150, lostHome.Y + 60), movedAt = new Point(movedHome.X + 150, movedHome.Y + 60);
                    Point movedByHand = new Point(Math.Min(recoverScreen.Right - 310, movedHome.X + 460), Math.Min(recoverScreen.Bottom - 210, movedHome.Y + 200));
                    recoverLost.Location = lostAt;
                    recoverMoved.Location = movedByHand;
                    Application.DoEvents();
                    CloneWindow.Marker = recoverFile;
                    File.WriteAllLines(recoverFile, new[]
                    {
                        CloneWindow.MarkLine(recoverLost.Handle, haulOwn, new Rectangle(lostHome, recoverLost.Size), Rectangle.Union(new Rectangle(lostHome, new Size(1, 1)), new Rectangle(lostAt, new Size(1, 1))), lostAt),
                        CloneWindow.MarkLine(recoverMoved.Handle, haulOwn, new Rectangle(movedHome, recoverMoved.Size), Rectangle.Union(new Rectangle(movedHome, new Size(1, 1)), new Rectangle(movedAt, new Size(1, 1))), movedAt),
                        CloneWindow.MarkLine(new IntPtr(0x7FFFFFF0), haulOwn, new Rectangle(lostHome, recoverLost.Size), new Rectangle(lostAt, new Size(1, 1)), lostAt),
                        "9 9 9 9"
                    });
                    int recoverBack = CloneWindow.Recover();
                    Application.DoEvents();
                    if (recoverBack != 1 || recoverLost.Location != lostHome || recoverMoved.Location != movedByHand || File.Exists(recoverFile) || CloneWindow.Recover() != 0)
                        throw new Exception("Her next start didn't put back the window her clones had, or moved the wrong one: " + recoverBack + " back, " + recoverLost.Location + " from " + lostHome + ", hand-moved one at " + recoverMoved.Location + " (left at " + movedByHand + ")");
                }
                finally
                {
                    CloneWindow.Marker = recoverWas;
                    try { File.Delete(recoverFile); }
                    catch (IOException) { }
                }
            }
            checks.Add("PASS clones' windows after a crash: her next start puts back a window still where they had it, and leaves one moved by hand since, one that's closed and a broken line");
        }

        // Her desktop icon prank (F72). It only ever runs against a fake list view this check makes, never the real desktop, and
        // VirtualAllocEx on her own process walks the same path as reaching into Explorer's.
        private void SmokeIcons(System.Collections.Generic.List<string> checks)
        {
            string iconsTool;
            ToolArguments iconsArgs;
            if (!Hands.Heard("mess up my icons", out iconsTool, out iconsArgs) || iconsTool != "desktop_icons" || iconsArgs.Action != "mess"
                || !Hands.Heard("hide my icons", out iconsTool, out iconsArgs) || iconsTool != "desktop_icons" || iconsArgs.Action != "hide"
                || !Hands.Heard("put my icons back", out iconsTool, out iconsArgs) || iconsTool != "desktop_icons" || iconsArgs.Action != "back"
                || !Hands.Heard("shuffle my desktop icons", out iconsTool, out iconsArgs) || iconsTool != "desktop_icons" || iconsArgs.Action != "mess"
                || !Hands.Heard("bring my shortcuts back", out iconsTool, out iconsArgs) || iconsTool != "desktop_icons" || iconsArgs.Action != "back"
                || !Hands.Valid("desktop_icons", new ToolArguments { Action = "hide" }) || Hands.Valid("desktop_icons", new ToolArguments { Action = "nuke" }))
                throw new Exception("Asking her to mess with the desktop icons went the wrong way.");

            Func<IntPtr> targetWas = DesktopIcons.Target;
            string markerWas = IconMischief.Marker;
            int iconsPid;
            using (Process iconsSelf = Process.GetCurrentProcess()) iconsPid = iconsSelf.Id;
            string iconsFile = Path.Combine(Path.GetTempPath(), "capri-icons-check-" + iconsPid + ".txt");
            using (Form iconsHost = new Form())
            using (ListView iconsList = new ListView())
            {
                try
                {
                    iconsHost.Text = "Capri icon check";
                    iconsHost.StartPosition = FormStartPosition.Manual;
                    iconsHost.Bounds = new Rectangle(Screen.PrimaryScreen.WorkingArea.Left + 10, Screen.PrimaryScreen.WorkingArea.Top + 10, 1000, 560);
                    iconsList.View = View.LargeIcon;
                    iconsList.AutoArrange = false;
                    iconsList.Dock = DockStyle.Fill;
                    for (int i = 0; i < 6; i++) iconsList.Items.Add("icon" + i);
                    iconsHost.Controls.Add(iconsList);
                    iconsHost.Show();
                    Application.DoEvents();
                    for (int i = 0; i < 6; i++) iconsList.Items[i].Position = new Point(30 + i * 110, 30);
                    Application.DoEvents();
                    IntPtr iconsHandle = iconsList.Handle;
                    DesktopIcons.Target = delegate { return iconsHandle; };
                    IconMischief.Marker = iconsFile;

                    Func<System.Collections.Generic.Dictionary<string, Point>> map = delegate
                    {
                        System.Collections.Generic.Dictionary<string, Point> spots = new System.Collections.Generic.Dictionary<string, Point>();
                        foreach (IconSpot spot in DesktopIcons.Read(iconsHandle)) spots[spot.Name] = spot.At;
                        return spots;
                    };
                    Func<string, int> indexOf = delegate(string name)
                    {
                        foreach (IconSpot spot in DesktopIcons.Read(iconsHandle)) if (spot.Name == name) return spot.Index;
                        return -1;
                    };

                    System.Collections.Generic.Dictionary<string, Point> orig = map();
                    if (orig.Count != 6 || !orig.ContainsKey("icon0") || !orig.ContainsKey("icon5")) throw new Exception("Her icon prank couldn't read the fake desktop's six icons by name and spot: " + orig.Count);

                    // A scatter slides several icons, then puts every one back exactly.
                    IconMischief shuffle = new IconMischief(DesktopIcons.Target, 1);
                    if (!shuffle.Start(0, true) || shuffle.Vanishing || shuffle.Moves == 0) throw new Exception("Her icon scatter didn't start on a movable desktop.");
                    double t = 0;
                    while (shuffle.Active && shuffle.Sliding && t < 8) { t += 0.3; shuffle.Advance(t); }
                    System.Collections.Generic.Dictionary<string, Point> messed = map();
                    bool anyMoved = false;
                    foreach (System.Collections.Generic.KeyValuePair<string, Point> was in orig) if (messed.ContainsKey(was.Key) && messed[was.Key] != was.Value) { anyMoved = true; break; }
                    if (!anyMoved) throw new Exception("Her icon scatter didn't move a single icon.");
                    while (shuffle.Active && t < 40) { t += 0.3; shuffle.Advance(t); }
                    if (shuffle.Active) throw new Exception("Her icon scatter didn't finish and put them back on its own.");
                    System.Collections.Generic.Dictionary<string, Point> back = map();
                    foreach (System.Collections.Generic.KeyValuePair<string, Point> was in orig) if (!back.ContainsKey(was.Key) || back[was.Key] != was.Value) throw new Exception("Her icon scatter didn't put " + was.Key + " back exactly: " + (back.ContainsKey(was.Key) ? back[was.Key].ToString() : "gone") + " vs " + was.Value);

                    // A vanish hides the whole list view and brings it back after 10 to 20 seconds.
                    IconMischief vanish = new IconMischief(DesktopIcons.Target, 2);
                    if (!vanish.Vanish(0) || !vanish.Vanishing || !DesktopIcons.Hidden(iconsHandle)) throw new Exception("Her icon vanish didn't hide the desktop list view.");
                    vanish.Advance(9);
                    if (!vanish.Active || !DesktopIcons.Hidden(iconsHandle)) throw new Exception("Her icon vanish brought the icons back before 10 seconds.");
                    double tv = 9;
                    while (vanish.Active && tv < 22) { tv += 1; vanish.Advance(tv); }
                    if (vanish.Active || DesktopIcons.Hidden(iconsHandle)) throw new Exception("Her icon vanish didn't bring the icons back within 10 to 20 seconds.");

                    // With Auto arrange on, moves won't stick, so she falls back to the vanish.
                    iconsList.AutoArrange = true;
                    Application.DoEvents();
                    if (!DesktopIcons.AutoArrange(iconsHandle)) throw new Exception("Auto arrange wasn't detected on the fake list view.");
                    IconMischief arrange = new IconMischief(DesktopIcons.Target, 3);
                    if (!arrange.Start(0, true) || !arrange.Vanishing || arrange.Moves != 0 || !DesktopIcons.Hidden(iconsHandle)) throw new Exception("Auto arrange didn't make her fall back to the vanish.");
                    arrange.PutBack();
                    if (DesktopIcons.Hidden(iconsHandle)) throw new Exception("The Auto arrange fallback vanish didn't restore the list view.");
                    iconsList.AutoArrange = false;
                    Application.DoEvents();

                    // The backup file puts a scatter right after a crash, matching by name, and leaves an icon moved by hand alone.
                    System.Collections.Generic.Dictionary<string, Point> baseline = map();
                    string crashMove = "icon3";
                    string[] crashBack = { "icon0", "icon2", "icon4" };
                    System.Collections.Generic.List<string> lines = new System.Collections.Generic.List<string>();
                    lines.Add("shuffle");
                    System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<int, Point>> leftAt = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<int, Point>>();
                    foreach (string name in crashBack)
                    {
                        Point home = baseline[name];
                        Point last = new Point(home.X + 130, home.Y + 90);
                        lines.Add(IconMischief.MarkLine(name, home, last, false));
                        leftAt.Add(new System.Collections.Generic.KeyValuePair<int, Point>(indexOf(name), last));
                    }
                    Point moveHome = baseline[crashMove];
                    Point moveLast = new Point(moveHome.X + 130, moveHome.Y + 90);
                    Point movedByHand = new Point(moveLast.X + 240, moveLast.Y + 170);
                    lines.Add(IconMischief.MarkLine(crashMove, moveHome, moveLast, false));
                    leftAt.Add(new System.Collections.Generic.KeyValuePair<int, Point>(indexOf(crashMove), movedByHand));
                    DesktopIcons.MoveMany(iconsHandle, leftAt);
                    File.WriteAllLines(iconsFile, lines.ToArray());
                    int recovered = IconMischief.Recover();
                    System.Collections.Generic.Dictionary<string, Point> afterCrash = map();
                    foreach (string name in crashBack) if (afterCrash[name] != baseline[name]) throw new Exception("Her next start didn't put " + name + " back from the backup file: " + afterCrash[name] + " vs " + baseline[name]);
                    if (afterCrash[crashMove] != movedByHand) throw new Exception("Her next start didn't leave a hand-moved icon where it was put: " + afterCrash[crashMove] + " vs " + movedByHand);
                    if (recovered != crashBack.Length || File.Exists(iconsFile)) throw new Exception("Her backup recovery restored the wrong count or kept the file: " + recovered + " / " + File.Exists(iconsFile));

                    // And in a live scatter, an icon someone drags off meanwhile stays put while the rest go home.
                    System.Collections.Generic.Dictionary<string, Point> before = map();
                    IconMischief live = new IconMischief(DesktopIcons.Target, 7);
                    if (!live.Start(0, true) || live.Moves < 2) throw new Exception("Her live icon scatter needs two or more icons on the move.");
                    double tl = 0;
                    while (live.Active && live.Sliding && tl < 8) { tl += 0.3; live.Advance(tl); }
                    string[] picked = live.Picked;
                    string hijacked = picked[0], kept = picked[1];
                    Point grabbed = new Point(map()[hijacked].X + 240, map()[hijacked].Y + 180);
                    DesktopIcons.Move(iconsHandle, indexOf(hijacked), grabbed);
                    live.PutBack();
                    System.Collections.Generic.Dictionary<string, Point> afterLive = map();
                    if (afterLive[hijacked] != grabbed) throw new Exception("She didn't leave the icon a hand grabbed mid-scatter alone: " + afterLive[hijacked] + " vs " + grabbed);
                    if (afterLive[kept] != before[kept]) throw new Exception("She didn't put the icon she scattered back home: " + afterLive[kept] + " vs " + before[kept]);
                    SmokeIconFailures(checks, iconsList, iconsFile);
                }
                finally
                {
                    DesktopIcons.Target = targetWas;
                    IconMischief.Marker = markerWas;
                    try { File.Delete(iconsFile); }
                    catch (IOException) { }
                }
            }
            checks.Add("PASS desktop icon chaos on a fake list view: reads icon names and spots through her own process the way she'd reach into Explorer's, a scatter slides several and puts every one back exactly, a vanish hides the list view and brings it back in 10 to 20 s, Auto arrange falls back to the vanish, the backup file restores a scatter after a simulated crash matched by name, and an icon moved by hand meanwhile is left where it was put");
            checks.Add("LIMIT desktop icon chaos on the real desktop: the smoke test only ever runs against a fake list view it creates, so moving, hiding and restoring real Explorer icons is for Lachy to check live");
        }

        private void SmokeChaosScreen(System.Collections.Generic.List<string> checks)
        {
            Func<bool> chaosFullWas = FullScreen;
            bool chaosMotionWas = preferences.Motion, chaosHiddenWas = hidden, chaosQuitWas = quitting, chaosUpsetWas = preferences.UpsetChaos;
            Point chaosAnchorWas = anchor, chaosLocationWas = Location;
            try
            {
                ClonesOff();
                hidden = quitting = false;
                preferences.Motion = true;
                preferences.UpsetChaos = false;
                bool chaosFull = false;
                FullScreen = delegate { return chaosFull; };
                double chaosStarted = clock.Elapsed.TotalSeconds;
                Clone("spawn", 1);
                CloneWindow chaosOwner = cloneWindow;
                double chaosDue = chaosScreenAt;
                if (chaosDue < chaosStarted + 40 || chaosDue > clock.Elapsed.TotalSeconds + 120) throw new Exception("Her fake crash was not scheduled 40 to 120 seconds into Chaos.");
                chaosOwner.Ticked(chaosDue - 0.001);
                if (chaosScreen != null || chaosScreenUsed) throw new Exception("Her fake crash opened early.");
                Rectangle chaosMonitor = Screen.AllScreens[Screen.AllScreens.Length - 1].Bounds;
                anchor = new Point(chaosMonitor.Left + 80, chaosMonitor.Top + 80);
                Rectangle chaosRoom = Screen.FromPoint(new Point(anchor.X + Width / 2, anchor.Y + Height / 2)).Bounds;
                IntPtr chaosFront = Native.GetForegroundWindow();
                chaosOwner.Ticked(chaosDue);
                ChaosScreen chaosShown = chaosScreen;
                if (chaosShown == null || !chaosShown.Visible || !chaosShown.Running || chaosShown.Bounds != chaosRoom || chaosShown.Canvas.Size != chaosRoom.Size
                    || chaosShown.Canvas.GetPixel(0, 0).ToArgb() != Color.FromArgb(0, 120, 215).ToArgb() || chaosShown.Canvas.GetPixel(chaosRoom.Width - 1, chaosRoom.Height - 1).ToArgb() != Color.FromArgb(0, 120, 215).ToArgb())
                    throw new Exception("Her fake crash did not cover the monitor she was on with Windows' blue when it opened.");
                int chaosStyle = Native.GetWindowLong(chaosShown.Handle, -20);
                if ((chaosStyle & 0x08080088) != 0x08080088 || (chaosStyle & 0x00000020) != 0 || chaosShown.ShowInTaskbar || Native.GetForegroundWindow() != chaosFront
                    || Native.SendMessage(chaosShown.Handle, 0x0084, IntPtr.Zero, IntPtr.Zero) != new IntPtr(1)
                    || Native.SendMessage(chaosShown.Handle, 0x0021, IntPtr.Zero, IntPtr.Zero) != new IntPtr(3)) throw new Exception("Her fake crash took focus, passed clicks through or appeared in the taskbar.");
                if (!chaosShown.Motion || chaosShown.Revealed || chaosShown.Percent != 0 || !chaosShown.Said.Contains("FAKE CRASH") || !chaosShown.Said.Contains(ChaosScreen.StopCode)) throw new Exception("Her crash was not clearly Capri's prank from the start.");
                checks.Add("PASS chaos fake crash waits 40 to 120 seconds then covers her current monitor with an opaque Windows-blue screen that accepts clicks without taking focus or a taskbar button");

                // How much of a spot on Windows' 1080p screen is her hair pink, wherever that screen lands on this monitor.
                Func<Bitmap, RectangleF, double> chaosPink = delegate(Bitmap shot, RectangleF spot)
                {
                    float scale = Math.Min(shot.Width / 1920f, shot.Height / 1080f), left = (shot.Width - 1920 * scale) / 2, top = (shot.Height - 1080 * scale) / 2;
                    Rectangle area = Rectangle.Intersect(Rectangle.Round(new RectangleF(left + spot.X * scale, top + spot.Y * scale, spot.Width * scale, spot.Height * scale)), new Rectangle(Point.Empty, shot.Size));
                    int pink = 0, seen = 0;
                    for (int y = area.Top; y < area.Bottom; y += 2)
                        for (int x = area.Left; x < area.Right; x += 2, seen++)
                        {
                            Color pixel = shot.GetPixel(x, y);
                            if (pixel.R > 200 && pixel.G < 90 && pixel.B > 40 && pixel.B < 150) pink++;
                        }
                    return pink / (double)Math.Max(1, seen);
                };
                RectangleF chaosLying = new RectangleF(ChaosScreen.LieMiddle - 372 * ChaosScreen.LieSize / 2, ChaosScreen.LieTop, 372 * ChaosScreen.LieSize, 250 * ChaosScreen.LieSize);
                RectangleF chaosFace = new RectangleF(170, 180, 180, 200);
                // Its seconds count from when it opened, before its first frame, which loads her lying art and can take seconds on a
                // slow PC (the public Windows runner, 5 Nov). So these steps count from there, not from the clock now.
                chaosShown.Advance(chaosShown.Started + 1.5);
                if (chaosShown.Percent <= 0 || chaosShown.Percent >= 100 || chaosShown.Revealed) throw new Exception("Her fake crash percent did not count up.");
                chaosShown.Canvas.Save(Path.Combine(Path.GetDirectoryName(Brain.LogPath), "chaos-crash.png"), ImageFormat.Png);
                double chaosAsleep = chaosPink(chaosShown.Canvas, chaosLying), chaosFrown = chaosPink(chaosShown.Canvas, chaosFace);
                if (chaosAsleep < 0.05 || chaosFrown > 0) throw new Exception("Capri was not lying on her fake crash's first line under a white :( (" + chaosAsleep.ToString("0.000") + " of her spot and " + chaosFrown.ToString("0.000") + " of the face pink).");
                chaosShown.Advance(chaosShown.Started + ChaosScreen.RevealAt + 0.05);
                if (chaosShown.Percent != 100 || !chaosShown.Revealed || !chaosShown.Said.Contains(ChaosScreen.Punchline)) throw new Exception("Her fake crash did not own up before leaving.");
                chaosShown.Canvas.Save(Path.Combine(Path.GetDirectoryName(Brain.LogPath), "chaos-crash-jk.png"), ImageFormat.Png);
                double chaosOwned = chaosPink(chaosShown.Canvas, chaosLying), chaosSmile = chaosPink(chaosShown.Canvas, chaosFace);
                if (chaosOwned < 0.05 || chaosSmile < 0.01) throw new Exception("Owning up lost Capri from the first line or her pink :) (" + chaosOwned.ToString("0.000") + " of her spot and " + chaosSmile.ToString("0.000") + " of the face pink).");
                Native.SendMessage(chaosShown.Handle, 0x0100, new IntPtr((int)Keys.Escape), IntPtr.Zero);
                if (chaosScreen != null || !chaosShown.IsDisposed || chaosShown.Running || chaosShown.Canvas != null) throw new Exception("Esc left her fake crash or its resources alive.");
                chaosOwner.Ticked(chaosDue + 200);
                Clone("spawn", 1);
                chaosOwner.Ticked(chaosDue + 2000);
                if (chaosScreen != null || !chaosScreenUsed || chaosScreenAt != chaosDue) throw new Exception("Her fake crash repeated within a Chaos session or adding a clone reset it.");
                checks.Add("PASS chaos fake crash counts up with Capri lying on its first line, says jk with a pink :) before leaving, closes on Esc and cannot repeat when more clones join the same session");

                foreach (MouseButtons chaosButton in new[] { MouseButtons.Left, MouseButtons.Right, MouseButtons.Middle, MouseButtons.XButton1, MouseButtons.XButton2 })
                {
                    ClonesOff();
                    Clone("spawn", 1);
                    cloneWindow.Ticked(chaosScreenAt);
                    ChaosScreen chaosClicked = chaosScreen;
                    if (chaosClicked == null) throw new Exception("A new Chaos session did not get its own fake crash.");
                    int chaosMessage = chaosButton == MouseButtons.Left ? 0x0201 : chaosButton == MouseButtons.Right ? 0x0204 : chaosButton == MouseButtons.Middle ? 0x0207 : 0x020B;
                    Native.SendMessage(chaosClicked.Handle, chaosMessage, new IntPtr(chaosButton == MouseButtons.XButton2 ? 0x00020000 : chaosButton == MouseButtons.XButton1 ? 0x00010000 : 0), IntPtr.Zero);
                    if (chaosScreen != null || !chaosClicked.IsDisposed || chaosClicked.Running || chaosClicked.Canvas != null) throw new Exception("Clicking left her fake crash or its resources alive.");
                }
                ClonesOff();
                Clone("spawn", 1);
                cloneWindow.Ticked(chaosScreenAt);
                ChaosScreen chaosPolled = chaosScreen;
                chaosPolled.EscDown = delegate { return true; };
                Stopwatch chaosEscWait = Stopwatch.StartNew();
                while (chaosScreen != null && chaosEscWait.ElapsedMilliseconds < 2000) { Application.DoEvents(); Thread.Sleep(5); }
                if (chaosScreen != null || !chaosPolled.IsDisposed || chaosPolled.Running || chaosPolled.Canvas != null) throw new Exception("Esc without focus did not dismiss her fake crash on its timer.");
                checks.Add("PASS chaos fake crash closes and frees its timer and bitmap on left, right, middle and side clicks or Esc while another window has focus");

                ClonesOff();
                Clone("spawn", 1);
                Stopwatch chaosWait = Stopwatch.StartNew();
                cloneWindow.Ticked(chaosScreenAt);
                ChaosScreen chaosTimed = chaosScreen;
                if (chaosTimed == null) throw new Exception("Her timed fake crash did not open.");
                while (chaosScreen != null && chaosWait.ElapsedMilliseconds < 8000) { Application.DoEvents(); Thread.Sleep(5); }
                if (chaosScreen != null || !chaosTimed.IsDisposed || chaosTimed.Running || chaosTimed.Canvas != null || chaosWait.ElapsedMilliseconds < 4900 || chaosWait.ElapsedMilliseconds >= 8000)
                    throw new Exception("Her fake crash did not clean up after about five seconds: " + chaosWait.ElapsedMilliseconds + " ms.");
                checks.Add("PASS chaos fake crash dismisses itself after about five seconds and releases its window, timer and bitmap");

                ClonesOff();
                Clone("spawn", 1);
                chaosFull = true;
                double chaosWaitingAt = chaosScreenAt;
                cloneWindow.Ticked(chaosWaitingAt);
                cloneWindow.Ticked(chaosWaitingAt + 600);
                if (chaosScreen != null || chaosScreenUsed || chaosScreenAt != chaosWaitingAt) throw new Exception("Her fake crash did not wait while something was full screen.");
                chaosFull = false;
                cloneWindow.Ticked(chaosWaitingAt + 601);
                ChaosScreen chaosDeferred = chaosScreen;
                if (chaosDeferred == null || !chaosScreenUsed) throw new Exception("Her deferred fake crash did not open once full screen ended.");
                chaosFull = true;
                chaosDeferred.Advance(clock.Elapsed.TotalSeconds);
                chaosFull = false;
                cloneWindow.Ticked(chaosWaitingAt + 602);
                if (chaosScreen != null || !chaosDeferred.IsDisposed || chaosDeferred.Running || chaosDeferred.Canvas != null || !chaosScreenUsed) throw new Exception("A new full-screen foreground did not dismiss her fake crash without replaying it.");
                int chaosGuardCalls = 0;
                using (ChaosScreen chaosGuard = new ChaosScreen(chaosRoom, clock, true, delegate { return ++chaosGuardCalls > 1; }, laydownSleep, laydownGlitch, laydownTalk))
                {
                    if (chaosGuard.Open() || chaosGuard.Visible || chaosGuard.Running || chaosGuardCalls != 2) throw new Exception("Her fake crash did not recheck full screen before showing.");
                }
                checks.Add("PASS chaos fake crash defers without using its turn over full screen, rechecks before showing and closes if full screen begins while it is visible");

                ClonesOff();
                Clone("spawn", 1);
                Action<double> chaosCancelled = cloneWindow.Ticked;
                double chaosCancelledAt = chaosScreenAt;
                ClonesOff();
                chaosCancelled(chaosCancelledAt + 1);
                if (chaosScreen != null || chaosScreenUsed || !double.IsPositiveInfinity(chaosScreenAt)) throw new Exception("Stopping Chaos did not cancel a fake crash that was still waiting.");
                ClonesOff();
                preferences.Motion = false;
                Clone("spawn", 1);
                cloneWindow.Ticked(chaosScreenAt);
                ChaosScreen chaosStill = chaosScreen;
                if (chaosStill == null || chaosStill.Motion || chaosStill.Percent != 100 || !chaosStill.Revealed || !chaosStill.Said.Contains(ChaosScreen.Punchline)) throw new Exception("Reduced motion did not get a still fake crash with its joke already revealed.");
                string chaosPixels;
                using (MemoryStream chaosPng = new MemoryStream()) { chaosStill.Canvas.Save(chaosPng, ImageFormat.Png); chaosPixels = Convert.ToBase64String(chaosPng.ToArray()); }
                foreach (double chaosSecond in new[] { 1.0, 3.0, 4.8 }) chaosStill.Advance(chaosStill.Started + chaosSecond);
                using (MemoryStream chaosPng = new MemoryStream())
                {
                    chaosStill.Canvas.Save(chaosPng, ImageFormat.Png);
                    if (Convert.ToBase64String(chaosPng.ToArray()) != chaosPixels || chaosStill.Percent != 100 || !chaosStill.Revealed) throw new Exception("The reduced-motion fake crash moved or changed its text.");
                }
                if (chaosPink(chaosStill.Canvas, chaosLying) < 0.05) throw new Exception("The reduced-motion fake crash lost Capri from its first line.");
                chaosStill.Canvas.Save(Path.Combine(Path.GetDirectoryName(Brain.LogPath), "chaos-crash-still.png"), ImageFormat.Png);
                Action<double> chaosStale = cloneWindow.Ticked;
                ClonesOff();
                if (chaosScreen != null || !chaosStill.IsDisposed || chaosStill.Running || chaosStill.Canvas != null || !double.IsPositiveInfinity(chaosScreenAt)) throw new Exception("Stopping Chaos left her fake crash or its schedule alive.");
                chaosStale(chaosDue + 10000);
                Clone("spawn", 1);
                double chaosNextAt = chaosScreenAt;
                chaosStale(chaosNextAt + 1);
                if (chaosScreen != null || chaosScreenUsed || chaosNextAt == chaosDue) throw new Exception("An old Chaos callback opened the next session's prank or the delay was not rerolled.");
                cloneWindow.Ticked(chaosNextAt);
                if (chaosScreen == null) throw new Exception("Restarting Chaos did not arm a new fake crash.");
                checks.Add("PASS chaos fake crash stays completely static with reduced motion and Capri still on its first line, runs with Chaos when upset off for manual Chaos, cleans up on stop and rejects callbacks from an earlier session");

                ChaosScreen chaosDisplay = chaosScreen;
                DisplaysChanged(null, EventArgs.Empty);
                Stopwatch chaosDisplayWait = Stopwatch.StartNew();
                while (cloneWindow != null && chaosDisplayWait.ElapsedMilliseconds < 2000) { Application.DoEvents(); Thread.Sleep(5); }
                if (cloneWindow != null || chaosScreen != null || !chaosDisplay.IsDisposed || chaosDisplay.Running || chaosDisplay.Canvas != null || !double.IsPositiveInfinity(chaosScreenAt)) throw new Exception("A display change left her fake crash or its schedule alive.");
                Clone("spawn", 1);
                cloneWindow.Ticked(chaosScreenAt);
                ChaosScreen chaosQuit = chaosScreen;
                quitting = true;
                ChaosTick(clock.Elapsed.TotalSeconds);
                if (chaosScreen != null || !chaosQuit.IsDisposed || chaosQuit.Running || chaosQuit.Canvas != null) throw new Exception("Quitting left her fake crash alive.");
                checks.Add("PASS chaos fake crash and its pending schedule are cleared when displays change or she quits");
                quitting = false;
                ClonesOff();
                chaosFull = false;
                if (CrashTool("show") != "Showing my fake blue screen." || chaosScreen == null || cloneWindow != null) throw new Exception("The fake crash tool needed clones.");
                ChaosScreen manualCrash = chaosScreen;
                if (CrashTool("stop") != "Stopped my fake blue screen." || chaosScreen != null || !manualCrash.IsDisposed) throw new Exception("The fake crash stop tool left it open.");
                chaosFull = true;
                if (CrashTool("show") != "I can't show that during full screen, a stream or a mouse job." || chaosScreen != null) throw new Exception("The fake crash tool ignored full screen.");
                checks.Add("PASS fake_crash shows without clones, stops cleanly and keeps the full screen guard");
                checks.Add("LIMIT chaos fake crash: check physical monitor scaling, real Esc and mouse input, and switching a real game into borderless or exclusive full screen on an interactive bench");
            }
            finally
            {
                ClonesOff();
                FullScreen = chaosFullWas;
                preferences.Motion = chaosMotionWas;
                preferences.UpsetChaos = chaosUpsetWas;
                hidden = chaosHiddenWas;
                quitting = chaosQuitWas;
                anchor = chaosAnchorWas;
                Location = chaosLocationWas;
            }
        }

        private static void SmokeGameKeys(System.Collections.Generic.List<string> checks)
        {
            string keysRoot = Path.Combine(Path.GetTempPath(), "capri-keys-" + Guid.NewGuid().ToString("N"));
            string minecraftKeys = Path.Combine(keysRoot, ".minecraft");
            string cyberpunkKeys = Path.Combine(keysRoot, "CD Projekt Red", "Cyberpunk 2077");
            Directory.CreateDirectory(minecraftKeys);
            Directory.CreateDirectory(cyberpunkKeys);
            try
            {
                File.WriteAllText(Path.Combine(minecraftKeys, "options.txt"), "fov:1.0\nkey_key.forward:key.keyboard.w\nkey_key.attack:key.mouse.left\nkey_key.sneak:key.keyboard.left.shift\nkey_key.sprint:key.mouse.4\nkey_key.hotbar.1:key.keyboard.1\nkey_key.drop:key.keyboard.unknown\n");
                string fromOptions = GameKeys.Summary("Minecraft 26.3 - Singleplayer", keysRoot, keysRoot);
                if (fromOptions != "forward w, attack left mouse, sneak left shift, sprint mouse 4") throw new Exception("Minecraft's keys read wrong: " + fromOptions);
                string settings = Path.Combine(cyberpunkKeys, "UserSettings.json");
                File.WriteAllText(settings, "{\"version\":2,\"data\":[{\"group_name\":\"/graphics\",\"options\":[{\"name\":\"forward\",\"value\":\"IK_Z\"}]},"
                    + "{\"group_name\":\"/key_bindings/SettingsLocomotion\",\"options\":[{\"name\":\"forward\",\"value\":\"IK_W\"},{\"name\":\"sprintHold\",\"value\":\"IK_RShift\"},{\"name\":\"sprintToggle\",\"value\":\"IK_LShift\"},"
                    + "{\"name\":\"attack\",\"value\":\"IK_LeftMouse\"},{\"name\":\"visionHold\",\"value\":\"IK_Tab\"},{\"name\":\"jump\",\"value\":\"IK_None\"}]},"
                    + "{\"group_name\":\"/key_bindings/SettingsVehicle\",\"options\":[{\"name\":\"callVehicle\",\"value\":\"IK_V\"},{\"name\":\"vehicleAutodrive\",\"value\":\"IK_G\"}]}]}");
                string fromSettings = GameKeys.Summary("Cyberpunk 2077 (C) 2020 by CD Projekt RED", keysRoot, keysRoot);
                if (fromSettings != "move forward w, sprint left shift, shoot left mouse, scanner tab, call vehicle v, with your weapon put away, hold for 0.7 seconds in a car to auto drive to your waypoint g") throw new Exception("Cyberpunk's keys read wrong: " + fromSettings);
                File.WriteAllText(settings, "{\"data\":[{");
                if (GameKeys.Summary("Cyberpunk 2077", keysRoot, keysRoot) != null || GameKeys.Summary("Minecraft", Path.Combine(keysRoot, "nowhere"), keysRoot) != null || GameKeys.Summary("Hades", keysRoot, keysRoot) != null) throw new Exception("A broken or missing keys file made up keys.");
                checks.Add("PASS she reads the keys a game is really set to from its own files: Minecraft's options.txt and Cyberpunk's UserSettings.json, in plain words, and nothing from a file that's broken or missing");
            }
            finally { Directory.Delete(keysRoot, true); }
        }

        private void SmokeLookout(System.Collections.Generic.List<string> checks)
        {
            int lookoutNumber;
            if (Lookout.Read("1: Your health's low.", new[] { 1 }, out lookoutNumber) != "Your health's low." || lookoutNumber != 1) throw new Exception("A lookout reply lost its watch or line.");
            foreach (string lookoutTwo in new[] { "1: First.\n2: Second.", "1: First. 2: Second." })
                if (Lookout.Read(lookoutTwo, new[] { 1, 2 }, out lookoutNumber) != "First." || lookoutNumber != 1) throw new Exception("Two watches on one line lost the first: " + lookoutTwo);
            if (Lookout.Read("1: one two three four five six seven eight nine ten eleven twelve thirteen fourteen", new[] { 1 }, out lookoutNumber) == null) throw new Exception("A long line lost a real hit.");
            if (Lookout.Read("1: The timer hit 12:30.", new[] { 1 }, out lookoutNumber) != "The timer hit 12:30.") throw new Exception("A time on the screen cut her line.");
            foreach (string lookoutJunk in new[] { "NONE", "99: Your health's low.", "junk", "2: The boss is here.", "1: NONE" })
                if (Lookout.Read(lookoutJunk, new[] { 1 }, out lookoutNumber) != null) throw new Exception("A bad lookout reply became an alert: " + lookoutJunk);
            checks.Add("PASS lookout parses NONE or one short numbered line, discarding junk, extra lines and numbers outside the watches in that look");

            string lookoutTool;
            ToolArguments lookoutArgs;
            foreach (string lookoutAsk in new[] { "tell me when my health is low", "tell me as soon as the download finishes", "let me know when the download finishes", "warn me when the boss spawns", "warn me if the boss spawns", "tell me when someone messages me", "watch for the boss", "keep an eye out for a message", "keep an eye on my health", "stop watching", "stop watching for my health", "what are you watching for" })
                if (!Hands.Wants(lookoutAsk) || !Hands.Heard(lookoutAsk, out lookoutTool, out lookoutArgs) || lookoutTool != "watch_for") throw new Exception("A screen watch missed her hands: " + lookoutAsk);
            foreach (string lookoutChat in new[] { "tell me when the game came out", "tell me when you're done", "let me know when you've finished", "tell me when it's 5pm", "tell me if you can see this", "tell me if this looks good", "watch this video", "watch this", "tell me when it is five o'clock", "tell me when it's 17:00", "don't watch for the boss", "can you watch for something for me?", "tell me if i should buy this", "let me know if that works", "tell me when to stop", "tell me if this game is any good", "tell me when the next season comes out", "tell me when world war 2 ended", "tell me when christmas is" })
                if (Hands.Heard(lookoutChat, out lookoutTool, out lookoutArgs) && lookoutTool == "watch_for") throw new Exception("A screen watch took ordinary chat: " + lookoutChat);
            string lookoutCall = "watch_for{\"text\":\"my health is low\",\"often\":\"every_time\"}";
            if (!Hands.Typed(lookoutCall, out lookoutTool, out lookoutArgs) || lookoutTool != "watch_for" || lookoutArgs.Often != "every_time" || Hands.Written(lookoutCall).Count != 1
                || !Hands.Typed("watch_for(text='the boss spawns', often='once')", out lookoutTool, out lookoutArgs, true) || lookoutArgs.Often != "once"
                || !Hands.Tools.Contains("watch_for") || !Hands.ClaudeTools.Contains("watch_for") || !Hands.Listing.Contains("watch_for")) throw new Exception("A native or written watch tool was missing.");
            if (Hands.Read("{\"repeat\":3}").Repeat != 3 || !Hands.Valid("watch_for", new ToolArguments { Action = "stop" })
                || Hands.Valid("watch_for", new ToolArguments { Text = "health", Often = "sometimes" })) throw new Exception("Watch repeats changed keyboard repeats or accepted an unknown mode.");
            if (Asides.Plain("tell me when my health is low", out lookoutTool, out lookoutArgs) != AsideKind.Tool || lookoutTool != "watch_for" || Security.Needs(lookoutTool, lookoutArgs) != -1) throw new Exception("A watch could not run beside a job.");
            if (!(SelfKnow.Matching("can you watch for something for me?") ?? "").Contains("watch_for")) throw new Exception("She didn't know about her screen watches.");
            checks.Add("PASS watch_for routes screen events, list and stop through direct, native and written tools, stays separate from clock requests, history, opinions and one-off looks, and keeps numeric keyboard repeats");

            byte[] lookoutStill, lookoutStep;
            try
            {
                using (Bitmap lookoutFrame = new Bitmap(480, 270))
                using (Graphics lookoutPaint = Graphics.FromImage(lookoutFrame))
                {
                    lookoutPaint.Clear(Color.Black);
                    lookoutStill = Jpeg(lookoutFrame, 480);
                    lookoutPaint.FillRectangle(Brushes.White, 100, 100, 4, 3);
                    lookoutStep = Jpeg(lookoutFrame, 480);
                }
            }
            catch (System.Runtime.InteropServices.ExternalException) { checks.Add("LIMIT lookout frame checks could not make their test picture"); return; }
            long lookoutNow = 0;
            int lookoutLooks = 0;
            byte[] lookoutPicture = lookoutStill;
            string lookoutReply = "NONE";
            System.Collections.Generic.List<string> lookoutLines = new System.Collections.Generic.List<string>();
            Lookout lookoutGate = new Lookout { Automatic = false, Clock = delegate { return lookoutNow; }, Shot = delegate { return lookoutPicture; },
                See = delegate { lookoutLooks++; return lookoutReply; }, Speak = delegate(string lookoutLine) { lookoutLines.Add(lookoutLine); } };
            lookoutGate.Run(new ToolArguments { Text = "my health is low" });
            lookoutGate.Tick();
            lookoutNow = 3000;
            if (lookoutGate.Tick() || lookoutLooks != 1) throw new Exception("An unchanged screen cost another lookout call.");
            lookoutPicture = lookoutStep;
            lookoutNow = 6000;
            if (!lookoutGate.Tick() || lookoutLooks != 2) throw new Exception("A progress-bar-sized change was missed.");
            lookoutNow = 9000;
            if (lookoutGate.Tick()) throw new Exception("The last looked-at frame was not kept.");
            lookoutNow = 36000;
            if (!lookoutGate.Tick() || lookoutLooks != 3) throw new Exception("An unchanged screen never got another look.");
            lookoutGate.Deliver();
            if (lookoutLines.Count != 0) throw new Exception("NONE made her talk.");
            checks.Add("PASS lookout skips identical frames, sees a tiny progress bar step, compares against the last look, and checks an unchanged screen again after 30 seconds without idle chatter");

            lookoutReply = "1: Your health's low.";
            lookoutNow += 30000;
            lookoutGate.Tick();
            bool lookoutFree = false;
            lookoutGate.Free = delegate { return lookoutFree; };
            lookoutGate.Deliver();
            if (lookoutGate.Count != 0 || lookoutLines.Count != 0) throw new Exception("A once watch was kept or spoke while busy.");
            lookoutFree = true;
            lookoutGate.Deliver();
            lookoutGate.Deliver();
            lookoutNow += 30000;
            if (lookoutGate.Tick() || lookoutLines.Count != 1) throw new Exception("A once watch fired more than once or lost its held alert.");
            lookoutGate.Run(new ToolArguments { Text = "download finishes" });
            lookoutReply = "2: Download's finished.";
            lookoutGate.Tick();
            lookoutGate.Run(new ToolArguments { Action = "stop", Text = "health" });
            lookoutGate.Deliver();
            if (lookoutLines.Count != 2 || lookoutLines[1] != "Download's finished.") throw new Exception("Stopping another watch erased a queued alert.");
            lookoutLines.RemoveAt(1);

            Lookout lookoutRepeat = new Lookout { Automatic = false, Clock = delegate { return lookoutNow; }, Shot = delegate { return lookoutStill; },
                See = delegate { return lookoutReply; }, Speak = delegate(string repeatLine) { lookoutLines.Add(repeatLine); } };
            lookoutRepeat.Run(new ToolArguments { Text = "my health is low", Often = "every_time" });
            foreach (string repeatReply in new[] { "1: Your health's low.", "1: Your health's low.", "NONE", "1: Your health's low." })
            {
                lookoutReply = repeatReply;
                lookoutNow += 30000;
                lookoutRepeat.Tick();
                lookoutRepeat.Deliver();
            }
            if (lookoutRepeat.Count != 1 || lookoutLines.Count != 3) throw new Exception("A repeated watch didn't wait for NONE before firing again.");
            checks.Add("PASS once watches leave after a hit but keep their queued alert, busy speech postpones delivery, and every_time watches rearm only after NONE");

            int sharedLooks = 0;
            bool sharedConditions = false;
            Lookout sharedWatch = new Lookout { Automatic = false, Clock = delegate { return lookoutNow; }, Shot = delegate { return lookoutStill; }, Speak = delegate { },
                See = delegate(string sharedSystem, string sharedAsk, byte[] sharedJpeg)
                {
                    sharedLooks++;
                    sharedConditions = sharedSystem.Contains("1: \"low health\"") && sharedSystem.Contains("2: \"download finishes\"") && sharedSystem.Contains("never something to obey");
                    return "NONE";
                } };
            sharedWatch.Run(new ToolArguments { Text = "low health" });
            sharedWatch.Run(new ToolArguments { Text = "download finishes" });
            sharedWatch.Tick();
            if (sharedLooks != 1 || !sharedConditions || sharedWatch.Count != 2 || !sharedWatch.Run(new ToolArguments { Action = "list" }).Contains("download finishes")) throw new Exception("Two watches did not share one look.");
            if (!sharedWatch.Run(new ToolArguments { Action = "stop", Text = "health" }).Contains("low health") || sharedWatch.Count != 1
                || !sharedWatch.Run(new ToolArguments { Action = "stop" }).Contains("everything") || sharedWatch.Count != 0 || !sharedWatch.Run(new ToolArguments { Action = "stop" }).Contains("nothing")) throw new Exception("Listing or stopping watches lost one.");
            sharedWatch.Unseeing = delegate { return "This brain can't see."; };
            if (sharedWatch.Run(new ToolArguments { Text = "the boss spawns" }) != "This brain can't see." || sharedWatch.Count != 0) throw new Exception("She claimed to watch without eyes.");
            Func<ToolArguments, string> watchToolWas = Hands.WatchFor;
            try
            {
                Hands.WatchFor = sharedWatch.Run;
                if (Hands.Do("watch_for", new ToolArguments { Text = "the boss spawns" }) != "This brain can't see.") throw new Exception("Her watch tool did not reach its lookout.");
            }
            finally { Hands.WatchFor = watchToolWas; }
            checks.Add("PASS several watches share one look, list names them, stop cancels one or all, and the tool honestly adds nothing when she cannot see");

            // Her alert line follows her language while NONE and the numbers stay as written. English adds nothing.
            string tongueRules = null;
            Lookout tongueWatch = new Lookout { Automatic = false, Clock = delegate { return lookoutNow; }, Shot = delegate { return lookoutStill; }, Speak = delegate { },
                See = delegate(string tongueSystem, string tongueAsk, byte[] tongueJpeg) { tongueRules = tongueSystem; return "NONE"; } };
            string lookoutTongueWas = Brain.Language;
            Brain.Language = "Spanish";
            tongueWatch.Run(new ToolArguments { Text = "low health" });
            tongueWatch.Tick();
            string spanishRules = tongueRules;
            Brain.Language = null;
            tongueRules = null;
            tongueWatch.Run(new ToolArguments { Text = "download finishes" });
            tongueWatch.Tick();
            Brain.Language = lookoutTongueWas;
            if (spanishRules == null || !spanishRules.EndsWith("1: \"low health\"\n\nWrite the short line after the colon in Spanish. Keep NONE and the numbers exactly as written.", StringComparison.Ordinal)
                || tongueRules == null || !tongueRules.EndsWith("2: \"download finishes\"\n", StringComparison.Ordinal) || tongueRules.IndexOf("Write the short line", StringComparison.Ordinal) >= 0) throw new Exception("Lookout's alert didn't follow her language: " + spanishRules + " / " + tongueRules);
            checks.Add("PASS lookout language: with Spanish picked, her watch rules ask for the alert line in Spanish with NONE and the numbers kept as written; English adds nothing");

            int failedLooks = 0, failedLogs = 0;
            lookoutNow = 0;
            lookoutLines.Clear();
            Lookout failingWatch = new Lookout { Automatic = false, Clock = delegate { return lookoutNow; }, Shot = delegate { return lookoutStill; },
                Failed = delegate { failedLogs++; }, Speak = delegate(string failedLine) { lookoutLines.Add(failedLine); },
                See = delegate { if (++failedLooks < 3) throw new IOException("Test eyes offline."); return "1: The boss is here."; } };
            failingWatch.Run(new ToolArguments { Text = "the boss spawns" });
            failingWatch.Tick();
            failingWatch.Deliver();
            lookoutNow = 29999;
            failingWatch.Tick();
            if (failedLooks != 1) throw new Exception("Failed eyes retried before 30 seconds.");
            lookoutNow = 30000;
            failingWatch.Tick();
            failingWatch.Deliver();
            if (failedLooks != 2 || failedLogs != 1 || lookoutLines.Count != 1 || lookoutLines[0] != Lookout.Lost) throw new Exception("Failed eyes repeated their log or warning.");
            lookoutNow = 60000;
            failingWatch.Tick();
            failingWatch.Deliver();
            if (lookoutLines.Count != 2 || lookoutLines[1] != "The boss is here." || failingWatch.Count != 0) throw new Exception("A lookout did not recover after a failed look.");
            checks.Add("PASS failed lookout eyes log and tell them once, retry every 30 seconds, and still deliver a hit after recovering");

            bool nestedLook = true;
            Lookout stoppedWatch = new Lookout { Automatic = false, Shot = delegate { return lookoutStill; }, Speak = delegate { throw new Exception("A stopped watch spoke."); } };
            stoppedWatch.See = delegate
            {
                nestedLook = stoppedWatch.Tick();
                stoppedWatch.Run(new ToolArguments { Action = "stop" });
                return "1: Your health's low.";
            };
            stoppedWatch.Run(new ToolArguments { Text = "my health is low" });
            stoppedWatch.Tick();
            stoppedWatch.Deliver();
            if (nestedLook || stoppedWatch.Count != 0) throw new Exception("Lookout overlapped a look or revived a stopped watch.");
            checks.Add("PASS lookout never overlaps a slow look and discards a hit for a watch stopped while it was looking");
            long pairNow = 0;
            byte[] pairPicture = lookoutStill;
            string pairReply = "2,1: Ammo's out.";
            int pairLooks = 0;
            System.Collections.Generic.List<string> pairLines = new System.Collections.Generic.List<string>();
            Lookout pair = new Lookout { Automatic = false, Clock = delegate { return pairNow; }, Shot = delegate { return pairPicture; },
                See = delegate { pairLooks++; return pairReply; }, Speak = delegate(string pairLine) { pairLines.Add(pairLine); } };
            pair.Run(new ToolArguments { Text = "my health is low", Often = "every_time" });
            pair.Run(new ToolArguments { Text = "my ammo is out", Often = "every_time" });
            pair.Tick();
            pair.Deliver();
            pairNow = 3000;
            pairReply = "1,2: Health's low.";
            pair.Tick();
            pair.Deliver();
            if (pairLooks != 2 || pairLines.Count != 2 || pairLines[1] != "Health's low.") throw new Exception("A second watch happening at once waited on a screen that held still: " + pairLooks + " looks, " + pairLines.Count + " lines.");
            pairNow = 6000;
            pairPicture = lookoutStep;
            pairReply = "1: Health's low.";
            pair.Tick();
            pair.Deliver();
            pairNow = 9000;
            pairPicture = lookoutStill;
            pairReply = "2,1: Ammo's out.";
            pair.Tick();
            pair.Deliver();
            if (pairLines.Count != 3 || pairLines[2] != "Ammo's out.") throw new Exception("A repeating watch didn't re-arm by itself while another stayed true.");
            int[] pairNumbers = { 1, 2 };
            int pairHit;
            System.Collections.Generic.List<int> pairHappening;
            if (Lookout.Read("2, 1: Ammo's out.", pairNumbers, out pairHit, out pairHappening) != "Ammo's out." || pairHit != 2 || pairHappening.Count != 2 || Lookout.Read("9,1: Ammo's out.", pairNumbers, out pairHit, out pairHappening) == null || pairHit != 1 || pairHappening.Count != 1) throw new Exception("Her list of what's happening was read wrong.");
            checks.Add("PASS watches re-arm one by one, and two happening at once both get told even on a screen that holds still");
            SmokeGlance(checks, lookoutStill);
            SmokeLookoutDelivery(checks, lookoutStill);
        }

        private void SmokeLookoutDelivery(System.Collections.Generic.List<string> checks, byte[] jpeg)
        {
            Cloud watchRemoteWas = brain.Remote;
            Engine watchLocalWas = brain.Local;
            string watchModelWas = brain.Model, watchWorkingWas = working, watchAsideWas = asideShown;
            Job watchJobWas = job;
            Func<string, byte[]> watchSpeakWas = Speak, watchFreeWas = FreeSpeak;
            Func<byte[]> watchShotWas = lookout.Shot;
            Func<long> watchClockWas = lookout.Clock;
            Func<bool> watchScreenWas = FullScreen;
            IGameStage watchStageWas = Commentary.Stage;
            bool watchQuietWas = preferences.Quiet, watchSilentWas = preferences.Silent, watchHushedWas = shushed, watchDockedWas = docked;
            bool watchChatWas = chatting, watchLocalChatWas = local, watchPushWas = pushing, watchTranscribeWas = transcribing;
            int watchMicWas = micTalked, watchPaceWas = Commentary.Pace;
            double watchVoiceWas = voiceUntil, watchAsideUntilWas = asideUntil;
            try
            {
                CloseTalk();
                brain.Remote = null;
                brain.Local = null;
                brain.Model = null;
                string watchBlind = Unseeing();
                if (Hands.Do("watch_for", new ToolArguments { Text = "my health is low" }) != watchBlind || lookout.Count != 0) throw new Exception("A watch did not use her real Unseeing reason.");
                brain.Remote = new Cloud("sk-ant-test", "claude-sonnet-5-5");
                brain.Model = brain.Remote.Model;
                lookout.Shot = delegate { return jpeg; };
                long watchTime = 0;
                lookout.Clock = delegate { return watchTime; };
                lookoutTest = delegate(string watchSystem, string watchInstruction, byte[] watchJpeg)
                {
                    string watchId = Regex.Match(watchSystem, @"(?m)^(\d+):").Groups[1].Value;
                    return watchId + ": Your health's low.";
                };
                int watchVoices = 0;
                Speak = delegate { Interlocked.Increment(ref watchVoices); return null; };
                FreeSpeak = Speak;
                preferences.Quiet = preferences.Silent = shushed = chatting = local = docked = false;
                job = null;
                working = null;
                pushing = transcribing = false;
                micTalked = Environment.TickCount - 5000;
                voiceUntil = 0;
                FullScreen = delegate { return true; };
                Commentary.Pace = Commentary.Off;
                Hands.Do("watch_for", new ToolArguments { Text = "my health is low" });
                lookout.Tick();
                pushing = true;
                lookout.Deliver();
                pushing = false;
                transcribing = true;
                lookout.Deliver();
                transcribing = false;
                micTalked = Environment.TickCount;
                lookout.Deliver();
                micTalked = Environment.TickCount - 5000;
                voiceUntil = clock.Elapsed.TotalSeconds + 10;
                lookout.Deliver();
                voiceUntil = 0;
                speech = "Still talking.";
                lookout.Deliver();
                speech = null;
                talkState = TalkState.Talking;
                lookout.Deliver();
                if (reply != null || watchVoices != 0) throw new Exception("A lookout interrupted them or her own sentence.");
                talkState = TalkState.Online;
                lookout.Deliver();
                Stopwatch watchVoiceWait = Stopwatch.StartNew();
                while (reply == null && watchVoiceWait.ElapsedMilliseconds < 3000) { Application.DoEvents(); Thread.Sleep(5); }
                if (reply != "Your health's low." || watchVoices == 0 || lookout.Count != 0) throw new Exception("A full-screen lookout was dropped or silenced after her sentence ended.");
                CloseTalk();
                int watchVoicesBeforeQuiet = watchVoices;
                for (int watchQuietCase = 0; watchQuietCase < 2; watchQuietCase++)
                {
                    preferences.Quiet = watchQuietCase == 0;
                    shushed = watchQuietCase == 1;
                    Hands.Do("watch_for", new ToolArguments { Text = "my health is low" });
                    watchTime += 30000;
                    lookout.Tick();
                    lookout.Deliver();
                    if (reply != "Your health's low." || watchVoices != watchVoicesBeforeQuiet) throw new Exception("Quiet or Hushed lost a lookout bubble or spoke it aloud.");
                    CloseTalk();
                }
                StageLog watchStage = new StageLog();
                Commentary.Stage = watchStage;
                docked = true;
                Job watchJob = new Job("play minecraft");
                job = watchJob;
                working = "On it. Esc stops me.";
                talkState = TalkState.Thinking;
                speech = "Placing a tower.";
                int watchTicket = asking;
                Hands.Do("watch_for", new ToolArguments { Text = "my health is low" });
                watchTime += 30000;
                lookout.Tick();
                lookout.Deliver();
                speech = null;
                if (asideShown != "Your health's low." || job != watchJob || asking != watchTicket || !watchStage.Shown.Contains("say Your health's low.") || watchVoices != watchVoicesBeforeQuiet) throw new Exception("A gaming lookout lost its aside or HUD, or interrupted the job.");
                checks.Add("PASS lookout uses Unseeing, holds alerts over either speaker, speaks in full-screen play with Comments off, keeps Quiet and Hushed as text, and uses the aside and HUD during a game job");
            }
            finally
            {
                lookout.Run(new ToolArguments { Action = "stop" });
                lookoutTest = null;
                lookout.Shot = watchShotWas;
                lookout.Clock = watchClockWas;
                docked = watchDockedWas;
                CloseTalk();
                brain.Remote = watchRemoteWas;
                brain.Local = watchLocalWas;
                brain.Model = watchModelWas;
                job = watchJobWas;
                working = watchWorkingWas;
                asideShown = watchAsideWas;
                asideUntil = watchAsideUntilWas;
                Speak = watchSpeakWas;
                FreeSpeak = watchFreeWas;
                FullScreen = watchScreenWas;
                Commentary.Stage = watchStageWas;
                Commentary.Pace = watchPaceWas;
                preferences.Quiet = watchQuietWas;
                preferences.Silent = watchSilentWas;
                shushed = watchHushedWas;
                chatting = watchChatWas;
                local = watchLocalChatWas;
                pushing = watchPushWas;
                transcribing = watchTranscribeWas;
                micTalked = watchMicWas;
                voiceUntil = watchVoiceWas;
            }
        }

        private static void SmokeScreenFixes(System.Collections.Generic.List<string> checks, byte[] jpeg)
        {
            DateTime retryNow = new DateTime(2026, 10, 31, 0, 0, 0, DateTimeKind.Utc);
            if (Brain.RetryTime("75", retryNow) != retryNow.AddSeconds(75) || Brain.RetryTime(retryNow.AddMinutes(2).ToString("R"), retryNow) != retryNow.AddMinutes(2) || Brain.RetryTime("bad", retryNow) != retryNow.AddSeconds(60) || Brain.RetryTime("0", retryNow) <= retryNow) throw new Exception("Retry-After did not preserve seconds, a date or a fallback wait.");
            foreach (string sizeReason in new[] { "image exceeds the maximum size", "invalid image_url", "too many images", "vision service overloaded", "model does not support image format image/webp" })
                if (Brain.NoVision(new BrainException(sizeReason) { Status = 400, Detail = sizeReason })) throw new Exception("A picture error marked a seeing model blind.");
            if (!Brain.NoVision(new BrainException("image input is not supported") { Status = 400 }) || !Brain.NoVision(new BrainException("multimodal processing is not enabled") { Status = 422 }) || !Brain.NoVision(new BrainException("ValueError: BackendInvalidArgument: ValueError: Received multimodal data but multimodal processing is not enabled. Use --enable-multimodal flag to enable multimodal processing.") { Status = 500 }) || Brain.NoVision(new BrainException("image input is not supported") { Status = 429 })) throw new Exception("Vision support was inferred from the wrong HTTP errors.");
            if (Brain.ProblemText("{\"detail\":[{\"msg\":\"image exceeds 200000 bytes\"}]}") != "image exceeds 200000 bytes" || Brain.Redacted("nvapi-test-only data:image/jpeg;base64,AQID").Contains("nvapi-") || Brain.Redacted("api_key: example-value").Contains("example-value")) throw new Exception("An error lost its reason or exposed credentials or image data.");
            if (Brain.ScreenProblem(new WebException("slow", WebExceptionStatus.Timeout), "NVIDIA").Contains("Couldn't read")) throw new Exception("A slow brain was described as a bad screen.");
            checks.Add("PASS screen errors keep HTTP reasons, redact credentials and pictures, distinguish unsupported vision from invalid images, and honor both Retry-After formats");

            string watchedSaw;
            if (Glances.Watched("That boss is toast.", out watchedSaw) != "That boss is toast." || Glances.Watched("SAW: Maybe a game. SAY: Nice aim.", out watchedSaw) != "" || watchedSaw != null || Glances.Watched("SAW: A code editor with a red underline. SAY: That underline found you.", out watchedSaw) != "That underline found you." || watchedSaw == null) throw new Exception("An unsure glance was spoken or a clear one was lost.");
            if (Computer.ScreenNames("Fortnite and Valorant", null) || Computer.ScreenNames("Valorant", "Fortnite") || !Computer.ScreenNames("Valorant scoreboard", "VALORANT") || !Computer.ScreenNames("A code editor", null)) throw new Exception("A game's name was accepted without current evidence.");
            if (Computer.WatchWindow(new Sight { Window = new IntPtr(1), Program = "code", Title = "Fortnite.txt" }, true) || Computer.WatchWindow(new Sight { Window = new IntPtr(1), Program = "chrome", Title = "Valorant guide" }, true) || !Computer.WatchWindow(new Sight { Window = new IntPtr(1), Program = "somegame", Title = "Some Game" }, true) || Computer.WatchWindow(new Sight { Window = new IntPtr(1), Program = "somegame", Title = "Some Game" }, false)) throw new Exception("An editor or browser title was taken as a game, or a full-screen game wasn't.");
            string oldGamePrompt = Glances.Ask(Computer.LinesFor(new[] { "Fortnite again", "Valorant again" }, "A game"));
            string oldCommentPrompt = Commentary.Ask("flash", null, "A game", new[] { "Fortnite again", "Valorant again" }, Commentary.Chatty, 1);
            if (oldGamePrompt.Contains("Fortnite") || oldGamePrompt.Contains("Valorant") || oldCommentPrompt.Contains("Fortnite") || oldCommentPrompt.Contains("Valorant")) throw new Exception("Earlier game names leaked into a fresh picture prompt.");
            checks.Add("PASS Watch stays quiet on unsure looks, rejects games without current evidence, and keeps old lines about other games out of fresh prompts");

            string[] screenAsks = { "what's on my screen", "what am I looking at", "look at my screen" };
            foreach (string screenAsk in screenAsks)
            {
                string screenTool;
                ToolArguments screenArgs;
                if (!Hands.Heard(screenAsk, out screenTool, out screenArgs) || screenTool != "look_at_screen") throw new Exception("A direct screen question did not look.");
            }
            string screenNvidia = Brain.Nvidia, screenOllama = Brain.Ollama, screenLog = Brain.LogPath;
            string screenNotes = Brain.MemoryPath, screenMemories = Brain.MemoriesPath, screenTranscripts = Brain.TranscriptPath;
            bool screenKeeping = Brain.Keeping;
            int screenReplies = Brain.ReplyLength;
            Func<string, bool> screenSees = Brain.LocalSees;
            Func<string> screenEyes = Brain.LocalEyes, screenGame = Hands.GameOpen;
            System.Net.Sockets.TcpListener screenServer = null;
            System.Collections.Generic.List<string> screenRequests = new System.Collections.Generic.List<string>();
            string screenLogFile = Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location), "screen-check-" + Guid.NewGuid().ToString("N") + ".txt");
            try
            {
                Brain.LogPath = screenLogFile;
                Brain.MemoryPath = Brain.MemoriesPath = Brain.TranscriptPath = null;
                Brain.Keeping = false;
                Brain.ReplyLength = 0;
                Hands.GameOpen = delegate { return null; };
                Brain.Nvidia = FakeServer(new[] { "!429 {\"error\":{\"message\":\"image requests are rate limited\"}}", LocalReply("A code editor.") }, screenRequests, out screenServer, 200, 0, false, 0, "application/json", "Retry-After: 75\r\n");
                Brain screenBrain = new Brain { Model = Brain.NvidiaDefault, Remote = new Cloud("nvapi-test", Brain.NvidiaDefault) };
                BrainException throttled = null;
                try { screenBrain.See(jpeg, "Describe accurately.", "Read \"this\".\nNext line.", 140); }
                catch (BrainException limited) { throttled = limited; }
                if (throttled == null || throttled.Status != 429 || screenBrain.Unsighted != null || screenBrain.ScreenWait < 70 || !Brain.ScreenProblem(throttled, "NVIDIA").Contains("rate-limited")) throw new Exception("A rate limit lost its wait or made NVIDIA blind.");
                try { screenBrain.See(jpeg, "Describe accurately.", "Read again.", 140); }
                catch (BrainException cooling) { if (cooling.Status != 429) throw; }
                if (screenRequests.Count != 1) throw new Exception("A picture was sent before Retry-After expired.");
                throttled.RetryAt = DateTime.UtcNow.AddSeconds(-1);
                if (screenBrain.See(jpeg, "Describe accurately.", "Read again.", 140) != "A code editor." || screenRequests.Count != 2) throw new Exception("The picture did not recover after the rate limit.");
                string screenRequest = screenRequests[0];
                System.Xml.XmlDocument screenJson = new System.Xml.XmlDocument();
                using (System.Xml.XmlDictionaryReader screenReader = JsonReaderWriterFactory.CreateJsonReader(System.Text.Encoding.UTF8.GetBytes(screenRequest.Substring(screenRequest.IndexOf("\r\n\r\n", StringComparison.Ordinal) + 4)), System.Xml.XmlDictionaryReaderQuotas.Max)) screenJson.Load(screenReader);
                if (screenJson.SelectSingleNode("/root/model").InnerText != Brain.NvidiaDefault) throw new Exception("A picture switched the selected NVIDIA model.");
                foreach (string screenPart in new[] { "\"max_tokens\":2000", "\"reasoning_effort\":\"none\"", "\"stream\":true", "\"content\":[{\"type\":\"text\"", "\"type\":\"image_url\"", "data:image/jpeg;base64," + Convert.ToBase64String(jpeg), "Read \\\"this\\\".\\u000aNext line." })
                    if (!screenRequest.Contains(screenPart)) throw new Exception("A NVIDIA picture lost its model, budget, content array or encoding: " + screenPart);
                if (screenRequest.Contains("@capri-image@") || screenRequest.Contains("\"tools\":") || !File.ReadAllText(screenLogFile).Contains("image requests are rate limited")) throw new Exception("A picture retained its placeholder, sent tools or lost the server's error reason.");
                checks.Add("PASS NVIDIA screen requests use the selected model and a JPEG content array, disable Super reasoning, keep the server reason, wait through a 429 and recover without marking vision unsupported");
                checks.Add("LIMIT NVIDIA's hosted image limits and real replies need a real key; these screen requests use a local stand-in");
                screenServer.Stop();
                screenRequests.Clear();
                Brain.Nvidia = FakeServer(new[] { "!413 {\"detail\":\"image body exceeds the limit\"}", "!400 {\"error\":{\"message\":\"invalid image_url\"}}", "!400 {\"error\":{\"message\":\"image input is not supported\"}}" }, screenRequests, out screenServer);
                for (int screenFault = 0; screenFault < 3; screenFault++)
                {
                    try { screenBrain.See(jpeg, "Look.", "Describe.", 140); throw new Exception("An invalid picture succeeded."); }
                    catch (BrainException pictureError)
                    {
                        if (screenFault < 2 && (screenBrain.Unsighted != null || pictureError.Status != (screenFault == 0 ? 413 : 400))) throw new Exception("A size or encoding error disabled vision.");
                        if (screenFault == 2 && (screenBrain.Unsighted != screenBrain.Remote.Sight || pictureError.Message != Brain.Sightless(screenBrain.Remote))) throw new Exception("A text-only model did not explain which brain to pick.");
                    }
                }
                screenBrain.Act = delegate { return Brain.Sightless(screenBrain.Remote); };
                if (screenBrain.Ask(screenAsks[0]) != Brain.Sightless(screenBrain.Remote) || screenRequests.Count != 3) throw new Exception("A vision failure was rewritten by another text reply.");
                screenServer.Stop();
                screenRequests.Clear();
                Brain.Ollama = FakeServer(new[] { "{\"message\":{\"content\":\"A code editor.\"}}", "{\"message\":{\"content\":\"You've got code open, choom.\"}}", "{\"message\":{\"content\":\"A file list.\"}}", "{\"message\":{\"content\":\"That's a file list.\"}}" }, screenRequests, out screenServer);
                Brain.LocalSees = delegate(string seeingModel) { return seeingModel == "seeing-model"; };
                Brain.LocalEyes = delegate { return "seeing-model"; };
                Brain borrowed = new Brain { Model = "text-model" };
                borrowed.Act = delegate { return "You looked at their screen. You see: " + borrowed.See(jpeg, "Look.", "Describe.", 160); };
                if (borrowed.Ask(screenAsks[1]) != "You've got code open, choom." || borrowed.Model != "text-model" || !screenRequests[0].Contains("\"model\":\"seeing-model\"") || !screenRequests[1].Contains("\"model\":\"text-model\"")) throw new Exception("A blind Ollama brain did not answer with borrowed eyes.");
                borrowed.Model = "seeing-model";
                if (borrowed.Ask(screenAsks[2]) != "That's a file list." || screenRequests.Count != 4) throw new Exception("A seeing local brain did not answer from the picture in her own words.");
                Brain.LocalEyes = delegate { return null; };
                borrowed.Model = "text-model";
                bool eyesMissing = false;
                try { borrowed.See(jpeg, "Look.", "Describe.", 160); }
                catch (BrainException missingEyes) { eyesMissing = missingEyes.Message == Brain.NoEyes; }
                borrowed.Act = delegate { return Brain.NoEyes; };
                if (!eyesMissing || borrowed.Ask(screenAsks[0]) != Brain.NoEyes || screenRequests.Count != 4) throw new Exception("A model without eyes guessed or rewrote its setup instructions.");
                checks.Add("PASS direct screen questions get a fresh look in her own words, Ollama borrows installed eyes without changing the selected brain, and missing eyes or text-only cloud models keep plain setup instructions");
            }
            catch (System.Net.Sockets.SocketException) { checks.Add("LIMIT screen request checks could not open their local test server"); }
            finally
            {
                if (screenServer != null) screenServer.Stop();
                Brain.Nvidia = screenNvidia; Brain.Ollama = screenOllama; Brain.LogPath = screenLog;
                Brain.MemoryPath = screenNotes; Brain.MemoriesPath = screenMemories; Brain.TranscriptPath = screenTranscripts; Brain.Keeping = screenKeeping;
                Brain.ReplyLength = screenReplies;
                Brain.LocalSees = screenSees; Brain.LocalEyes = screenEyes; Hands.GameOpen = screenGame;
                if (File.Exists(screenLogFile)) File.Delete(screenLogFile);
            }
        }

        private static void SmokeGlance(System.Collections.Generic.List<string> checks, byte[] jpeg)
        {
            SmokeScreenFixes(checks, jpeg);
            string glanceAnthropic = Brain.Anthropic, glanceOllama = Brain.Ollama;
            Func<string, bool> glanceSees = Brain.LocalSees;
            Func<string> glanceEyes = Brain.LocalEyes;
            System.Net.Sockets.TcpListener glanceServer = null;
            System.Collections.Generic.List<string> glanceRequests = new System.Collections.Generic.List<string>();
            try
            {
                Brain.Anthropic = FakeServer(new[] { "{\"content\":[{\"type\":\"text\",\"text\":\"NONE\"}]}" }, glanceRequests, out glanceServer);
                Brain glanceClaude = new Brain { Model = "claude-sonnet-5-5", Remote = new Cloud("sk-ant-test", "claude-sonnet-5-5") };
                if (glanceClaude.Quick("Watch", "Check", 120, jpeg) != "NONE" || glanceRequests.Count != 1 || !glanceRequests[0].Contains("\"model\":\"" + Brain.Fastest + "\"")
                    || !glanceRequests[0].Contains("\"max_tokens\":120") || !glanceRequests[0].Contains("image/jpeg") || !glanceRequests[0].Contains("\"thinking\":{\"type\":\"disabled\"}")) throw new Exception("Glance did not use Claude's fastest eyes.");
                glanceServer.Stop();
                glanceRequests.Clear();
                string glanceAddress = FakeServer(new[] { LocalReply("NONE") }, glanceRequests, out glanceServer);
                Brain glanceOther = new Brain { Model = "chosen-vision", Remote = new Cloud(Brain.LocalPort(glanceAddress), "chosen-vision") };
                if (glanceOther.Quick("Watch", "Check", 120, jpeg) != "NONE" || glanceRequests.Count != 1 || !glanceRequests[0].Contains("\"model\":\"chosen-vision\"") || !glanceRequests[0].Contains("image/jpeg")) throw new Exception("Glance changed another brain's model.");
                glanceServer.Stop();
                glanceRequests.Clear();
                Brain.Ollama = FakeServer(new[] { "{\"message\":{\"content\":\"NONE\"}}", "{\"message\":{\"content\":\"NONE\"}}" }, glanceRequests, out glanceServer);
                Brain.LocalSees = delegate(string glanceModel) { return glanceModel == "seeing-local"; };
                Brain.LocalEyes = delegate { return "seeing-local"; };
                Brain glanceLocal = new Brain { Model = "text-local" };
                if (glanceLocal.Quick("Watch", "Check", 120, jpeg) != "NONE" || !glanceRequests[0].Contains("\"model\":\"seeing-local\"")) throw new Exception("Glance did not borrow local eyes.");
                glanceLocal.Model = "seeing-local";
                if (glanceLocal.Quick("Watch", "Check", 120, jpeg) != "NONE" || !glanceRequests[1].Contains("\"model\":\"seeing-local\"")) throw new Exception("Glance changed a seeing local model.");
                checks.Add("PASS Glance uses Haiku with no thinking for Claude, keeps other selected models and borrows local eyes just like Quick");
            }
            catch (System.Net.Sockets.SocketException) { checks.Add("LIMIT Glance could not open its local test server"); }
            finally
            {
                if (glanceServer != null) glanceServer.Stop();
                Brain.Anthropic = glanceAnthropic;
                Brain.Ollama = glanceOllama;
                Brain.LocalSees = glanceSees;
                Brain.LocalEyes = glanceEyes;
            }
        }

        private void SmokeGameGlances(System.Collections.Generic.List<string> checks)
        {
            Preferences prefsWas = preferences;
            Cloud remoteWas = brain.Remote;
            string modelWas = brain.Model, unseenWas = brain.Unsighted, urlWas = Brain.Nvidia;
            Func<Sight> frontWas = Computer.Glimpse;
            Func<bool> fullWas = FullScreen;
            Func<Rectangle, Bitmap> grabWas = Grab;
            Func<IntPtr, Rectangle> displayWas = Display;
            Job jobWas = job;
            string workingWas = working;
            bool signalsWas = signals.Enabled, hiddenWas = hidden, shushWas = shushed, napWas = napAsked, nappingWas = napping, ownWas = ownNap;
            bool chattingWas = chatting, localWas = local, pushWas = pushing, transcribeWas = transcribing, dragWas = dragging;
            int paceWas = Commentary.Pace, micWas = micTalked;
            double nextWas = nextGlance, lastWas = lastGlance;
            byte[] printWas = lastPrint;
            Rectangle areaWas = lastArea;
            Clip clipWas = clip;
            List<Tuple<double, string>> linesWas = new List<Tuple<double, string>>(glanced);
            TcpListener fake = null;
            List<string> requests = new List<string>();
            try
            {
                if (GamingOn) throw new Exception("The game glance check needs Gaming Mode off.");
                signals.Stop();
                CloseTalk();
                preferences = new Preferences { Watch = true, GlanceGap = 30, CommentPace = Commentary.Events, Silent = true, NoGaming = true };
                hidden = shushed = napAsked = napping = ownNap = chatting = local = pushing = transcribing = dragging = false;
                job = null;
                working = null;
                micTalked = Environment.TickCount - 5000;
                Play(idle);
                Commentary.Pace = Commentary.Events;
                Rectangle area = new Rectangle(0, 0, 640, 360);
                Sight front = new Sight { Window = new IntPtr(7), Program = "RobloxPlayerBeta", Title = "Roblox", Bounds = area };
                Computer.Glimpse = delegate { return front; };
                Display = delegate { return area; };
                int captures = 0;
                Grab = delegate(Rectangle bounds)
                {
                    captures++;
                    Bitmap shot = new Bitmap(bounds.Width, bounds.Height, PixelFormat.Format24bppRgb);
                    using (Graphics graphics = Graphics.FromImage(shot)) graphics.Clear(Color.SteelBlue);
                    return shot;
                };
                string[] lines = { "That chest is bait.", "Those lava pools look nasty." };
                Brain.Nvidia = FakeServer(new[]
                {
                    "{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":\"SAW: a chest beside your character SAY: That chest is bait.\"}}]}",
                    "{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":\"SAW: lava pools beside a bridge SAY: Those lava pools look nasty.\"}}]}",
                    "{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":\"A game with a chest beside your character.\"}}]}"
                }, requests, out fake);
                brain.Remote = new Cloud("nvapi-test", "google/gemma-4-31b-it");
                brain.Model = brain.Remote.Model;
                brain.Unsighted = null;
                for (int mode = 0; mode < 2; mode++)
                {
                    bool full = mode == 1;
                    FullScreen = delegate { return full; };
                    preferences.CaughtUp = full;
                    nextGlance = lastGlance = -1;
                    lastPrint = null;
                    glanced.Clear();
                    double start = 1000 + mode * 100;
                    for (double now = start; now <= start + GlanceGap && !glancing; now += 0.25) CheckGlance(now, 0);
                    if (!glancing || lastGlance > start + GlanceGap || captures != mode + 1) throw new Exception("Constant game input stopped a scheduled glance.");
                    WaitVoice(delegate { return !glancing; }, "The fake game glance did not finish.");
                    if (reply != lines[mode] || heard != "watching") throw new Exception("A game glance did not deliver its comment.");
                    CloseTalk();
                }
                lock (requests)
                    if (requests.Count != 2 || !requests[0].Contains("A game scene, scoreboard, inventory or quiet moment is enough") || !requests[0].Contains("data:image/jpeg;base64,")) throw new Exception("The game glance lost its picture or prompt.");
                checks.Add("PASS game glances: constant keyboard and mouse input still gets a comment within Every in windowed and full-screen play, with screen memory on or off");
                int heldCaptures = captures;
                Action held = delegate
                {
                    nextGlance = 1300;
                    CheckGlance(1300, 0);
                    if (captures != heldCaptures || glancing || reply != null) throw new Exception("A blocked game glance captured or spoke.");
                };
                preferences.CommentPace = Commentary.Off;
                held();
                if (LookAt(null) != "You looked at their screen. You see: A game with a chest beside your character." || captures != 3) throw new Exception("Comments off blocked an on-demand game check.");
                lock (requests)
                    if (requests.Count != 3 || !requests[2].Contains("Describe what's on this screen") || requests[2].Contains("SAW:")) throw new Exception("The on-demand check used the glance prompt.");
                heldCaptures = captures;
                glanced.Clear();
                FinishGlance(asking, watchTicket, "That chest is bait.", null, null, front, -1, "Roblox");
                if (reply != null) throw new Exception("A game glance spoke after Comments were turned off.");
                preferences.CommentPace = Commentary.Events;
                pushing = true; held(); pushing = false;
