                    if (Hands.Heard(missingReminder, out reminderTool, out reminderArgs)) throw new Exception("An article selected a reminder: " + missingReminder);
                foreach (string reminderFragment in new string[] { "the", "my", "piz", "he pizza", "pizza ou" })
                    if (DoTool("remind", new ToolArguments { Action = "cancel", Text = reminderFragment }) != "Couldn't find that reminder.") throw new Exception("Part of a word cancelled a reminder: " + reminderFragment);
                if (!new Reminders(reminderFolder, reminderNow).Remind(new ToolArguments { Action = "list" }).Contains("take the pizza out")
                    || !Hands.Heard("cancel the pizza out reminder", out reminderTool, out reminderArgs) || DoTool(reminderTool, reminderArgs) != "Cancelled your reminder: take the pizza out"
                    || new Reminders(reminderFolder, reminderNow).Take(reminderNow.AddHours(3)) != null) throw new Exception("Reminder cancellation did not keep whole word boundaries.");
                checks.Add("PASS cancelling a reminder rejects the and my alone and partial words, keeps the saved reminder intact, and cancels a whole word phrase");

                System.Collections.Generic.List<string> routineRuns = new System.Collections.Generic.List<string>();
                Hands.Catalog = delegate { return new System.Collections.Generic.List<InstalledApp> { new InstalledApp("Premiere", "premiere"), new InstalledApp("Spotify", "spotify") }; };
                Hands.Run = delegate(string routineApp) { routineRuns.Add(routineApp); };
                Hands.Forget();
                preferences.QuickHands = true;
                Security.Load(Security.Of(Security.Trusted));
                foreach (string unclearRoutine in new string[] { "when I say let's go open steam", "when I say thanks, I really mean it", "when I say \"thanks\", I really mean it" })
                    if (Hands.Heard(unclearRoutine, out reminderTool, out reminderArgs)) throw new Exception("A conversational or ambiguous phrase became a routine: " + unclearRoutine);
                foreach (string clearRoutine in new string[] { "when I say let's go, open steam", "when I say \"let's go\" open steam" })
                    if (!Hands.Heard(clearRoutine, out reminderTool, out reminderArgs) || reminderTool != "routine" || reminderArgs.Phrase != "let's go" || reminderArgs.Steps != "open steam") throw new Exception("A clear routine phrase was split at its verb: " + clearRoutine);
                checks.Add("PASS routine definitions keep verbs inside the phrase, require a listed action after the comma or quoted phrase, and leave ambiguous splits and conversation for her brain");
                if (!Hands.Heard("when I say let's get to work, open premiere and spotify", out reminderTool, out reminderArgs) || reminderTool != "routine" || reminderArgs.Phrase != "let's get to work" || reminderArgs.Steps != "open premiere and spotify") throw new Exception("A routine definition was not heard.");
                DoTool(reminderTool, reminderArgs);
                if (routineRuns.Count != 0) throw new Exception("Saving a routine ran it.");
                reminders = new Reminders(reminderFolder, reminderNow);
                reminders.Now = delegate { return reminderNow; };
                Hands.Plan = reminders.Route;
                Hands.Remind = reminders.Remind;
                foreach (string routinePhrase in new string[] { "let's get to work", "HEY CAPRI! LET’S GET TO WORK.", "Capri, lets get to work!" })
                {
                    if (!Hands.Heard(routinePhrase, out reminderTool, out reminderArgs) || reminderTool != "routine" || reminderArgs.Action != "run") throw new Exception("A saved routine phrase was missed: " + routinePhrase);
                    DoTool(reminderTool, reminderArgs);
                }
                if (string.Join(",", routineRuns.ToArray()) != "premiere,spotify,premiere,spotify,premiere,spotify") throw new Exception("A routine did not run through her ordinary opening tools.");
                string routineAnimation = null;
                Hands.Animate = delegate(string routineMove) { routineAnimation = routineMove; return "Blinked."; };
                reminders.Routine(new ToolArguments { Phrase = "blink", Steps = "blink" });
                if (!Hands.Heard("blink", out reminderTool, out reminderArgs) || DoTool(reminderTool, reminderArgs) != "Blinked." || routineAnimation != "blink") throw new Exception("A routine shadowed its own ordinary action.");
                if (Hands.Heard("I said Capri, let's get to work", out reminderTool, out reminderArgs) && reminderTool == "routine") throw new Exception("A routine ran inside a longer sentence.");
                string routineJob = null;
                Think = delegate(string routineRequest) { routineJob = routineRequest; return "Movie time is ready."; };
                if (!Hands.Heard("when I say movie time, open netflix and turn the volume down", out reminderTool, out reminderArgs) || reminderArgs.Phrase != "movie time") throw new Exception("A mixed routine definition was missed.");
                DoTool(reminderTool, reminderArgs);
                if (!Hands.Heard("movie time", out reminderTool, out reminderArgs) || DoTool(reminderTool, reminderArgs) != "Movie time is ready." || routineJob != "open netflix and turn the volume down") throw new Exception("A routine did not pass all its steps to the ordinary request path.");
                if (!Hands.Heard("what routines do I have", out reminderTool, out reminderArgs) || !DoTool(reminderTool, reminderArgs).Contains("movie time: open netflix and turn the volume down") || !Hands.Heard("forget the movie time routine", out reminderTool, out reminderArgs) || DoTool(reminderTool, reminderArgs) != "Forgot your routine: movie time" || new Reminders(reminderFolder, reminderNow).Steps("movie time") != null) throw new Exception("Listing or forgetting a routine failed.");
                checks.Add("PASS routines save without running, reload, match the whole phrase with case, punctuation or Hey Capri, run ordinary tools or pass the whole job to the usual request path, and list and forget");
                if (!Hands.Heard("forget about my workout routine", out reminderTool, out reminderArgs) || reminderTool != "remember" || reminderArgs.Action != "forget" || reminderArgs.Text != "my workout routine"
                    || !Hands.Heard("forget the workout routine", out reminderTool, out reminderArgs) || reminderTool != "remember") throw new Exception("Forgetting a note about a routine was intercepted.");
                reminders.Routine(new ToolArguments { Phrase = "workout", Steps = "play workout music" });
                if (!Hands.Heard("forget the workout routine", out reminderTool, out reminderArgs) || reminderTool != "routine" || DoTool(reminderTool, reminderArgs) != "Forgot your routine: workout") throw new Exception("An existing routine did not match its forget request.");
                checks.Add("PASS forgetting a routine only takes the routine branch when it exists, and forget about my workout routine still reaches remember");

                CloseTalk();
                int reminderBrainCalls = 0;
                Think = delegate { reminderBrainCalls++; return "Unexpected brain call."; };
                preferences.Silent = true;
                Hear("remind me in an hour to stretch");
                Stopwatch reminderWait = Stopwatch.StartNew();
                while (reply == null && reminderWait.ElapsedMilliseconds < 3000) { Application.DoEvents(); Thread.Sleep(5); }
                if (reminderBrainCalls != 0 || reply == null || !reply.Contains(": stretch")) throw new Exception("A complete reminder went to her brain.");
                CloseTalk();
                int reminderVoices = 0;
                Speak = delegate { reminderVoices++; return null; };
                FreeSpeak = Speak;
                preferences.Silent = false;
                preferences.Quiet = false;
                FullScreen = delegate { return true; };
                shushed = false;
                CheckReminders(reminderNow.AddHours(1));
                UpdateTalk(clock.Elapsed.TotalSeconds);
                if (reply != "Reminder: stretch" || !box.Visible || reminderVoices != 0) throw new Exception("A full-screen game held back a reminder bubble or spoke over it.");
                CloseTalk();
                reminders.Remind(new ToolArguments { Text = "quiet reminder", When = "in an hour" });
                FullScreen = delegate { return false; };
                shushed = true;
                CheckReminders(reminderNow.AddHours(1));
                UpdateTalk(clock.Elapsed.TotalSeconds);
                if (reply != "Reminder: quiet reminder" || !box.Visible || reminderVoices != 0) throw new Exception("Quiet mode held back a reminder bubble or spoke over it.");
                CloseTalk();
                reminders.Remind(new ToolArguments { Text = "spoken reminder", When = "in an hour" });
                shushed = false;
                CheckReminders(reminderNow.AddHours(1));
                Stopwatch reminderVoiceWait = Stopwatch.StartNew();
                while (reply == null && reminderVoiceWait.ElapsedMilliseconds < 3000) { Application.DoEvents(); Thread.Sleep(5); }
                if (reply != "Reminder: spoken reminder" || reminderVoices == 0) throw new Exception("A reminder did not use her usual voice path.");
                checks.Add("PASS complete reminders skip the brain, due reminders use her bubble and usual voice path, and Quiet mode and full-screen games still show the bubble without voice");

                CloseTalk();
                Job reminderJob = new Job("open notepad");
                job = reminderJob;
                working = "On it. Esc stops me.";
                talkState = TalkState.Thinking;
                int reminderJobTicket = asking;
                Hear("remind me in 20 minutes to check the oven");
                Stopwatch reminderJobWait = Stopwatch.StartNew();
                while ((asideShown == null || !asideShown.Contains("check the oven")) && reminderJobWait.ElapsedMilliseconds < 3000) { Application.DoEvents(); Thread.Sleep(5); }
                if (job != reminderJob || asking != reminderJobTicket || talkState != TalkState.Thinking || reminderBrainCalls != 0 || working == null || asideShown == null || !asideShown.Contains(": check the oven")
                    || !new Reminders(reminderFolder, reminderNow).Remind(new ToolArguments { Action = "list" }).Contains("check the oven")) throw new Exception("A mid-job reminder was acknowledged without saving, or replaced the active job.");
                string reminderJobLine = asideShown;
                Hear("when I say oven ready, open spotify");
                Stopwatch reminderRoutineWait = Stopwatch.StartNew();
                while (asideShown == reminderJobLine && reminderRoutineWait.ElapsedMilliseconds < 3000) { Application.DoEvents(); Thread.Sleep(5); }
                if (job != reminderJob || asking != reminderJobTicket || routineRuns.Count != 6 || new Reminders(reminderFolder, reminderNow).Steps("oven ready") != "open spotify") throw new Exception("A mid-job routine was not saved beside the active job.");
                checks.Add("PASS reminders and routine definitions received mid-job execute their planned tools and persist without cancelling or replacing the active job");

                CheckReminders(reminderNow.AddMinutes(20));
                UpdateTalk(clock.Elapsed.TotalSeconds);
                if (asideShown != "Reminder: check the oven" || box.Reply != asideShown || !box.Visible || job != reminderJob || asking != reminderJobTicket || talkState != TalkState.Thinking
                    || reminders.Take(reminderNow.AddMinutes(20)) != null) throw new Exception("A due reminder waited for the job to end or took over its reply.");
                job = null;
                working = null;
                CloseTalk();
                int reminderCallVoices = reminderVoices;
                foreach (bool reminderLocalCall in new bool[] { false, true })
                {
                    chatting = true;
                    local = reminderLocalCall;
                    talkState = TalkState.Thinking;
                    reminders.Remind(new ToolArguments { Text = "call reminder", When = "in an hour" });
                    CheckReminders(reminderNow.AddHours(1));
                    UpdateTalk(clock.Elapsed.TotalSeconds);
                    if (reply != "Reminder: call reminder" || !box.Visible || reminderVoices != reminderCallVoices || !chatting || local != reminderLocalCall
                        || reminders.Take(reminderNow.AddHours(1)) != null) throw new Exception("A due reminder waited for a call to end or spoke over it.");
                    CloseTalk();
                }
                chatting = false;
                local = false;
                checks.Add("PASS due reminders show in the working text during a job and only in her bubble during local or cloud calls, without waiting for either to finish or firing twice");
            }
            catch (IOException reminderIo) { checks.Add("LIMIT reminder persistence could not use the smoke folder: " + reminderIo.Message); }
            catch (UnauthorizedAccessException reminderAccess) { checks.Add("LIMIT reminder persistence could not use the smoke folder: " + reminderAccess.Message); }
            finally
            {
                chatting = false;
                local = false;
                CloseTalk();
                job = savedReminderJob;
                working = savedReminderWorking;
                chatting = savedReminderChatting;
                local = savedReminderLocal;
                reminders = savedReminders;
                Hands.Plan = savedPlan;
                Hands.Remind = savedRemind;
                Hands.Routine = savedRoutine;
                Hands.Catalog = savedReminderCatalog;
                Hands.Run = savedReminderRun;
                Hands.Forget();
                Think = savedReminderThink;
                Hands.Animate = savedRoutineAnimate;
                Speak = savedReminderSpeak;
                FreeSpeak = savedReminderFree;
                FullScreen = savedReminderScreen;
                preferences.Quiet = savedReminderQuiet;
                preferences.Silent = savedReminderSilent;
                preferences.QuickHands = savedReminderQuick;
                shushed = savedReminderShush;
                Security.Load(savedReminderSecurity);
            }
        }

        internal static void SmokeRequests(System.Collections.Generic.List<string> checks, string folder)
        {
            Func<System.Collections.Generic.List<InstalledApp>> requestCatalog = Hands.Catalog;
            Func<System.Collections.Generic.List<OpenWindow>> requestWindows = Hands.Windows;
            Func<string, bool> requestExists = Hands.Exists, requestPlaying = Hands.SongPlaying, requestPress = Hands.PressPlay;
            Func<string, string> requestFetch = Hands.Fetch, requestBrowser = Hands.BrowserPath, requestOpened = Hands.Opened;
            Func<string> requestGame = Hands.GameOpen;
            Func<string, System.Collections.Generic.KeyValuePair<string, ToolArguments>> requestPlan = Hands.Plan;
            Action<string> requestRun = Hands.Run;
            Action<string, string> requestBrowse = Hands.Browse;
            Websites requestWebsites = Hands.Websites;
            FileFinder requestFinder = Hands.Finder;
            Func<Tune> requestTune = Tunes.Spotify;
            try
            {
                Hands.Catalog = delegate { return new System.Collections.Generic.List<InstalledApp> { new InstalledApp("Spotify", "spotify"), new InstalledApp("Minecraft", "minecraft") }; };
                Hands.Exists = delegate { return false; };
                Hands.Windows = delegate { return new System.Collections.Generic.List<OpenWindow>(); };
                Hands.GameOpen = delegate { return null; };
                Hands.Plan = delegate { return new System.Collections.Generic.KeyValuePair<string, ToolArguments>(); };
                Hands.Finder = new FileFinder();
                Hands.Finder.Roots = delegate { return new string[0]; };
                Hands.Finder.Wider = delegate { return new string[0]; };
                Hands.Websites = null;
                Hands.Forget();
                string[,] requests =
                {
                    { "open spotify and play X", "play_music" }, { "play X on spotify", "play_music" }, { "put on my X playlist", "play_music" },
                    { "open spotify and play Blinding Lights", "play_music" },
                    { "play Blinding Lights on spotify", "play_music" },
                    { "put on my driving playlist", "play_music" },
                    { "open spotify and play my driving playlist", "play_music" },
                    { "Capri, can you open spotify and play Blinding Lights for me?", "play_music" },
                    { "let's watch some youtube", "open_website" }, { "lets watch youtube", "open_website" },
                    { "let's play minecraft", "use_computer" }, { "let's listen to some music", "play_music" },
                    { "play chess", "mini_game" }, { "open chess", "mini_game" }, { "play Chess by The Artist", "play_music" },
                    { "wanna watch some youtube", "open_website" }, { "we should open spotify", "open_app" },
                    { "how about some youtube", "open_website" }, { "time for some youtube", "open_website" }, { "put on some youtube", "open_website" },
                    { "answer the questions on my screen", "use_computer" }, { "do this quiz", "use_computer" },
                    { "do this quiz for me", "use_computer" }, { "answer this quiz", "use_computer" },
                    { "fill in this quiz", "use_computer" }, { "answer these questions", "use_computer" },
                    { "Hey, Capri. Can you please show me the path to the cyberpunk game folder", "find_file" },
                    { "find my holiday photos", "find_file" }, { "find budget.xlsx", "find_file" }
                };
                string[] conversations = { "let's talk", "let's see", "let's go", "let's be honest", "we should talk", "how about you", "time for bed", "i watched youtube yesterday", "what's a quiz", "i have a quiz tomorrow" };
                string heardTool;
                ToolArguments heardArgs;
                for (int requestIndex = 0; requestIndex < requests.GetLength(0); requestIndex++)
                {
                    string wording = requests[requestIndex, 0], expected = requests[requestIndex, 1];
                    if (!Hands.Heard(wording, out heardTool, out heardArgs) || heardTool != expected || !Hands.Valid(heardTool, heardArgs) || !Hands.Wants(wording)) throw new Exception("Request routed wrong: " + wording + " -> " + heardTool);
                    // Her board, like her hands' jobs, opens through her brain's pick.
                    if (expected != "use_computer" && expected != "mini_game" && !WithoutBrain(heardTool)) throw new Exception("A direct request still needs a brain: " + wording);
                    if (expected == "use_computer" && heardArgs.Task != wording) throw new Exception("A question job lost their wording.");
                    if (expected == "play_music" && heardArgs.App == "spotify" && CursorJob(heardTool, heardArgs) != null) throw new Exception("Spotify took a clicking detour.");
                }
                foreach (string conversation in conversations)
                    if (Hands.Heard(conversation, out heardTool, out heardArgs) || Hands.Wants(conversation)) throw new Exception("Conversation became a job: " + conversation);
                if (Hands.Heard("search youtube for cats and open spotify", out heardTool, out heardArgs) || Hands.Heard("find example.com", out heardTool, out heardArgs) && heardTool == "find_file") throw new Exception("A direct route swallowed a second action or mistook a website for a file.");
                foreach (string webSearch in new[] { "search for cat videos", "look for funny pictures", "find cheap flights" })
                    if (Hands.Heard(webSearch, out heardTool, out heardArgs) && heardTool == "find_file") throw new Exception("A web search became a file search: " + webSearch);
                foreach (string pcSearch in new[] { "where's my homework folder", "look for tax return on my pc", "find my videos folder" })
                    if (!Hands.Heard(pcSearch, out heardTool, out heardArgs) || heardTool != "find_file") throw new Exception("A search of this PC went elsewhere: " + pcSearch);
                if (Hands.Heard("wanna play something", out heardTool, out heardArgs)) throw new Exception("Wanna play something picked a song: " + heardTool);
                if (Hands.Heard("remember my score is 12.5", out heardTool, out heardArgs) && heardTool == "website_nickname") throw new Exception("A note became a website nickname.");
                checks.Add("PASS suggestions and screen questions: every reported ask routes through Heard, Wants and Direct; ordinary conversation stays chat, quizzes use a normal job, and opening apps, sites and music works without a brain");

                System.Collections.Generic.List<string> launches = new System.Collections.Generic.List<string>();
                int playClicks = 0, musicFetches = 0;
                Hands.Run = delegate(string launched) { launches.Add(launched); };
                Hands.Fetch = delegate { musicFetches++; return "<a href=\"https://open.spotify.com/track/0VjIjW4GlUZAMYd2vXMi3b\">Blinding Lights by The Weeknd</a>"; };
                Hands.SongPlaying = delegate { return true; };
                Hands.PressPlay = delegate { playClicks++; return true; };
                System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> picked = new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>>();
                picked.Add(new System.Collections.Generic.KeyValuePair<string, ToolArguments>("use_computer", new ToolArguments { Task = "open spotify and play Blinding Lights" }));
                Hands.Rescue("open spotify and play Blinding Lights", picked);
                if (picked.Count != 1 || picked[0].Key != "play_music") throw new Exception("The brain's clicking choice was not corrected.");
                foreach (string[] filed in new[]
                {
                    new[] { "play this round with me", "this round with me", "use_computer" },
                    new[] { "play my minecraft world", "my minecraft world", "use_computer" },
                    new[] { "play that", "that", "use_computer" },
                    new[] { "play solitaire", "solitaire", "use_computer" },
                    new[] { "play this chess match with me", "this chess match with me", "mini_game" },
                    new[] { "play that", "Neon Nights", "play_music" },
                    new[] { "play video games by lana del rey", "Video Games", "play_music" },
                    new[] { "play stay with me", "stay with me", "play_music" },
                    new[] { "play mike up and make some new friends", "Mike Up", "use_computer" }
                })
                {
                    picked.Clear();
                    picked.Add(new System.Collections.Generic.KeyValuePair<string, ToolArguments>("play_music", new ToolArguments { Song = filed[1] }));
                    Hands.Rescue(filed[0], picked);
                    if (picked.Count != 1 || picked[0].Key != filed[2]) throw new Exception("\"" + filed[0] + "\" filed under music as \"" + filed[1] + "\" ended up as " + (picked.Count == 0 ? "nothing" : picked[0].Key) + ".");
                }
                // Lachy, 6 Nov: "play Mic Up and make some new friends" was typed whole into Spotify, again. With a brain to ask, "play"
                // goes straight to music only when it's clearly music, and Mic Up, however her ears spell it, is a Roblox game.
                foreach (string notMusic in new[] { "Hey Capri, play Mike Up and make some new friends.", "play mic up", "play the floor is lava and make some new friends", "play hide and seek with me", "play tag with some randoms", "Hey Capri, play Balloons Tower Defense 6.", "play blinding lights" })
                    if (Hands.Heard(notMusic, out heardTool, out heardArgs, true) && heardTool == "play_music") throw new Exception("With a brain to ask, a game went to Spotify: " + notMusic);
                foreach (string clearlyMusic in new[] { "play some music", "play lofi beats on spotify", "play songs by the weeknd", "play my driving playlist" })
                    if (!Hands.Heard(clearlyMusic, out heardTool, out heardArgs, true) || heardTool != "play_music") throw new Exception("With a brain to ask, music stopped going straight to music: " + clearlyMusic + " went to " + heardTool);
                if (Hands.Heard("play mike up and make some new friends", out heardTool, out heardArgs) && heardTool == "play_music") throw new Exception("Mic Up went to Spotify with no brain to ask.");
                if (!Hands.Heard("play stay with me", out heardTool, out heardArgs) || heardTool != "play_music") throw new Exception("With no brain to ask, a short title stopped going to music.");
                string asideTool;
                ToolArguments asideArgs;
                if (Asides.Plain("play the floor is lava and make some new friends", out asideTool, out asideArgs, true) == AsideKind.Tool) throw new Exception("Mid-job, a game ask ran as a song beside the job.");
                if (!Computer.Gaming("hop on mike up for a bit")) throw new Exception("A Mic Up job wasn't a game job.");
                checks.Add("PASS with a brain to ask, play goes straight to music only when it's clearly music, before her brain, after its pick and mid-job, and Mic Up or Mike Up is a Roblox game (Lachy, 6 Nov)");
                // A brain that opens Spotify's web player for someone with the app gets the app (Bende, 3 Nov).
                foreach (string[] spotifyWeb in new[]
                {
                    new[] { "can you open spotify for me", "https://open.spotify.com", "", "open_app" },
                    new[] { "i wanna listen to lofi beats on my spotify app", "open.spotify.com", "lofi beats", "play_music" },
                    new[] { "search the spotify website for lofi beats", "https://open.spotify.com/", "lofi beats", "open_website" },
                    new[] { "search the spotify website for the song blinding lights", "https://open.spotify.com", "Blinding Lights", "open_website" }
                })
                {
                    picked.Clear();
                    picked.Add(new System.Collections.Generic.KeyValuePair<string, ToolArguments>("open_website", new ToolArguments { Site = spotifyWeb[1], Search = spotifyWeb[2].Length == 0 ? null : spotifyWeb[2] }));
                    Hands.Rescue(spotifyWeb[0], picked);
                    if (picked.Count != 1 || picked[0].Key != spotifyWeb[3]) throw new Exception("\"" + spotifyWeb[0] + "\" with Spotify's web player picked ended up as " + (picked.Count == 0 ? "nothing" : picked[0].Key) + ".");
                }
                string musicResult = Hands.Do("use_computer", new ToolArguments { Task = "play Blinding Lights on spotify" });
                if (!musicResult.StartsWith("Playing ", StringComparison.Ordinal) || launches.Count != 1 || launches[0] != "spotify:track:0VjIjW4GlUZAMYd2vXMi3b" || playClicks != 0) throw new Exception("A known track clicked or opened a browser.");
                int beforePrivate = musicFetches;
                Hands.Do("play_music", new ToolArguments { Song = "my driving", Kind = "playlist", App = "spotify" });
                if (musicFetches != beforePrivate || launches[launches.Count - 1] != "spotify:search:driving" || playClicks != 1) throw new Exception("An own playlist used a public URI or repeated Play.");
                string similarSongs = "<a href=\"https://open.spotify.com/track/1111111111111111111111\">Blinding Lights by Someone Else</a><a href=\"https://open.spotify.com/track/2222222222222222222222\">Blinding Lights by The Weeknd</a>";
                if (Hands.SpotifyLink(similarSongs, "song", "Blinding Lights by The Weeknd") != "2222222222222222222222") throw new Exception("A same-name song hid the requested artist.");
                for (int musicSpec = 0; musicSpec < Hands.Count; musicSpec++)
                    if (Hands.Name(musicSpec) == "play_music" && !Hands.ElevenLabsTool(musicSpec).Contains("\"response_timeout_secs\":60")) throw new Exception("Spotify's playback wait outlasts its voice tool.");
                // ElevenLabs turns down a whole tool over one parameter with no description, and voice chat can't open without her tools.
                for (int voiceSpec = 0; voiceSpec < Hands.Count; voiceSpec++)
                    if (System.Text.RegularExpressions.Regex.IsMatch(Hands.ElevenLabsTool(voiceSpec), "\"\\w+\":\\{\"type\":\"(?:string|number|integer|boolean)\"(?![^{}]*\"description\":\"[^\"])"))
                        throw new Exception("ElevenLabs would refuse " + Hands.Name(voiceSpec) + ": one of its parameters has no description.");
                ToolArguments desired = new ToolArguments { Song = "Blinding Lights by The Weeknd", Kind = "song", App = "spotify" };
                Tune requestedTune = new Tune { Title = "Blinding Lights", Artist = "The Weeknd", App = "Spotify.exe", Playing = true };
                if (!Hands.Started(desired, requestedTune, requestedTune) || Hands.Started(desired, null, new Tune { Title = "Blinding Lights", Artist = "The Weeknd", App = "Spotify.exe", Playing = false }) || Hands.Started(desired, null, new Tune { Title = "Blinding Lights", Artist = "Someone Else", App = "Spotify.exe", Playing = true }) || Hands.Started(desired, null, new Tune { Title = "Blinding Lights", Artist = "The Weeknd", App = "chrome", Playing = true })) throw new Exception("Playback used a title without its playing state, artist or app.");
                if (!Hands.Started(new ToolArguments { Song = "blinding lights the weeknd", Kind = "song" }, null, requestedTune)) throw new Exception("A song named with its artist never counted as playing.");
                int quietClicks = playClicks;
                Hands.SongPlaying = delegate { return false; };
                string unstarted = Hands.Do("play_music", new ToolArguments { Song = "Blinding Lights", Kind = "song", App = "spotify" });
                if (playClicks != quietClicks + 1 || !unstarted.StartsWith("Playing ", StringComparison.Ordinal)) throw new Exception("A track that didn't start by itself never got its Play pressed: " + unstarted);
                Hands.SongPlaying = delegate { return true; };
                checks.Add("PASS Spotify: direct and brain-picked music stays play_music, a track that's playing is left alone, a track that didn't start gets one Play, own playlists search Spotify once, and playing means Spotify's own session with the title and artist; paused, wrong-artist and other-app sessions don't count");
                checks.Add("LIMIT live Spotify playback and personal playlist controls: URI launches, Play and Windows media sessions use stand-ins here");

                string fixture = Path.Combine(folder, Guid.NewGuid().ToString("N"));
                try { Directory.CreateDirectory(fixture); File.WriteAllText(Path.Combine(fixture, "writable.txt"), "names only"); }
                catch (IOException) { checks.Add("LIMIT website and file fixtures: the smoke folder isn't writable"); return; }
                catch (UnauthorizedAccessException) { checks.Add("LIMIT website and file fixtures: the smoke folder isn't writable"); return; }
                Hands.Websites = new Websites(fixture);
                Hands.Websites.Current = delegate { return "https://example.com/current"; };
                foreach (string remembering in new[] { "remember this website as apples", "call this site apples", "remember apples is example.com/page", "Capri, please remember this website that I am currently on as 'apples'" })
                {
                    if (!Hands.Heard(remembering, out heardTool, out heardArgs) || heardTool != "website_nickname" || !Hands.Wants(remembering) || !Hands.Valid(heardTool, heardArgs)) throw new Exception("Website saving routed wrong: " + remembering);
                    if (!Hands.Do(heardTool, heardArgs).StartsWith("I'll remember apples as https://example.com/", StringComparison.Ordinal)) throw new Exception("Website nickname was not saved.");
                }
                Hands.Websites = new Websites(fixture);
                if (Hands.Websites.Find("APPLES") != "https://example.com/current") throw new Exception("Website nicknames did not survive reload.");
                Hands.BrowserPath = delegate { return "chrome.exe"; };
                Hands.Browse = delegate(string browserPath, string address) { launches.Add(browserPath + " " + address); };
                Hands.Opened = delegate { return ""; };
                foreach (string opening in new[] { "open apples", "check out the apples website", "go to apples", "take me to apples", "open apples in chrome", "capri can you check out the apples website" })
                {
                    if (!Hands.Heard(opening, out heardTool, out heardArgs) || heardTool != "open_website" || heardArgs.Site != "apples" || !Hands.Wants(opening)) throw new Exception("Website opening routed wrong: " + opening);
                    Hands.Do(heardTool, heardArgs);
                    if (!launches[launches.Count - 1].EndsWith("https://example.com/current", StringComparison.Ordinal)) throw new Exception("A nickname became a search.");
                    if (opening.EndsWith("in chrome", StringComparison.Ordinal) && launches[launches.Count - 1] != "chrome.exe https://example.com/current") throw new Exception("A nickname lost the named browser.");
                }
                if (Hands.Heard("open apples pie", out heardTool, out heardArgs) || !Hands.Heard("google apples pie", out heardTool, out heardArgs) || heardArgs.Search != "apples pie") throw new Exception("A nickname took over part of a target or a search.");
                Hands.Websites.Current = delegate { return null; };
                if (!Hands.Websites.Do(new ToolArguments { Action = "save", Name = "missing" }).StartsWith("I couldn't read that browser's address.", StringComparison.Ordinal) || new Websites(fixture).Find("missing") != null) throw new Exception("An unreadable address was guessed.");
                if (!Hands.Heard("what websites do you know", out heardTool, out heardArgs) || !Hands.Do(heardTool, heardArgs).Contains("apples: https://example.com/current")) throw new Exception("Saved websites were not listed.");
